const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={view:'overview',sites:[],employees:[],ppe:null,ppeHistory:[],obligations:[],legalReviews:[],legalSources:[],legalUpdates:[],legalWatch:null,payments:[],equipment:[],documents:[],tasks:[],notifications:[],extractions:[],users:[],user:null,permissions:[]};
const meta={myday:['My Day','Việc cần làm hôm nay · ưu tiên · evidence · data quality'],inbox:['Inbox','Một nơi xử lý file mới · OCR · approval · legal review'],calendar:['EHS Calendar','Deadline Compliance · Task · Payment · Kiểm định'],auditprep:['Audit Mode','Chuẩn bị thanh tra · gap hồ sơ · evidence coverage · audit pack'],reports:['Báo cáo & KPI','Form báo cáo tuần · báo cáo tháng · KPI EHS · xuất Excel'],overview:['Overview','EHS Command Center'],compliance:['Compliance','Kế hoạch EHS · nghĩa vụ · legal review · deadline'],documents:['Documents','Tủ hồ sơ · truy xuất theo category · OCR · metadata · link nghiệp vụ'],ppe:['PPE','Kho BHLĐ · tồn kho · lịch sử nhập/xuất · chi phí'],equipment:['Thiết bị kiểm định','Asset register · kiểm định · hạn hiệu lực'],payments:['Payments','Tracking hồ sơ thanh toán EHS — không phải kế toán'],tasks:['Tasks','Nhắc việc · tiến độ · công việc lặp hàng ngày/tuần/tháng'],notifications:['Alerts','Cảnh báo · escalation · overdue · legal review'],employees:['Employees','Employee Master · bộ phận · trạng thái'],audit:['Audit','Lịch sử thao tác không ghi đè'],users:['Users & Roles','RBAC · tài khoản · phân quyền'],system:['System','Backup · restore validation · health controls']};
let authBusy=false;
const rawFetch=async(path,opts={})=>fetch(path,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});
const api=async(path,opts={})=>{const r=await rawFetch(path,opts);const j=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&!authBusy)showLogin();if(j.error==='PASSWORD_CHANGE_REQUIRED'&&!authBusy)forcePasswordChange();const e=new Error(j.error||`HTTP ${r.status}`);e.code=j.error;e.permission=j.permission;throw e}return j};
const exportScopeByView={overview:'all',employees:'employees',ppe:'ppe',compliance:'compliance',documents:'documents',payments:'payments',equipment:'equipment',tasks:'tasks',notifications:'notifications',audit:'audit'};
async function downloadExcel(scope,triggerBtn=null){const btn=triggerBtn||$('#exportExcelBtn'),original=btn?.textContent||'⇩ Xuất Excel';if(btn){btn.disabled=true;btn.textContent='Đang xuất…'}try{const r=await fetch(`/api/export/excel?scope=${encodeURIComponent(scope)}`);if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||`HTTP ${r.status}`)}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const cd=r.headers.get('content-disposition')||'';a.download=(cd.match(/filename="?([^";]+)"?/)?.[1]||`VIETCHEM_EHS_${scope}.xlsx`);document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Đã xuất Excel')}catch(e){toast(e.message,true)}finally{if(btn){btn.disabled=false;btn.textContent=original}}}
function configureExportButton(){const b=$('#exportExcelBtn'),scope=exportScopeByView[state.view];if(!b)return;b.hidden=!scope;b.dataset.scope=scope||'';}
const fmtDate=d=>d?new Intl.DateTimeFormat('vi-VN').format(new Date(d+'T00:00:00')):'—';
const fmtMoney=n=>n==null?'—':new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const days=d=>d?Math.ceil((new Date(d+'T23:59:59')-new Date())/86400000):null;
const monthName=m=>m?`T${m}`:'—';
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pill(text,type='gray'){return `<span class="pill ${type}">${esc(text)}</span>`}
function toast(msg,err=false){$('#toast').innerHTML=`<div class="toast ${err?'err':''}">${esc(msg)}</div>`;setTimeout(()=>$('#toast').innerHTML='',3000)}
function can(p){return !!state.user&&(state.permissions.includes('*')||state.permissions.includes(p))}
function modal(title,body,onSave,save='Lưu'){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><strong>${esc(title)}</strong><button class="x">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="ghost cancel">Hủy</button><button class="primary save">${esc(save)}</button></div></div></div>`;const close=()=>$('#modalRoot').innerHTML='';$('.x').onclick=$('.cancel').onclick=close;$('.save').onclick=async()=>{try{await onSave(close)}catch(e){toast(e.message,true)}}}
function showLogin(){state.user=null;state.permissions=[];$('#shell').hidden=true;$('#loginScreen').hidden=false;$('#loginPass').value='';}
async function enterApp(){authBusy=true;try{const me=await api('/api/auth/me');state.user=me.user;state.permissions=me.permissions||[];$('#loginScreen').hidden=true;$('#shell').hidden=false;$('#userName').textContent=state.user.display_name||state.user.username;$('#userRole').textContent=state.user.role;configureNav();await loadBase();const asset=new URLSearchParams(location.search).get('asset');await navigate(asset?'equipment':'myday')}finally{authBusy=false}}
function configureNav(){$$('#nav button').forEach(b=>{b.hidden=!can(b.dataset.perm)});$('#quickTaskBtn').hidden=!can('tasks.write');if($('#quickCaptureBtn'))$('#quickCaptureBtn').hidden=!(can('tasks.write')||can('documents.write'))}
function forcePasswordChange(){if($('#modalRoot .password-force'))return;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal password-force"><div class="modal-head"><strong>Đổi mật khẩu lần đầu</strong></div><div class="modal-body"><div class="notice">Mật khẩu bootstrap chỉ dùng cho lần đăng nhập đầu tiên.</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Mật khẩu hiện tại</label><input id="oldPw" type="password"></div><div class="field full"><label>Mật khẩu mới (≥10 ký tự)</label><input id="newPw" type="password"></div><div class="field full"><label>Nhập lại mật khẩu mới</label><input id="newPw2" type="password"></div></div></div><div class="modal-foot"><button class="primary savePw">Đổi mật khẩu</button></div></div></div>`;$('.savePw').onclick=async()=>{try{if($('#newPw').value!==$('#newPw2').value)throw new Error('Mật khẩu nhập lại không khớp');await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({old_password:$('#oldPw').value,new_password:$('#newPw').value})});$('#modalRoot').innerHTML='';toast('Đã đổi mật khẩu');await enterApp()}catch(e){toast(e.message,true)}}}
async function boot(){authBusy=true;try{const r=await rawFetch('/api/auth/me');if(r.ok){const j=await r.json();state.user=j.user;state.permissions=j.permissions||[];if(state.user.must_change_password){$('#loginScreen').hidden=true;$('#shell').hidden=true;forcePasswordChange()}else await enterApp()}else showLogin()}finally{authBusy=false}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();authBusy=true;$('#loginError').textContent='';try{const out=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('#loginUser').value,password:$('#loginPass').value})});state.user=out.user;if(out.user.must_change_password){$('#loginScreen').hidden=true;forcePasswordChange()}else await enterApp()}catch(err){$('#loginError').textContent=err.message;$('#loginScreen').hidden=false}finally{authBusy=false}};
$('#logoutBtn').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}showLogin()};
async function loadBase(){state.sites=await api('/api/sites')}
async function navigate(view){const btn=$(`#nav button[data-view="${view}"]`);if(btn?.hidden)return;state.view=view;$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pageTitle').textContent=meta[view][0];$('#pageSubtitle').textContent=meta[view][1];configureExportButton();await render()}
$$('#nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#refreshBtn').onclick=()=>render();$('#quickTaskBtn').onclick=()=>quickTask();$('#exportExcelBtn').onclick=()=>{const scope=$('#exportExcelBtn').dataset.scope;if(scope)downloadExcel(scope)};
function applyPermissionUI(){const hide=(sel,p)=>{$$(sel).forEach(x=>x.hidden=!can(p))};hide('#addEmployee,.toggleEmp','employees.write');hide('#issuePPE','ppe.issue');hide('#adjustPPE,#managePpeTypes,.ppeHistEdit','ppe.adjust');hide('.changeDeadline','compliance.request_deadline');hide('.legalResolve,.resolveLegalUpdate','legal.review');hide('#drop,#docImportTools','documents.write');hide('.docProcess','documents.process');hide('.docReview,.docMeta','documents.review');hide('.editPayment,.docToggle','payments.write');hide('#addEq,.eqInspect,.eqEdit,.eqReconcile','equipment.write');hide('#addTask,.notifRefresh','tasks.write');hide('.legalWatchRun','legal.review');hide('.quickEvidence','documents.write')}
async function render(){const app=$('#app');app.innerHTML='<div class="card empty">Đang tải…</div>';try{if(state.view==='myday')await myDay();else if(state.view==='inbox')await inboxView();else if(state.view==='calendar')await calendarView();else if(state.view==='auditprep')await auditPrepView();else if(state.view==='reports')await reportCenterView();else if(state.view==='overview')await overview();else if(state.view==='employees')await employees();else if(state.view==='ppe')await ppe();else if(state.view==='compliance')await compliance();else if(state.view==='documents')await documents();else if(state.view==='payments')await payments();else if(state.view==='equipment')await equipment();else if(state.view==='tasks')await tasks();else if(state.view==='notifications')await notifications();else if(state.view==='audit')await audit();else if(state.view==='users')await users();else if(state.view==='system')await systemView();applyPermissionUI()}catch(e){app.innerHTML=`<div class="card empty">${esc(e.message)}</div>`}}

function kpi(label,val,sub,accent){return `<div class="card kpi" style="--accent:${accent}"><label>${esc(label)}</label><strong>${val}</strong><small>${esc(sub)}</small></div>`}
async function overview(){const [d,stats]=await Promise.all([api('/api/dashboard'),api('/api/source-stats')]);state.obligations=await api('/api/obligations');state.payments=await api('/api/payments');state.equipment=await api('/api/equipment');$('#app').innerHTML=`<div class="grid kpis">${kpi('Overdue',d.overdue,'Nghĩa vụ có deadline','#fff0f1')}${kpi('Due 30 days',d.due30,'Sắp đến hạn','#fff6e2')}${kpi('PPE negative',d.ppeNegative,'Cần reconciliation','#fff0f1')}${kpi('Payment overdue',d.payOver,'Theo hợp đồng','#fff0f1')}${kpi('Inspection 60d',d.equipDue,'Thiết bị sắp hạn','#edf2ff')}${kpi('Legal review',d.legalReview,'Cần EHS xác nhận','#f1edff')}${kpi('Alerts',d.notificationsUnread??0,'Unread / escalation','#fff6e2')}</div>
<div class="section grid two"><div class="card panel"><div class="section-head"><div><h2>Data foundation</h2><p>Dữ liệu thật đã import vào checkpoint này</p></div></div><div class="mini-stats"><div><b>${stats.employees}</b><span>Nhân sự</span></div><div><b>${stats.ppeItems}</b><span>PPE items</span></div><div><b>${stats.planObligations}</b><span>Kế hoạch EHS</span></div><div><b>${stats.legalReview}</b><span>Legal review</span></div></div></div><div class="card panel"><div class="section-head"><div><h2>Attention</h2><p>Việc cần nhìn ngay</p></div></div><div class="list">${attention(state.payments,state.equipment,d)}</div></div></div>
<div class="section"><div class="card panel"><div class="section-head"><div><h2>Upcoming compliance</h2><p>Các obligation có deadline cụ thể</p></div></div><div class="list">${state.obligations.filter(o=>o.current_due_date).slice(0,8).map(listOb).join('')||'<div class="empty">Chưa có obligation có deadline</div>'}</div></div></div>`}
function listOb(o){const n=days(o.current_due_date),p=n<0?pill(`Quá ${-n} ngày`,'red'):n<=14?pill(`${n} ngày`,'amber'):pill(fmtDate(o.current_due_date),'blue');return `<div class="list-row"><div><div class="titleline">${esc(o.title)}</div><div class="sub">${esc(o.category)} · ${esc(o.site_code||'—')} · ${esc(o.owner||'—')}</div></div>${p}</div>`}
function attention(payments,equipment,d){let x=[];if(d.legalReview)x.push(`<div class="list-row"><div><div class="titleline">Legal review queue</div><div class="sub">Kế hoạch có căn cứ cần rà lại</div></div>${pill(`${d.legalReview} mục`,'violet')}</div>`);if(d.ppeNegative)x.push(`<div class="list-row"><div><div class="titleline">PPE âm kho</div><div class="sub">Cho phép xuất nhưng cần đối chiếu</div></div>${pill(`${d.ppeNegative} item`,'red')}</div>`);for(const p of payments){const n=days(p.contractual_due_date);if(p.status!=='paid'&&n<0)x.push(`<div class="list-row"><div><div class="titleline">${esc(p.vendor_name)}</div><div class="sub">${esc(p.title)}</div></div>${pill(`Payment +${-n}d`,'red')}</div>`)}for(const e of equipment){const n=days(e.next_inspection_date);if(n!=null&&n<=60)x.push(`<div class="list-row"><div><div class="titleline">${esc(e.asset_code)} · ${esc(e.name)}</div><div class="sub">${esc(e.location||'—')}</div></div>${n<0?pill(`Hết hạn ${-n}d`,'red'):pill(`${n} ngày`,'amber')}</div>`)}return x.slice(0,8).join('')||'<div class="empty">Không có cảnh báo nổi bật</div>'}

async function employees(){const q=$('#empQ')?.value||'',site=$('#empSite')?.value||'',status=$('#empStatus')?.value||'active';state.employees=await api(`/api/employees?q=${encodeURIComponent(q)}&site=${encodeURIComponent(site)}&status=${encodeURIComponent(status)}`);$('#app').innerHTML=`<div class="toolbar"><input id="empQ" placeholder="Tìm tên / mã / bộ phận" value="${esc(q)}"><select id="empSite"><option value="">Tất cả site</option>${state.sites.map(s=>`<option value="${s.code}" ${site===s.code?'selected':''}>${s.code}</option>`).join('')}</select><select id="empStatus"><option value="active" ${status==='active'?'selected':''}>Active</option><option value="inactive" ${status==='inactive'?'selected':''}>Inactive</option><option value="" ${status===''?'selected':''}>Tất cả</option></select><button class="primary" id="addEmployee">+ Nhân viên</button><span class="muted">${state.employees.length} kết quả</span></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Họ tên</th><th>Bộ phận</th><th>Vị trí</th><th>Site</th><th>Trạng thái</th><th></th></tr></thead><tbody>${state.employees.map(e=>`<tr><td>${esc(e.employee_code||'—')}</td><td><b>${esc(e.full_name)}</b></td><td>${esc(e.department||'—')}</td><td>${esc(e.job_title||'—')}</td><td>${esc(e.site_code||'—')}</td><td>${e.status==='active'?pill('Active','green'):pill('Inactive','gray')}</td><td><button class="ghost toggleEmp" data-id="${e.id}" data-status="${e.status==='active'?'inactive':'active'}">${e.status==='active'?'Ngừng':'Kích hoạt'}</button></td></tr>`).join('')}</tbody></table></div>`;$('#addEmployee').onclick=addEmployee;$('#empQ').onchange=$('#empSite').onchange=$('#empStatus').onchange=()=>employees();$$('.toggleEmp').forEach(b=>b.onclick=async()=>{await api('/api/employees/status',{method:'PATCH',body:JSON.stringify({id:b.dataset.id,status:b.dataset.status})});toast('Đã cập nhật trạng thái');employees()})}
function addEmployee(){modal('Thêm nhân viên',`<div class="form-grid"><div class="field"><label>Mã NV</label><input id="fCode"></div><div class="field"><label>Họ tên *</label><input id="fName"></div><div class="field"><label>Bộ phận</label><input id="fDept"></div><div class="field"><label>Vị trí</label><input id="fJob"></div><div class="field"><label>Site</label><select id="fSite">${state.sites.map(s=>`<option value="${s.id}">${s.code} · ${s.name}</option>`)}</select></div></div>`,async close=>{await api('/api/employees',{method:'POST',body:JSON.stringify({employee_code:$('#fCode').value,full_name:$('#fName').value,department:$('#fDept').value,job_title:$('#fJob').value,site_id:$('#fSite').value})});close();toast('Đã thêm nhân viên');employees()})}

async function ppe(){
  state.employees=await api('/api/employees?status=active');state.ppe=await api('/api/ppe');
  const neg=state.ppe.items.filter(i=>Number(i.current_stock)<0).length,zero=state.ppe.items.filter(i=>Number(i.current_stock)===0).length,low=state.ppe.items.filter(i=>Number(i.current_stock)<=Number(i.min_stock)).length,totalStock=state.ppe.items.reduce((a,i)=>a+Number(i.current_stock||0),0);
  $('#app').innerHTML=`<div class="grid ppe-kpis">${kpi('Tổng mặt hàng',state.ppe.items.length,'PPE master','#edf2ff')}${kpi('Tổng tồn',new Intl.NumberFormat('vi-VN').format(totalStock),'Theo tồn hệ thống','#eaf8f2')}${kpi('Low stock',low,'≤ min stock','#fff6e2')}${kpi('Âm kho',neg,'Cần reconciliation','#fff0f1')}${kpi('Hết hàng',zero,'Vẫn cho xuất','#f1edff')}</div>
  <div class="toolbar ppe-toolbar"><button class="primary" id="issuePPE">+ Xuất PPE</button><button class="ghost" id="adjustPPE">Nhập / điều chỉnh</button><button class="ghost" id="managePpeTypes">⚙ Loại PPE</button><input id="ppeQ" placeholder="Tìm PPE / SKU"><span class="muted">${state.ppe.items.length} mặt hàng · ${neg} âm kho</span></div>
  <div class="ppe-inventory-full"><div class="top-scroll" id="ppeTopScroll"><div></div></div><div class="table-wrap ppe-table-wrap" id="ppeTableWrap"><table class="ppe-table"><thead><tr><th>SKU</th><th>PPE</th><th>Tồn hiện tại</th><th>ĐVT</th><th>Min stock</th><th>Đơn giá tham chiếu</th></tr></thead><tbody id="ppeRows">${ppeRows(state.ppe.items)}</tbody></table></div></div>
  <details class="card ppe-history" id="ppeHistoryDetails"><summary><div><b>Lịch sử nhập/xuất PPE</b><span>Theo dõi toàn bộ biến động tồn kho</span></div><span class="history-chevron">⌄</span></summary><div class="ppe-history-body"><div class="toolbar"><input id="ppeHistQ" placeholder="Tìm PPE / người nhận / bộ phận / lý do"><select id="ppeHistType"><option value="">Tất cả giao dịch</option><option value="IN">Nhập kho</option><option value="OUT">Xuất PPE</option><option value="ADJUSTMENT">Điều chỉnh giảm</option><option value="OPENING_IMPORT">Tồn đầu kỳ</option></select><button class="ghost" id="exportPpeHistory">⇩ Xuất Excel lịch sử</button><span class="muted" id="ppeHistCount">Mở để tải lịch sử</span></div><div class="table-wrap ppe-history-table-wrap"><table class="ppe-history-table"><thead><tr><th>Thời gian</th><th>Loại</th><th>SKU</th><th>PPE</th><th>SL</th><th>Tồn trước</th><th>Tồn sau</th><th>Người nhận</th><th>Bộ phận</th><th>Lý do</th><th>Người thao tác</th></tr></thead><tbody id="ppeHistoryRows"><tr><td colspan="11" class="empty">Mở mục này để xem lịch sử nhập/xuất</td></tr></tbody></table></div></div></details>`;
  $('#issuePPE').onclick=issuePPE;$('#adjustPPE').onclick=adjustPPE;$('#managePpeTypes').onclick=managePpeTypes;$('#ppeQ').oninput=e=>$('#ppeRows').innerHTML=ppeRows(state.ppe.items.filter(x=>x.name.toLowerCase().includes(e.target.value.toLowerCase())||x.sku.toLowerCase().includes(e.target.value.toLowerCase())));
  const top=$('#ppeTopScroll'),wrap=$('#ppeTableWrap'),sync=()=>{top.firstElementChild.style.width=wrap.scrollWidth+'px'};sync();top.onscroll=()=>{wrap.scrollLeft=top.scrollLeft};wrap.onscroll=()=>{top.scrollLeft=wrap.scrollLeft};
  const details=$('#ppeHistoryDetails');details.ontoggle=()=>{if(details.open)loadPpeHistory()};$('#ppeHistType').onchange=()=>loadPpeHistory();let histTimer;$('#ppeHistQ').oninput=()=>{clearTimeout(histTimer);histTimer=setTimeout(loadPpeHistory,220)};$('#exportPpeHistory').onclick=e=>{e.preventDefault();e.stopPropagation();downloadExcel('ppe-ledger',$('#exportPpeHistory'))};
}
function ppeTxLabel(type){return ({IN:'Nhập kho',OUT:'Xuất PPE',REVERSAL:'Hoàn kho sửa sai',ADJUSTMENT:'Điều chỉnh',OPENING_IMPORT:'Tồn đầu kỳ'})[type]||type||'—'}
function ppeHistoryRows(rows){return rows.map(t=>`<tr><td>${new Date(t.created_at).toLocaleString('vi-VN')}</td><td>${pill(ppeTxLabel(t.type),t.type==='OUT'?'blue':t.type==='IN'?'green':t.type==='ADJUSTMENT'?'amber':'gray')}</td><td>${esc(t.sku||'—')}</td><td><b>${esc(t.item_name||'—')}</b></td><td>${new Intl.NumberFormat('vi-VN').format(Number(t.quantity||0))}</td><td>${new Intl.NumberFormat('vi-VN').format(Number(t.stock_before||0))}</td><td>${Number(t.stock_after)<0?pill(t.stock_after,'red'):esc(new Intl.NumberFormat('vi-VN').format(Number(t.stock_after||0)))}</td><td>${esc(t.employee_name||'—')}</td><td>${esc(t.department||'—')}</td><td>${esc(t.reason||'—')}</td><td>${esc(t.actor||'—')}</td></tr>`).join('')||'<tr><td colspan="11" class="empty">Không có giao dịch phù hợp</td></tr>'}
async function loadPpeHistory(){const q=$('#ppeHistQ')?.value||'',type=$('#ppeHistType')?.value||'';$('#ppeHistoryRows').innerHTML='<tr><td colspan="15" class="empty">Đang tải lịch sử…</td></tr>';try{state.ppeHistory=await api(`/api/ppe/history?type=${encodeURIComponent(type)}&q=${encodeURIComponent(q)}&limit=1000`);$('#ppeHistoryRows').innerHTML=ppeHistoryRows(state.ppeHistory);$('#ppeHistCount').textContent=`${state.ppeHistory.length} giao dịch`;$$('.ppeHistEdit').forEach(b=>b.onclick=()=>editPpeIssueHistory(b.dataset.id));applyPermissionUI();}catch(e){$('#ppeHistoryRows').innerHTML=`<tr><td colspan="15" class="empty">${esc(e.message)}</td></tr>`}}

function ppeRows(items){return items.map(i=>`<tr><td>${esc(i.sku)}</td><td><b>${esc(i.name)}</b></td><td>${Number(i.current_stock)<0?pill(i.current_stock,'red'):Number(i.current_stock)<=Number(i.min_stock)?pill(i.current_stock,'amber'):pill(i.current_stock,'green')}</td><td>${esc(i.unit)}</td><td>${i.min_stock??'—'}</td><td>${i.unit_price?fmtMoney(i.unit_price):'—'}</td></tr>`).join('')}
function employeeChoiceLabel(e,all){const same=all.filter(x=>String(x.full_name||'').trim().toLowerCase()===String(e.full_name||'').trim().toLowerCase());return same.length>1?`${e.full_name} — ${e.department||e.site_code||'Không rõ BP'}`:e.full_name}
function issuePPE(){const active=state.employees;modal('Xuất PPE',`<div class="form-grid"><div class="field full"><label>Người nhận *</label><select id="ppeEmp">${active.map(e=>`<option value="${e.id}">${esc(employeeChoiceLabel(e,active))}</option>`)}</select><div id="ppeEmpInfo" class="selected-person"></div></div><div class="field full"><label>Hàng cần xuất</label><div class="ppe-lines" id="ppeLines">${ppeLine()}</div><button class="soft" type="button" id="addLine">+ Thêm mặt hàng</button></div><div class="field"><label>Lý do</label><select id="ppeReason"><option>Cấp mới</option><option>Cấp định kỳ</option><option>Hỏng</option><option>Mất</option><option>Thay thế</option><option>Khác</option></select></div><div class="field"><label>Ghi chú</label><input id="ppeNote"></div><div class="field full"><div class="notice">Tồn âm không khóa thao tác; hệ thống lưu discrepancy + audit để đối chiếu.</div></div></div>`,async close=>{const lines=$$('.ppe-line').map(r=>({item_id:$('.liItem',r).value,quantity:Number($('.liQty',r).value)}));const out=await api('/api/ppe/issue',{method:'POST',body:JSON.stringify({employee_id:$('#ppeEmp').value,lines,reason:$('#ppeReason').value,note:$('#ppeNote').value,actor:'EHS'})});close();toast(out.results.some(x=>x.negative_stock)?'Đã xuất · có mặt hàng âm kho':'Đã xuất PPE');ppe()});setTimeout(()=>{const renderPerson=()=>{const e=active.find(x=>x.id===$('#ppeEmp').value);$('#ppeEmpInfo').innerHTML=e?`<b>${esc(e.full_name)}</b><span>Mã NV: ${esc(e.employee_code||'—')}</span><span>Bộ phận: ${esc(e.department||'—')}</span><span>Vị trí: ${esc(e.job_title||'—')}</span><span>Site: ${esc(e.site_code||'—')}</span>`:''};$('#ppeEmp').onchange=renderPerson;renderPerson();$('#addLine').onclick=()=>{$('#ppeLines').insertAdjacentHTML('beforeend',ppeLine());wireRemove()};wireRemove()},0)}
function ppeLine(){return `<div class="ppe-line"><select class="liItem">${state.ppe.items.map(i=>`<option value="${i.id}">${esc(i.name)} · tồn ${i.current_stock}</option>`)}</select><input class="liQty" type="number" min="1" value="1"><button class="x rm" type="button">×</button></div>`}
function wireRemove(){$$('.rm').forEach(b=>b.onclick=()=>{if($$('.ppe-line').length>1)b.closest('.ppe-line').remove()})}
function adjustPPE(){modal('Nhập / điều chỉnh PPE',`<div class="form-grid"><div class="field full"><label>PPE</label><select id="adjItem">${state.ppe.items.map(i=>`<option value="${i.id}">${esc(i.name)} · tồn ${i.current_stock}</option>`).join('')}</select></div><div class="field"><label>Số lượng (+ nhập, - điều chỉnh)</label><input id="adjQty" type="number" value="1"></div><div class="field"><label>Đơn giá nhập/tham chiếu (VND)</label><input id="adjPrice" type="number" min="0" step="100"></div><div class="field full"><label>Lý do</label><input id="adjReason" value="Kiểm kê/nhập kho"></div><div class="field full"><div class="notice">Khi nhập kho (+), nếu điền đơn giá thì hệ thống cập nhật đơn giá tham chiếu. Khi cấp phát, đơn giá được chốt vào giao dịch để phân bổ chi phí không thay đổi về sau.</div></div></div>`,async close=>{await api('/api/ppe/adjust',{method:'POST',body:JSON.stringify({item_id:$('#adjItem').value,quantity:Number($('#adjQty').value),unit_price:$('#adjPrice').value===''?null:Number($('#adjPrice').value),reason:$('#adjReason').value,actor:'EHS'})});close();toast('Đã cập nhật tồn');ppe()});setTimeout(()=>{const fillPrice=()=>{const i=state.ppe.items.find(x=>x.id===$('#adjItem').value);$('#adjPrice').value=i?.unit_price??''};$('#adjItem').onchange=fillPrice;fillPrice()},0)}

async function compliance(){
  const site=$('#cSite')?.value||'',cat=$('#cCat')?.value||'',review=$('#cReview')?.value||'';
  const [obs,req,lr,lu,ls,lw,lwr]=await Promise.all([api(`/api/obligations?site=${site}&category=${cat}&review=${review}`),api('/api/deadline-requests'),api('/api/legal-reviews'),api('/api/legal-updates'),api('/api/legal-sources'),api('/api/legal-watch/status'),api('/api/legal-watch/runs')]);
  state.obligations=obs;state.legalReviews=lr;state.legalUpdates=lu;state.legalSources=ls;state.legalWatch={status:lw,runs:lwr};
  const activeLR=lr.filter(x=>x.status==='needs_review'),activeLU=lu.filter(x=>x.status==='needs_review');
  $('#app').innerHTML=`<div class="toolbar"><select id="cSite"><option value="">Tất cả site</option>${state.sites.map(s=>`<option value="${s.code}" ${site===s.code?'selected':''}>${s.code}</option>`).join('')}</select><select id="cCat"><option value="">Tất cả nhóm</option>${[['fire','PCCC'],['chemical','Hóa chất'],['environment','Môi trường'],['osh','ATVSLĐ'],['equipment','Kiểm định'],['food','Bếp/VSATTP'],['other','Khác']].map(x=>`<option value="${x[0]}" ${cat===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select id="cReview"><option value="">Tất cả review</option><option value="needs_review" ${review==='needs_review'?'selected':''}>Needs review</option><option value="reviewed" ${review==='reviewed'?'selected':''}>Reviewed</option></select><span class="muted">${obs.length} dòng kế hoạch</span></div>
  <div class="grid compliance-grid"><div class="table-wrap"><table><thead><tr><th>Site</th><th>STT</th><th>Hành động</th><th>Tháng</th><th>Owner</th><th>Type</th><th>Legal</th><th>Deadline</th><th></th></tr></thead><tbody>${obs.map(o=>`<tr><td>${esc(o.site_code||'—')}</td><td>${o.source_stt??'—'}</td><td><b>${esc(o.title)}</b><div class="sub">${esc(o.source_goal||'')}</div></td><td>${monthName(o.schedule_month)}</td><td>${esc(o.owner||'—')}</td><td>${pill(o.requirement_type,o.requirement_type==='LEGAL'?'violet':'teal')}</td><td>${o.legal_review_status==='needs_review'?pill('Review','amber'):o.legal_review_status==='reviewed'?pill('Reviewed','green'):pill('—','gray')}</td><td>${o.current_due_date?fmtDate(o.current_due_date):'<span class="muted">Theo tháng</span>'}</td><td>${o.current_due_date?`<button class="ghost changeDue" data-id="${o.id}">Đổi hạn</button>`:''}</td></tr>`).join('')}</tbody></table></div>
  <div class="stack"><div class="card panel legal-panel"><div class="section-head"><div><h2>Legal Update Inbox</h2><p>Official-source baseline → impact review</p></div>${pill(`${activeLU.length} cần review`,activeLU.length?'amber':'green')}</div><div class="list">${activeLU.map(x=>`<div class="legal-item"><div><b>${esc(x.code)}</b><div class="sub">${esc(x.category)} · hiệu lực ${fmtDate(x.effective_date)}</div><div class="sub">${esc(x.summary)}</div></div><button class="soft resolveLegalUpdate" data-id="${x.id}">Review</button></div>`).join('')||'<div class="empty">Không có cập nhật chờ review</div>'}</div></div>
  <div class="card panel legal-panel"><div class="section-head"><div><h2>Obligation Legal Review</h2><p>Không tự sửa căn cứ pháp lý</p></div>${pill(`${activeLR.length} cần review`,activeLR.length?'amber':'green')}</div><div class="list">${activeLR.slice(0,10).map(x=>`<div class="legal-item"><div><b>${esc(x.entity_title||x.entity_id)}</b><div class="sub">${esc(x.site_code||'—')} · ${esc(x.reason)}</div></div><button class="soft resolveLegal" data-id="${x.id}">Review</button></div>`).join('')||'<div class="empty">Không có mục chờ review</div>'}</div></div></div></div>
  <div class="section grid two"><div class="card panel"><div class="section-head"><div><h2>Legal Watch</h2><p>Daily official-source fingerprint watch · không tự sửa obligation</p></div>${pill(lw.enabled?'Scheduler ON':'Scheduler OFF',lw.enabled?'green':'amber')}</div><div class="toolbar"><button class="soft legalWatchRun" id="legalWatchRun">Kiểm tra nguồn ngay</button><span class="muted">${lwr[0]?`${esc(lwr[0].status)} · ${lwr[0].checked_count} nguồn · ${lwr[0].changed_count} thay đổi · ${lwr[0].error_count} lỗi`:'Chưa chạy'}</span></div><div class="list">${ls.slice(0,12).map(x=>`<div class="list-row"><div><div class="titleline">${esc(x.code)}</div><div class="sub">${esc(x.category)} · hiệu lực ${fmtDate(x.effective_date)} · checked ${x.last_checked_at?new Date(x.last_checked_at).toLocaleString('vi-VN'):'—'}${x.last_error?' · '+esc(x.last_error):''}</div></div><a class="ghost button-link" target="_blank" rel="noopener" href="${esc(x.official_url)}">Nguồn</a></div>`).join('')}</div></div><div class="card panel"><div class="section-head"><div><h2>Deadline change requests</h2><p>Original deadline không bị ghi đè</p></div></div><div class="list">${req.slice(0,10).map(r=>`<div class="list-row"><div><div class="titleline">${esc(r.obligation_title)}</div><div class="sub">${fmtDate(r.old_due_date)} → ${fmtDate(r.new_due_date)} · ${esc(r.reason_category)} · ${esc(r.justification)}</div></div>${pill(r.status,r.status==='approved'?'green':r.status==='rejected'?'red':'amber')}</div>`).join('')||'<div class="empty">Chưa có yêu cầu</div>'}</div></div></div>`;
  $('#cSite').onchange=$('#cCat').onchange=$('#cReview').onchange=()=>compliance();$$('.changeDue').forEach(b=>b.onclick=()=>changeDue(b.dataset.id));$$('.resolveLegal').forEach(b=>b.onclick=()=>resolveLegal(b.dataset.id));$$('.resolveLegalUpdate').forEach(b=>b.onclick=()=>resolveLegalUpdate(b.dataset.id));if($('#legalWatchRun'))$('#legalWatchRun').onclick=async()=>{const b=$('#legalWatchRun');b.disabled=true;b.textContent='Đang kiểm tra…';try{const out=await api('/api/legal-watch/run',{method:'POST',body:'{}'});toast(`Legal Watch: ${out.checked_count} nguồn · ${out.changed_count} thay đổi · ${out.error_count} lỗi`);compliance()}catch(e){toast(e.message,true)}finally{b.disabled=false}};
}

function changeDue(id){const o=state.obligations.find(x=>x.id===id);modal('Yêu cầu đổi deadline',`<div class="form-grid"><div class="field"><label>Deadline hiện tại</label><input value="${o.current_due_date||''}" disabled></div><div class="field"><label>Deadline đề xuất *</label><input id="newDue" type="date"></div><div class="field full"><label>Lý do *</label><select id="reason"><option>Waiting for authority</option><option>Waiting for supplier</option><option>Budget approval</option><option>Document incomplete</option><option>Resource unavailable</option><option>Scope changed</option><option>Other</option></select></div><div class="field full"><label>Giải trình chi tiết *</label><textarea id="why"></textarea></div></div>`,async close=>{await api('/api/obligations/deadline-change',{method:'POST',body:JSON.stringify({obligation_id:id,new_due_date:$('#newDue').value,reason_category:$('#reason').value,justification:$('#why').value,requested_by:'EHS'})});close();toast('Đã gửi yêu cầu đổi deadline');compliance()},'Gửi yêu cầu')}
function resolveLegal(id){const x=state.legalReviews.find(a=>a.id===id);modal('Legal review',`<div class="notice">${esc(x.reason)}</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Kết luận</label><select id="lrStatus"><option value="reviewed">Reviewed / cập nhật ngoài hệ thống nếu cần</option><option value="keep_current">Giữ hiện tại</option><option value="not_applicable">Không áp dụng</option></select></div><div class="field full"><label>Ghi chú bắt buộc</label><textarea id="lrNote"></textarea></div></div>`,async close=>{await api('/api/legal-reviews/resolve',{method:'POST',body:JSON.stringify({id,status:$('#lrStatus').value,review_note:$('#lrNote').value,reviewed_by:'EHS'})});close();toast('Đã đóng legal review');compliance()},'Xác nhận')}
function resolveLegalUpdate(id){const x=state.legalUpdates.find(a=>a.id===id);modal('Review legal update',`<div class="notice"><b>${esc(x.code)}</b> · ${esc(x.summary)}</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Kết luận</label><select id="luStatus"><option value="action_required">Có ảnh hưởng / cần hành động</option><option value="reviewed">Đã review / chưa cần thay đổi</option><option value="not_applicable">Không áp dụng</option></select></div><div class="field full"><label>Ghi chú bắt buộc</label><textarea id="luNote" placeholder="Nêu obligation/hồ sơ nào cần rà; không tự sửa dữ liệu"></textarea></div></div>`,async close=>{await api('/api/legal-updates/resolve',{method:'POST',body:JSON.stringify({id,status:$('#luStatus').value,review_note:$('#luNote').value})});close();toast('Đã lưu impact review');compliance()},'Xác nhận')}



const DOCUMENT_FOLDERS=[['📚','Tất cả',''],['🔥','PCCC','fire'],['⚗️','Hóa chất','chemical'],['🌱','Môi trường','environment'],['🏗','Kiểm định','equipment'],['🦺','ATVSLĐ / PPE','osh'],['🎓','Đào tạo','training'],['♻️','Chất thải','waste'],['₫','Thanh toán','payment'],['📅','Kế hoạch năm','annual_plan'],['📑','Khác','other']];
