let docFilters={category:'',subcategory:'',site:'',status:'',ocr:'',linked:'',year:'',q:''},docSearchTimer=null;
function docCategoryName(code){return DOCUMENT_FOLDERS.find(x=>x[2]===code)?.[1]||code||'Chưa phân loại'}
function docSubOptions(category,selected=''){const arr=DOC_SUBCATS[category]||[];return `<option value="">Tất cả phân nhóm</option>${arr.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}`}
function docQuery(){const p=new URLSearchParams();for(const [k,v] of Object.entries(docFilters))if(v)p.set(k,v);return p.toString()}
async function exportFilteredDocuments(){const p=new URLSearchParams({scope:'documents'});for(const [k,v] of Object.entries(docFilters))if(v)p.set(k,v);const b=$('#docExportFiltered'),old=b?.textContent;if(b){b.disabled=true;b.textContent='Đang xuất…'}try{const r=await fetch(`/api/export/excel?${p.toString()}`);if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||`HTTP ${r.status}`)}const blob=await r.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`VIETCHEM_Documents_${docFilters.category||'all'}_${new Date().toISOString().slice(0,10)}.xlsx`;a.click();URL.revokeObjectURL(u);toast('Đã xuất danh mục đang lọc')}catch(e){toast(e.message,true)}finally{if(b){b.disabled=false;b.textContent=old}}}
async function documents(){
  const [stats,docs,exts]=await Promise.all([api('/api/documents/stats'),api(`/api/documents?${docQuery()}`),api('/api/document-extractions')]);
  state.documents=docs;state.extractions=exts;const emap=Object.fromEntries(exts.map(x=>[x.document_id,x])),queue=exts.filter(x=>x.status==='needs_review');
  const countMap=Object.fromEntries((stats.categories||[]).map(x=>[x.category,Number(x.count)]));const currentName=docFilters.category?docCategoryName(docFilters.category):'Tất cả tài liệu';
  const years=[...new Set(docs.map(d=>String(d.document_date||d.uploaded_at||'').slice(0,4)).filter(x=>/^20\d\d$/.test(x)))].sort().reverse();
  $('#app').innerHTML=`<div class="doc-breadcrumb"><b>Tủ hồ sơ</b><span>›</span><span>${esc(currentName)}</span>${docFilters.subcategory?`<span>›</span><span>${esc(docFilters.subcategory)}</span>`:''}</div>
  <div class="grid folder-grid doc-folder-grid">${DOCUMENT_FOLDERS.map(([i,n,c])=>`<button class="card folder docFolder ${docFilters.category===c?'active':''}" data-cat="${c}"><span class="icon">${i}</span><strong>${n}</strong><span>${c?(countMap[c]||0):stats.total} hồ sơ${c&&stats.categories?.find(x=>x.category===c)?.needs_review?` · ${stats.categories.find(x=>x.category===c).needs_review} chờ duyệt`:''}</span></button>`).join('')}</div>
  <div class="card panel section doc-filter-panel"><div class="section-head"><div><h2>Truy xuất hồ sơ</h2><p>Click category hoặc lọc theo site, phân nhóm, năm, trạng thái, OCR và liên kết nghiệp vụ.</p></div><div class="actions"><button class="soft" id="docReset">Xóa lọc</button><button class="primary" id="docExportFiltered">⇩ Xuất Excel đang lọc</button></div></div>
    <div class="doc-filters"><input id="docSearch" value="${esc(docFilters.q)}" placeholder="Tìm tên file, số văn bản, tag hoặc nội dung OCR…"><select id="docSubFilter">${docSubOptions(docFilters.category,docFilters.subcategory)}</select><select id="docSiteFilter"><option value="">Tất cả site</option>${state.sites.map(x=>`<option value="${x.code}" ${docFilters.site===x.code?'selected':''}>${x.code}</option>`).join('')}</select><select id="docYearFilter"><option value="">Tất cả năm</option>${years.map(y=>`<option ${docFilters.year===y?'selected':''}>${y}</option>`).join('')}</select><select id="docStatusFilter"><option value="">Tất cả trạng thái</option>${['needs_review','linked','archived'].map(x=>`<option ${docFilters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="docOcrFilter"><option value="">OCR: tất cả</option><option value="unprocessed" ${docFilters.ocr==='unprocessed'?'selected':''}>Chưa OCR</option><option value="needs_review" ${docFilters.ocr==='needs_review'?'selected':''}>OCR chờ review</option><option value="accepted" ${docFilters.ocr==='accepted'?'selected':''}>OCR accepted</option><option value="rejected" ${docFilters.ocr==='rejected'?'selected':''}>OCR rejected</option></select><select id="docLinkedFilter"><option value="">Liên kết: tất cả</option><option value="linked" ${docFilters.linked==='linked'?'selected':''}>Đã link nghiệp vụ</option><option value="unlinked" ${docFilters.linked==='unlinked'?'selected':''}>Chưa link</option></select></div><div class="doc-result-line"><b>${docs.length}</b> kết quả trong bộ lọc hiện tại</div>
  </div>
  <div class="section grid two doc-import-review"><details class="card panel doc-import-box"><summary><b>+ Import tài liệu</b><span>Kéo thả / chọn file · phân loại ngay khi nhập</span></summary><div class="dropzone" id="drop"><input id="file" type="file"><strong>Thả file vào đây hoặc click để chọn</strong><div class="sub">PDF / ảnh / Word / Excel · SHA-256 duplicate detection · không overwrite nguồn</div></div><div class="doc-import-fields" id="docImportTools"><select id="docCat">${DOCUMENT_FOLDERS.filter(x=>x[2]).map(x=>`<option value="${x[2]}" ${docFilters.category===x[2]?'selected':''}>${x[1]}</option>`).join('')}</select><select id="docSub"></select><select id="docSite">${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`).join('')}</select><label class="toggle"><input id="autoOCR" type="checkbox" checked> OCR sau import</label></div></details>
  <div class="card panel"><div class="section-head"><div><h2>Intelligence Review Queue</h2><p>OCR chưa được ghi nhận cho tới khi người dùng duyệt</p></div>${pill(`${queue.length} chờ duyệt`,queue.length?'violet':'green')}</div><div class="list">${queue.slice(0,6).map(x=>`<div class="list-row"><div><div class="titleline">${esc(x.original_name)}</div><div class="sub">${esc(x.doc_type)} · confidence ${Math.round(x.confidence*100)}% · ${esc(x.extraction_method||'—')}</div></div><button class="ghost docReview" data-ext="${x.id}">Review</button></div>`).join('')||'<div class="empty">Không có extraction chờ review</div>'}</div></div></div>
  <div class="section"><div class="table-wrap doc-table-wrap"><table class="doc-table"><thead><tr><th>File / số văn bản</th><th>Category / phân nhóm</th><th>Site</th><th>Ngày / hết hạn</th><th>Liên kết</th><th>Intelligence</th><th>Status</th><th>Imported</th><th>Thao tác</th></tr></thead><tbody>${docs.map(d=>{const x=emap[d.id];return `<tr><td><b>${esc(d.original_name)}</b><div class="sub">${d.document_no?`Số: ${esc(d.document_no)} · `:''}${d.version_label?`Ver ${esc(d.version_label)} · `:''}${d.tags?`#${esc(d.tags).replaceAll(',',' #')} · `:''}${(d.size_bytes/1024).toFixed(1)} KB</div></td><td><b>${esc(docCategoryName(d.category))}</b><div class="sub">${esc(d.subcategory||'Chưa phân nhóm')}</div></td><td>${esc(d.site_code||'—')}</td><td>${fmtDate(d.document_date)}<div class="sub">${d.expiry_date?`Hết hạn ${fmtDate(d.expiry_date)}`:'—'}</div></td><td>${d.linked_entity_id?pill(d.linked_entity_type||'linked','green'):pill('Chưa link','gray')}<div class="sub">${esc(d.linked_entity_id||'')}</div></td><td>${x?`${pill(x.doc_type,x.status==='accepted'?'green':x.status==='needs_review'?'violet':'gray')}<div class="sub">${Math.round(x.confidence*100)}% · ${esc(x.extraction_method||'')}</div>`:pill('Chưa OCR','gray')}</td><td>${pill(d.status,d.status==='linked'?'green':d.status==='archived'?'gray':'violet')}</td><td>${new Date(d.uploaded_at).toLocaleString('vi-VN')}</td><td class="actions doc-actions"><a class="ghost button-link" target="_blank" href="/api/documents/file?id=${encodeURIComponent(d.id)}&inline=1">Xem</a><a class="ghost button-link" href="/api/documents/file?id=${encodeURIComponent(d.id)}">Tải</a><button class="soft docMeta" data-doc="${d.id}">Phân loại</button>${x?`<button class="ghost docReview" data-ext="${x.id}">OCR Review</button>`:`<button class="ghost docProcess" data-doc="${d.id}">OCR</button>`}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Không có tài liệu khớp bộ lọc</td></tr>'}</tbody></table></div></div>`;
  $$('.docFolder').forEach(b=>b.onclick=()=>{docFilters.category=b.dataset.cat||'';docFilters.subcategory='';documents()});
  const re=()=>documents();$('#docSubFilter').onchange=e=>{docFilters.subcategory=e.target.value;re()};$('#docSiteFilter').onchange=e=>{docFilters.site=e.target.value;re()};$('#docYearFilter').onchange=e=>{docFilters.year=e.target.value;re()};$('#docStatusFilter').onchange=e=>{docFilters.status=e.target.value;re()};$('#docOcrFilter').onchange=e=>{docFilters.ocr=e.target.value;re()};$('#docLinkedFilter').onchange=e=>{docFilters.linked=e.target.value;re()};$('#docSearch').oninput=e=>{docFilters.q=e.target.value;clearTimeout(docSearchTimer);docSearchTimer=setTimeout(re,350)};$('#docReset').onclick=()=>{docFilters={category:'',subcategory:'',site:'',status:'',ocr:'',linked:'',year:'',q:''};documents()};$('#docExportFiltered').onclick=exportFilteredDocuments;
  const cat=$('#docCat'),sub=$('#docSub');const syncSub=()=>{sub.innerHTML=(DOC_SUBCATS[cat.value]||['Khác']).map(x=>`<option>${esc(x)}</option>`).join('')};syncSub();cat.onchange=syncSub;
  const drop=$('#drop'),inp=$('#file');if(drop){drop.onclick=()=>inp.click();inp.onchange=()=>inp.files[0]&&uploadDoc(inp.files[0]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)uploadDoc(f)}}
  $$('.docProcess').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='Đang đọc…';try{await api('/api/document-intelligence/process',{method:'POST',body:JSON.stringify({document_id:b.dataset.doc})});toast('Đã trích xuất · chờ review');documents()}catch(e){toast(e.message,true);b.disabled=false}});$$('.docReview').forEach(b=>b.onclick=()=>reviewExtraction(b.dataset.ext));$$('.docMeta').forEach(b=>b.onclick=()=>editDocumentMetadata(b.dataset.doc));applyPermissionUI();
}
async function uploadDoc(file){const base64=await new Promise((ok,err)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=err;r.readAsDataURL(file)});const out=await api('/api/documents',{method:'POST',body:JSON.stringify({original_name:file.name,mime_type:file.type,base64,category:$('#docCat').value,subcategory:$('#docSub').value,site_id:$('#docSite').value})});toast(out.duplicate_of?'Đã import · phát hiện file trùng':'Đã import vào Tủ hồ sơ');if($('#autoOCR')?.checked){toast('Đang chạy Document Intelligence…');try{await api('/api/document-intelligence/process',{method:'POST',body:JSON.stringify({document_id:out.id})})}catch(e){toast(`Import OK · OCR: ${e.message}`,true)}}documents()}
function editDocumentMetadata(id){const d=state.documents.find(x=>x.id===id);if(!d)return;modal('Phân loại & metadata tài liệu',`<div class="form-grid"><div class="field full"><div class="notice"><b>${esc(d.original_name)}</b><br>Metadata dùng để truy xuất; file nguồn không bị thay đổi.</div></div><div class="field"><label>Category *</label><select id="dmCat">${DOCUMENT_FOLDERS.filter(x=>x[2]).map(x=>`<option value="${x[2]}" ${d.category===x[2]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label>Phân nhóm</label><select id="dmSub"></select></div><div class="field"><label>Site</label><select id="dmSite"><option value="">—</option>${state.sites.map(s=>`<option value="${s.id}" ${d.site_id===s.id?'selected':''}>${s.code}</option>`).join('')}</select></div><div class="field"><label>Trạng thái</label><select id="dmStatus">${['needs_review','linked','archived'].map(x=>`<option ${d.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Số văn bản / chứng từ</label><input id="dmNo" value="${esc(d.document_no||'')}"></div><div class="field"><label>Phiên bản</label><input id="dmVer" value="${esc(d.version_label||'')}"></div><div class="field"><label>Ngày tài liệu</label><input id="dmDate" type="date" value="${esc(d.document_date||'')}"></div><div class="field"><label>Ngày hết hạn</label><input id="dmExpiry" type="date" value="${esc(d.expiry_date||'')}"></div><div class="field full"><label>Tags (phân cách bằng dấu phẩy)</label><input id="dmTags" value="${esc(d.tags||'')}" placeholder="VD: PC04, PCCC, 2026"></div><div class="field full"><label>Ghi chú metadata</label><textarea id="dmNote">${esc(d.metadata_note||'')}</textarea></div></div>`,async close=>{await api('/api/documents/metadata',{method:'PATCH',body:JSON.stringify({id,category:$('#dmCat').value,subcategory:$('#dmSub').value,site_id:$('#dmSite').value||null,status:$('#dmStatus').value,document_no:$('#dmNo').value||null,version_label:$('#dmVer').value||null,document_date:$('#dmDate').value||null,expiry_date:$('#dmExpiry').value||null,tags:$('#dmTags').value||null,metadata_note:$('#dmNote').value||null})});close();toast('Đã cập nhật phân loại tài liệu');documents()},'Lưu metadata');const c=$('#dmCat'),sub=$('#dmSub');const sync=()=>{sub.innerHTML=(DOC_SUBCATS[c.value]||['Khác']).map(x=>`<option ${x===(c.value===d.category?d.subcategory:'')?'selected':''}>${esc(x)}</option>`).join('')};sync();c.onchange=sync}
function extractionFields(x){return Object.entries(x.fields||{}).filter(([,v])=>v).map(([k,v])=>`<div class="extract-field"><span>${esc(k)}</span><b>${esc(v.value)}</b><small>${Math.round((v.confidence||0)*100)}%</small></div>`).join('')||'<div class="empty">Không trích được field có cấu trúc</div>'}
function editableExtractionFields(x){return Object.entries(x.fields||{}).map(([k,v])=>`<div class="field"><label>${esc(k)} · ${Math.round((v?.confidence||0)*100)}%</label><input class="extEditField" data-key="${esc(k)}" value="${esc(v?.value??'')}"></div>`).join('')||'<div class="empty">Không có field để chỉnh</div>'}
async function reviewExtraction(id){const x=state.extractions.find(y=>y.id===id);if(!x)return; if(!state.payments.length&&can('payments.read'))state.payments=await api('/api/payments');const suggested=x.matches?.[0]?.id||'';modal('Review Document Intelligence',`<div class="review-summary"><div>${pill(x.doc_type,'blue')} ${pill(`${Math.round(x.confidence*100)}%`,x.confidence>=.9?'green':x.confidence>=.75?'amber':'red')} ${x.edited_at?pill('Human edited','violet'):''}</div><div class="sub">${esc(x.original_name)} · ${esc(x.extraction_method||'')}</div></div><div class="notice">Có thể sửa field OCR trước khi Accept. Giá trị sửa được audit và không thay đổi file nguồn.</div><div class="form-grid" style="margin-top:12px">${editableExtractionFields(x)}</div>${x.warnings?.length?`<div class="notice">${x.warnings.map(esc).join(' · ')}</div>`:''}<div class="field full" style="margin-top:12px"><label>Link tới payment case (nếu phù hợp)</label><select id="extPay"><option value="">Không link payment</option>${state.payments.map(p=>`<option value="${p.id}" ${(suggested===p.id)?'selected':''}>${esc(p.vendor_name)} · ${esc(p.title)} · ${esc(p.invoice_no||'')}</option>`).join('')}</select></div><div class="field full"><label>Kết luận review</label><select id="extStatus"><option value="accepted">Accept extraction</option><option value="rejected">Reject extraction</option></select></div><div class="field full"><label>Review note</label><textarea id="extNote" placeholder="Ghi rõ field đã chỉnh nếu OCR sai"></textarea></div><details><summary>Text preview</summary><pre class="ocr-preview">${esc(x.text_preview||'')}</pre></details>`,async close=>{const fields={};$$('.extEditField').forEach(i=>fields[i.dataset.key]=i.value);await api('/api/document-intelligence/extraction',{method:'PATCH',body:JSON.stringify({id,fields})});await api('/api/document-intelligence/review',{method:'POST',body:JSON.stringify({id,status:$('#extStatus').value,payment_id:$('#extPay').value||null,review_note:$('#extNote').value})});close();toast('Đã lưu field review + kết luận');documents()},'Xác nhận')}


async function payments(){
  state.payments=await api('/api/payments');
  $('#app').innerHTML=`<div class="grid payment-grid">${state.payments.map(p=>{const got=p.docs.filter(x=>x.received).length,tot=p.docs.filter(x=>x.required).length,n=days(p.contractual_due_date),intel=p.intelligence||{};let match='';if(intel.invoice_quantity_kg!=null){const st=intel.weight_status==='matched'?'ok':intel.weight_status==='mismatch'?'warn':'';match=`<div class="match-strip ${st}"><b>Document matching</b><span>Invoice ${new Intl.NumberFormat('vi-VN').format(intel.invoice_quantity_kg)} kg</span><span>${intel.weight_ticket_count?`Phiếu cân ${new Intl.NumberFormat('vi-VN').format(intel.weight_ticket_total_kg)} kg · lệch ${new Intl.NumberFormat('vi-VN').format(intel.weight_variance_kg)} kg · tolerance ${new Intl.NumberFormat('vi-VN').format(intel.weight_tolerance_kg||0)} kg`:'Chưa có phiếu cân đã duyệt'}</span><span>BBNT: ${intel.bbnt_count||0}</span></div>`}return `<div class="card payment"><div class="payment-top">${n<0&&p.status!=='paid'?pill(`Overdue ${-n}d`,'red'):n!=null&&n<=7?pill(`Due ${n}d`,'amber'):pill(p.status,'blue')}<div class="actions"><button class="soft quickEvidence" data-type="payment" data-id="${p.id}" data-site="${p.site_id||''}">+ File</button><button class="ghost editPayment" data-id="${p.id}">Edit</button></div></div><h3>${esc(p.title)}</h3><div class="vendor">${esc(p.vendor_name)} · ${esc(p.site_code||'—')}</div><div class="money">${fmtMoney(p.amount)}</div><div class="sub">Invoice ${esc(p.invoice_no||'—')} · ${fmtDate(p.invoice_date)}</div><div class="sub">Contract due: <b>${fmtDate(p.contractual_due_date)}</b> · Planned: <b>${fmtDate(p.planned_payment_date)}</b></div>${p.explanation_if_late?`<div class="late-note">${esc(p.explanation_if_late)}</div>`:''}${match}<div class="progress" style="margin-top:10px"><i style="width:${tot?got/tot*100:0}%"></i></div><div class="sub">${got}/${tot} hồ sơ · ${intel.accepted_docs||0} tài liệu OCR đã duyệt · ${p.linked_documents?.length||0} file linked</div><div class="checklist">${p.docs.map(d=>`<label class="check"><input class="docToggle" data-id="${d.id}" type="checkbox" ${d.received?'checked':''}> ${esc(d.doc_type)} ${d.document_id?'✓':''}</label>`).join('')}</div></div>`}).join('')}</div>`;
  $$('.docToggle').forEach(c=>c.onchange=async()=>{await api('/api/payments/doc-toggle',{method:'POST',body:JSON.stringify({id:c.dataset.id,received:c.checked})});toast('Đã cập nhật checklist')});$$('.editPayment').forEach(b=>b.onclick=()=>editPayment(b.dataset.id));
}
function editPayment(id){const p=state.payments.find(x=>x.id===id);modal('Payment tracking',`<div class="form-grid"><div class="field"><label>Contractual due</label><input value="${p.contractual_due_date||''}" disabled></div><div class="field"><label>Ngày dự kiến nội bộ</label><input id="payPlan" type="date" value="${p.planned_payment_date||''}"></div><div class="field"><label>Weight tolerance (kg)</label><input id="payTol" type="number" min="0" step="0.1" value="${p.weight_tolerance_kg??0}"></div><div class="field"><label>Trạng thái</label><select id="payStatus"><option value="collecting_docs" ${p.status==='collecting_docs'?'selected':''}>Collecting docs</option><option value="ready" ${p.status==='ready'?'selected':''}>Ready</option><option value="submitted" ${p.status==='submitted'?'selected':''}>Submitted</option><option value="scheduled" ${p.status==='scheduled'?'selected':''}>Scheduled</option><option value="paid" ${p.status==='paid'?'selected':''}>Paid</option><option value="returned" ${p.status==='returned'?'selected':''}>Returned</option></select></div><div class="field full"><label>Giải trình nếu planned > contract due</label><textarea id="payWhy">${esc(p.explanation_if_late||'')}</textarea></div><div class="field full"><div class="notice">Payment Tracker chỉ theo dõi hồ sơ và deadline. Không hạch toán, không chuyển tiền.</div></div></div>`,async close=>{await api('/api/payments',{method:'PATCH',body:JSON.stringify({id,planned_payment_date:$('#payPlan').value,status:$('#payStatus').value,explanation_if_late:$('#payWhy').value,weight_tolerance_kg:Number($('#payTol').value||0)})});close();toast('Đã cập nhật tracking');payments()})}

async function equipment(){
  const reqs=[api('/api/equipment')];if(can('documents.read'))reqs.push(api('/api/documents'));const out=await Promise.all(reqs);state.equipment=out[0];if(out[1])state.documents=out[1];
  const needReview=state.equipment.filter(e=>e.review_status==='needs_review').length,expired=state.equipment.filter(e=>e.inspection_state==='expired').length;
  $('#app').innerHTML=`<div class="toolbar"><button class="primary" id="addEq">+ Thiết bị</button><span class="muted">${state.equipment.length} asset · ${needReview} cần rà nguồn · ${expired} hết hạn kiểm định</span></div><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Thiết bị</th><th>Nguồn/Review</th><th>Vị trí</th><th>Kiểm định gần nhất</th><th>Tiếp theo</th><th>Quản lý</th><th></th></tr></thead><tbody>${state.equipment.map(e=>{const n=days(e.next_inspection_date),due=e.inspection_state==='expired'?pill(fmtDate(e.next_inspection_date),'red'):e.inspection_state==='due_60'?pill(fmtDate(e.next_inspection_date),'amber'):fmtDate(e.next_inspection_date);return `<tr><td><b>${esc(e.asset_code)}</b><div class="sub">${esc(e.model||'')}</div></td><td><b>${esc(e.name)}</b><div class="sub">${esc(e.manufacturer||'—')} · ${esc(e.serial_no||'—')}</div>${e.strict_control?pill('Nghiêm ngặt','violet'):pill('Chưa xác định','gray')}</td><td>${e.review_status==='needs_review'?pill('Needs review','amber'):pill('Reviewed','green')}<div class="sub">${esc(e.source_ref||'manual')}</div></td><td>${esc(e.site_code||'—')} · ${esc(e.location||'—')}</td><td>${fmtDate(e.last_inspection_date)}<div class="sub">${e.inspection_count||0} lịch sử</div></td><td>${due}</td><td>${esc(e.manager||'—')}<div class="sub">${esc(e.operator||'')}</div></td><td class="actions"><button class="ghost eqHistory" data-id="${e.id}">Lịch sử</button><button class="ghost eqEdit" data-id="${e.id}">Sửa</button>${e.review_status==='needs_review'?`<button class="ghost eqReconcile" data-id="${e.id}">Đối chiếu</button>`:''}<button class="soft quickEvidence" data-type="equipment" data-id="${e.id}" data-site="${e.site_id||''}">+ File</button><button class="soft eqInspect" data-id="${e.id}">+ Kiểm định</button></td></tr>`}).join('')}</tbody></table></div>`;
  $('#addEq').onclick=addEq;$$('.eqInspect').forEach(b=>b.onclick=()=>recordInspection(b.dataset.id));$$('.eqHistory').forEach(b=>b.onclick=()=>equipmentHistory(b.dataset.id));$$('.eqEdit').forEach(b=>b.onclick=()=>editEquipment(b.dataset.id));$$('.eqReconcile').forEach(b=>b.onclick=()=>reconcileEquipment(b.dataset.id));
}
function addEq(){modal('Thêm thiết bị',`<div class="form-grid"><div class="field"><label>Asset code *</label><input id="eCode"></div><div class="field"><label>Tên *</label><input id="eName"></div><div class="field"><label>Category</label><input id="eCat"></div><div class="field"><label>Site</label><select id="eSite"><option value="">Chưa xác định</option>${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`)}</select></div><div class="field"><label>Vị trí</label><input id="eLoc"></div><div class="field"><label>Kiểm định tiếp theo</label><input id="eNext" type="date"></div><div class="field"><label>Nhắc trước (ngày)</label><input id="eRemind" type="number" min="0" value="30"></div><div class="field full"><label><input id="eStrict" type="checkbox"> Thuộc danh mục nghiêm ngặt</label></div><div class="field full"><label>Căn cứ pháp lý / điều kiện áp dụng</label><textarea id="eLegal"></textarea></div></div>`,async close=>{await api('/api/equipment',{method:'POST',body:JSON.stringify({asset_code:$('#eCode').value,name:$('#eName').value,category:$('#eCat').value,site_id:$('#eSite').value||null,location:$('#eLoc').value,next_inspection_date:$('#eNext').value,inspection_reminder_days:Number($('#eRemind').value||30),strict_control:$('#eStrict').checked,legal_basis:$('#eLegal').value})});close();toast('Đã thêm thiết bị');equipment()})}
