async function systemView(){
  const health=await api('/api/system/health');
  const privateMode=!!health.personal_private_mode,remote=health.remote_url||'';
  $('#app').innerHTML=`<div class="grid two"><div class="card panel"><div class="section-head"><div><h2>Backup</h2><p>Snapshot SQLite + toàn bộ uploads · checksum SHA-256</p></div>${pill('Admin only','violet')}</div><div class="notice">Backup được tạo từ snapshot nhất quán. Restore không chạy trực tiếp trên server đang hoạt động để tránh corruption; dùng tool offline đi kèm checkpoint.</div><div class="toolbar" style="margin-top:14px"><button class="primary" id="downloadBackup">Tạo & tải backup</button></div></div><div class="card panel"><div class="section-head"><div><h2>Validate backup</h2><p>Kiểm manifest + checksum trước khi restore</p></div></div><div class="dropzone" id="backupDrop"><input id="backupFile" type="file" accept=".gz,.tgz,application/gzip"><strong>Chọn file .tar.gz</strong><div class="sub">Không ghi đè dữ liệu khi validate</div></div><div id="backupResult" class="sub" style="margin-top:10px"></div></div></div>
  <div class="section card panel"><div class="section-head"><div><h2>Personal Private Online</h2><p>Tailscale private network · không public Internet</p></div>${pill(privateMode?'TAILSCALE MODE':'LOCAL MODE',privateMode?'green':'gray')}</div><div class="mini-stats"><div><b>${esc(health.listen_host||'—')}</b><span>Listener</span></div><div><b>${health.listen_port||'—'}</b><span>Port</span></div><div><b>${health.legal_watch_enabled?'ON':'OFF'}</b><span>Legal Watch</span></div><div><b>${health.auto_backup_enabled?'ON':'OFF'}</b><span>Auto backup</span></div></div><div class="notice" style="margin-top:12px">${privateMode?`<b>Private URL:</b> ${esc(remote||`http://${health.tailscale_ip||health.listen_host}:${health.listen_port}`)}<br><b>Tailscale IP:</b> ${esc(health.tailscale_ip||'—')}<br>Server chỉ bind vào interface Tailscale; thiết bị không nằm trong tailnet sẽ không truy cập được.`:'Đang chạy Local fallback. Muốn truy cập từ điện thoại/laptop qua mạng riêng, đóng app và chạy <b>START_PRIVATE_ONLINE.bat</b>.'}</div></div>
  <div class="section card panel"><div class="section-head"><div><h2>System health</h2><p>${esc(health.app_version)} · SQLite ${esc(health.journal_mode)} · busy timeout ${health.busy_timeout_ms}ms</p></div>${pill(health.db==='ok'?'Healthy':'Issue',health.db==='ok'?'green':'red')}</div><div class="mini-stats"><div><b>${health.users}</b><span>Active users</span></div><div><b>${health.documents}</b><span>Documents</span></div><div><b>${health.notifications_unread}</b><span>Unread alerts</span></div><div><b>${health.last_auto_backup_at?new Date(health.last_auto_backup_at).toLocaleString('vi-VN'):'—'}</b><span>Last auto backup</span></div></div></div>
  <div class="section card panel"><div class="section-head"><div><h2>Data & Update Hardening</h2><p>Persistent data tách khỏi thư mục app</p></div>${pill(health.schema_version||'schema','blue')}</div><div class="notice"><b>Database:</b> ${esc(health.db_path)}<br><b>Uploads:</b> ${esc(health.upload_dir)}<br><b>Backups:</b> ${esc(health.backup_dir)}<br><b>Auto backup:</b> ${health.auto_backup_enabled?'Bật':'Tắt'} · kiểm ${health.backup_check_interval_minutes||60} phút/lần · tạo tối đa ~1 bản/24h · giữ ${health.backup_retention_days} ngày</div></div>
  <div class="section card panel"><div class="section-head"><div><h2>Recovery policy</h2><p>Persistent data + versioned migrations</p></div></div><div class="list"><div class="list-row"><div><div class="titleline">Online backup</div><div class="sub">VACUUM snapshot + uploads + manifest</div></div>${pill('Ready','green')}</div><div class="list-row"><div><div class="titleline">Backup validation</div><div class="sub">SHA-256 từng file</div></div>${pill('Ready','green')}</div><div class="list-row"><div><div class="titleline">Versioned migration</div><div class="sub">Schema migration chạy 1 lần, có checksum và pre-update backup</div></div>${pill('Ready','green')}</div><div class="list-row"><div><div class="titleline">Restore</div><div class="sub">Offline CLI: node scripts/restore-backup.mjs</div></div>${pill('Safe mode','blue')}</div><div class="list-row"><div><div class="titleline">Live restore</div><div class="sub">Cố ý không cho phép khi app đang mở</div></div>${pill('Blocked','amber')}</div></div></div>`;
  $('#downloadBackup').onclick=async()=>{const b=$('#downloadBackup');b.disabled=true;b.textContent='Đang tạo…';try{const r=await rawFetch('/api/admin/backup');if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||`HTTP ${r.status}`)}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const cd=r.headers.get('content-disposition')||'';a.download=(cd.match(/filename=([^;]+)/)?.[1]||'GAMI_EHS_backup.tar.gz').replaceAll('"','');a.click();URL.revokeObjectURL(url);toast('Đã tạo backup')}catch(e){toast(e.message,true)}finally{b.disabled=false;b.textContent='Tạo & tải backup'}};
  const input=$('#backupFile'),drop=$('#backupDrop');drop.onclick=()=>input.click();drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)validateBackupFile(f)};input.onchange=()=>input.files[0]&&validateBackupFile(input.files[0]);
}
async function validateBackupFile(file){const base64=await new Promise((ok,err)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=err;r.readAsDataURL(file)});$('#backupResult').textContent='Đang kiểm tra…';try{const out=await api('/api/admin/backup/validate',{method:'POST',body:JSON.stringify({base64})});$('#backupResult').innerHTML=`${pill('VALID','green')} ${esc(out.manifest.created_at)} · ${out.manifest.files.length} files · ${esc(out.manifest.app_version||'')}`}catch(e){$('#backupResult').innerHTML=`${pill('INVALID','red')} ${esc(e.message)}`}}



// ===== Checkpoint 5: Workflow & Usability overrides =====
function statusPill(status){const map={completed:'green',in_progress:'blue',waiting:'amber',blocked:'red',not_started:'gray',cancelled:'gray',overdue:'red',collecting_docs:'amber',ready:'green',submitted:'blue',scheduled:'violet',paid:'green',returned:'red'};const labels={not_started:'Chưa bắt đầu',in_progress:'Đang thực hiện',waiting:'Đang chờ',blocked:'Bị chặn',completed:'Hoàn thành',cancelled:'Hủy',overdue:'Quá hạn',collecting_docs:'Thu hồ sơ',ready:'Đủ hồ sơ',submitted:'Đã gửi',scheduled:'Đã lên lịch',paid:'Đã thanh toán',returned:'Bị trả lại'};return pill(labels[status]||status,map[status]||'gray')}
function progressBar(v){v=Math.max(0,Math.min(100,Number(v||0)));return `<div class="progress"><i style="width:${v}%"></i></div><div class="sub progress-label">${v}%</div>`}
function uniqueEmployeeLabels(rows){const counts={};for(const e of rows)counts[e.full_name]=(counts[e.full_name]||0)+1;return new Map(rows.map(e=>[e.id,counts[e.full_name]>1?`${e.full_name} — ${e.department||e.site_code||'khác'}`:e.full_name]))}

async function managePpeTypes(){
  const catalog=await api('/api/ppe/catalog');
  const active=catalog.filter(x=>Number(x.active)===1).length,inactive=catalog.length-active;
  modal('Quản lý loại PPE',`<div class="ppe-catalog-manager"><div class="toolbar"><button class="primary" id="ppeTypeAdd">+ Thêm loại PPE</button><input id="ppeTypeQ" placeholder="Tìm tên / SKU"><select id="ppeTypeStatus"><option value="">Tất cả</option><option value="active">Đang dùng</option><option value="inactive">Đã ngừng</option></select><span class="muted">${active} đang dùng · ${inactive} đã ngừng</span></div><div class="notice">“Bỏ loại PPE” = ngừng sử dụng, không xóa lịch sử. Giao dịch và chi phí cũ vẫn được giữ để audit.</div><div class="table-wrap ppe-catalog-table"><table><thead><tr><th>SKU</th><th>Loại PPE</th><th>ĐVT</th><th>Tồn</th><th>Min</th><th>Đơn giá</th><th>Trạng thái</th><th>GD</th><th></th></tr></thead><tbody id="ppeTypeRows"></tbody></table></div></div>`,async close=>close(),'Đóng');
  const render=()=>{const q=String($('#ppeTypeQ')?.value||'').toLowerCase(),st=$('#ppeTypeStatus')?.value||'';const rows=catalog.filter(i=>(!q||String(i.name).toLowerCase().includes(q)||String(i.sku).toLowerCase().includes(q))&&(!st||(st==='active'?Number(i.active)===1:Number(i.active)===0)));$('#ppeTypeRows').innerHTML=rows.map(i=>`<tr><td>${esc(i.sku)}</td><td><b>${esc(i.name)}</b>${i.size_variant?`<div class="sub">${esc(i.size_variant)}</div>`:''}</td><td>${esc(i.unit||'—')}</td><td>${Number(i.current_stock)<0?pill(i.current_stock,'red'):esc(i.current_stock)}</td><td>${esc(i.min_stock??'0')}</td><td>${i.unit_price!=null?fmtMoney(i.unit_price):'—'}</td><td>${Number(i.active)===1?pill('Đang dùng','green'):pill('Đã ngừng','gray')}</td><td>${i.tx_count||0}</td><td class="actions"><button class="ghost ppeTypeEdit" data-id="${i.id}">Sửa</button>${Number(i.active)===1?`<button class="danger ppeTypeStop" data-id="${i.id}">Bỏ</button>`:`<button class="soft ppeTypeRestore" data-id="${i.id}">Khôi phục</button>`}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Không có loại PPE phù hợp</td></tr>';$$('.ppeTypeEdit').forEach(b=>b.onclick=()=>ppeTypeForm(catalog.find(x=>x.id===b.dataset.id)));$$('.ppeTypeStop').forEach(b=>b.onclick=()=>deactivatePpeType(catalog.find(x=>x.id===b.dataset.id)));$$('.ppeTypeRestore').forEach(b=>b.onclick=async()=>{await api('/api/ppe/catalog',{method:'PATCH',body:JSON.stringify({id:b.dataset.id,active:true})});toast('Đã khôi phục loại PPE');managePpeTypes()})};
  $('#ppeTypeAdd').onclick=()=>ppeTypeForm(null);$('#ppeTypeQ').oninput=render;$('#ppeTypeStatus').onchange=render;render();
}
function ppeTypeForm(item=null){const isEdit=!!item;modal(isEdit?'Sửa loại PPE':'Thêm loại PPE',`<div class="form-grid"><div class="field"><label>SKU *</label><input id="ptSku" value="${esc(item?.sku||'')}"></div><div class="field"><label>Tên PPE *</label><input id="ptName" value="${esc(item?.name||'')}"></div><div class="field"><label>ĐVT *</label><input id="ptUnit" value="${esc(item?.unit||'cái')}"></div><div class="field"><label>Size / Quy cách</label><input id="ptSize" value="${esc(item?.size_variant||'')}"></div><div class="field"><label>Min stock</label><input id="ptMin" type="number" min="0" value="${item?.min_stock??0}"></div><div class="field"><label>Lifecycle (ngày)</label><input id="ptLife" type="number" min="0" value="${item?.lifecycle_days??''}"></div><div class="field"><label>Đơn giá tham chiếu (VND)</label><input id="ptPrice" type="number" min="0" step="100" value="${item?.unit_price??''}"></div>${!isEdit?'<div class="field"><label>Tồn đầu kỳ</label><input id="ptOpening" type="number" value="0"></div>':''}<div class="field full"><div class="notice">${isEdit?'Sửa master không làm thay đổi giao dịch/chi phí lịch sử.':'Nếu có tồn đầu kỳ, hệ thống sẽ tạo một dòng Stock Ledger OPENING_IMPORT.'}</div></div></div>`,async close=>{const body={sku:$('#ptSku').value,name:$('#ptName').value,unit:$('#ptUnit').value,size_variant:$('#ptSize').value,min_stock:Number($('#ptMin').value||0),lifecycle_days:$('#ptLife').value===''?null:Number($('#ptLife').value),unit_price:$('#ptPrice').value===''?null:Number($('#ptPrice').value)};if(isEdit){body.id=item.id;await api('/api/ppe/catalog',{method:'PATCH',body:JSON.stringify(body)})}else{body.opening_stock=Number($('#ptOpening').value||0);await api('/api/ppe/catalog',{method:'POST',body:JSON.stringify(body)})}close();toast(isEdit?'Đã cập nhật loại PPE':'Đã thêm loại PPE');ppe()},isEdit?'Lưu':'Thêm')}
function deactivatePpeType(item){modal('Bỏ / ngừng loại PPE',`<div class="notice warn"><b>${esc(item.name)}</b> · ${esc(item.sku)}<br>Tồn hiện tại: <b>${item.current_stock}</b>. Loại PPE sẽ bị ẩn khỏi danh sách xuất/nhập thường ngày nhưng lịch sử vẫn giữ nguyên.</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Lý do ngừng sử dụng *</label><textarea id="ptStopReason" placeholder="VD: Không còn sử dụng, thay bằng mã PPE mới, ngừng mua..."></textarea></div></div>`,async close=>{await api('/api/ppe/catalog',{method:'PATCH',body:JSON.stringify({id:item.id,active:false,inactive_reason:$('#ptStopReason').value})});close();toast('Đã ngừng loại PPE');ppe()},'Xác nhận bỏ')}

function ppeRowsCp56(items){return items.map(i=>`<tr><td>${esc(i.sku)}</td><td><b>${esc(i.name)}</b></td><td>${Number(i.current_stock)<0?pill(i.current_stock,'red'):Number(i.current_stock)<=Number(i.min_stock)?pill(i.current_stock,'amber'):pill(i.current_stock,'green')}</td><td>${esc(i.unit||'—')}</td><td>${i.min_stock??'—'}</td><td>${i.unit_price?fmtMoney(i.unit_price):'—'}</td><td class="ppe-action-cell"><div class="ppe-row-actions"><button class="soft ppeIssueOne" data-id="${i.id}">Xuất</button><button class="ghost ppeAdjustOne" data-id="${i.id}">Điều chỉnh</button></div></td></tr>`).join('')}

ppe = async function(){
  state.employees=await api('/api/employees?status=active');state.ppe=await api('/api/ppe');
  const neg=state.ppe.items.filter(i=>Number(i.current_stock)<0).length,zero=state.ppe.items.filter(i=>Number(i.current_stock)===0).length,low=state.ppe.items.filter(i=>Number(i.current_stock)<=Number(i.min_stock)).length,totalStock=state.ppe.items.reduce((a,i)=>a+Number(i.current_stock||0),0);
  $('#app').innerHTML=`<div class="grid ppe-kpis">${kpi('Tổng mặt hàng',state.ppe.items.length,'PPE master','#edf2ff')}${kpi('Tổng tồn',new Intl.NumberFormat('vi-VN').format(totalStock),'Theo tồn hệ thống','#eaf8f2')}${kpi('Low stock',low,'≤ min stock','#fff6e2')}${kpi('Âm kho',neg,'Cần reconciliation','#fff0f1')}${kpi('Hết hàng',zero,'Vẫn cho xuất','#f1edff')}</div>
  <div class="toolbar ppe-toolbar"><button class="primary" id="issuePPE">+ Xuất PPE</button><button class="ghost" id="adjustPPE">Nhập / điều chỉnh</button><button class="ghost" id="managePpeTypes">⚙ Loại PPE</button><input id="ppeQ" placeholder="Tìm PPE / SKU"><span class="muted">${state.ppe.items.length} mặt hàng · ${neg} âm kho · khung xem ~20 dòng</span><div class="toolbar-spacer"></div><div class="ppe-history-menu-wrap"><button class="ghost" id="ppeHistoryToggle">Lịch sử nhập/xuất ▾</button><div class="card ppe-history-dropdown" id="ppeHistoryDropdown" hidden><div class="ppe-history-head"><div><b>Lịch sử nhập/xuất PPE</b><span>Stock ledger đầy đủ</span></div><button class="x" id="ppeHistoryClose">×</button></div><div class="toolbar"><input id="ppeHistQ" placeholder="Tìm PPE / người nhận / bộ phận / lý do"><select id="ppeHistType"><option value="">Tất cả giao dịch</option><option value="IN">Nhập kho</option><option value="OUT">Xuất PPE</option><option value="ADJUSTMENT">Điều chỉnh</option><option value="OPENING_IMPORT">Tồn đầu kỳ</option></select><button class="ghost" id="exportPpeHistory">⇩ Xuất Excel lịch sử</button><span class="muted" id="ppeHistCount">Chưa tải</span></div><div class="table-wrap ppe-history-table-wrap"><table class="ppe-history-table"><thead><tr><th>Thời gian</th><th>Loại</th><th>SKU</th><th>PPE</th><th>SL</th><th>Tồn trước</th><th>Tồn sau</th><th>Người nhận</th><th>Bộ phận</th><th>Lý do</th><th>Người thao tác</th></tr></thead><tbody id="ppeHistoryRows"><tr><td colspan="11" class="empty">Mở lịch sử để tải dữ liệu</td></tr></tbody></table></div></div></div></div>
  <div class="ppe-inventory-full"><div class="top-scroll" id="ppeTopScroll"><div></div></div><div class="table-wrap ppe-table-wrap" id="ppeTableWrap"><table class="ppe-table"><thead><tr><th>SKU</th><th>PPE</th><th>Tồn hiện tại</th><th>ĐVT</th><th>Min stock</th><th>Đơn giá tham chiếu</th><th class="ppe-action-head">Thao tác</th></tr></thead><tbody id="ppeRows">${ppeRowsCp56(state.ppe.items)}</tbody></table></div><div class="ppe-table-foot"><span>Cuộn dọc ngay trong bảng để xem toàn bộ danh mục.</span><span>${state.ppe.items.length} mặt hàng</span></div></div>`;
  $('#issuePPE').onclick=()=>issuePPE();$('#adjustPPE').onclick=()=>adjustPPE();$('#managePpeTypes').onclick=()=>managePpeTypes();
  const renderRows=()=>{const q=($('#ppeQ').value||'').trim().toLowerCase();const rows=state.ppe.items.filter(x=>!q||String(x.name||'').toLowerCase().includes(q)||String(x.sku||'').toLowerCase().includes(q));$('#ppeRows').innerHTML=ppeRowsCp56(rows)};$('#ppeQ').oninput=renderRows;
  $('#ppeRows').onclick=e=>{const issue=e.target.closest('.ppeIssueOne'),adj=e.target.closest('.ppeAdjustOne');if(issue)issuePPE(issue.dataset.id);if(adj)adjustPPE(adj.dataset.id)};
  const top=$('#ppeTopScroll'),wrap=$('#ppeTableWrap'),sync=()=>{top.firstElementChild.style.width=wrap.scrollWidth+'px'};sync();requestAnimationFrame(sync);top.onscroll=()=>{wrap.scrollLeft=top.scrollLeft};wrap.onscroll=()=>{top.scrollLeft=wrap.scrollLeft};
  const toggle=$('#ppeHistoryToggle'),drop=$('#ppeHistoryDropdown'),close=$('#ppeHistoryClose');const openHistory=async()=>{drop.hidden=false;toggle.classList.add('active');await loadPpeHistory()};const closeHistory=()=>{drop.hidden=true;toggle.classList.remove('active')};toggle.onclick=()=>drop.hidden?openHistory():closeHistory();close.onclick=closeHistory;$('#ppeHistType').onchange=()=>loadPpeHistory();let histTimer;$('#ppeHistQ').oninput=()=>{clearTimeout(histTimer);histTimer=setTimeout(loadPpeHistory,220)};$('#exportPpeHistory').onclick=e=>{e.preventDefault();downloadExcel('ppe-ledger',$('#exportPpeHistory'))};
  applyPermissionUI();
}

function ppeLineWith(preselectId=null){return `<div class="ppe-line"><select class="liItem">${state.ppe.items.map(i=>`<option value="${i.id}" ${preselectId===i.id?'selected':''}>${esc(i.name)} · tồn ${i.current_stock}</option>`).join('')}</select><input class="liQty" type="number" min="1" value="1"><button class="x rm" type="button">×</button></div>`}
issuePPE = function(preselectItemId=null){
  const active=state.employees,labels=uniqueEmployeeLabels(active);
  modal('Xuất PPE',`<div class="form-grid"><div class="field full"><label>Người nhận *</label><select id="ppeEmp">${active.map(e=>`<option value="${e.id}">${esc(labels.get(e.id))}</option>`).join('')}</select><div id="ppeEmpInfo" class="selected-person"></div></div><div class="field full"><label>Hàng cần xuất</label><div class="ppe-lines" id="ppeLines">${ppeLineWith(preselectItemId)}</div><button class="soft" type="button" id="addLine">+ Thêm mặt hàng</button></div><div class="field"><label>Lý do</label><select id="ppeReason"><option>Cấp mới</option><option>Cấp định kỳ</option><option>Hỏng</option><option>Mất</option><option>Thay thế</option><option>Khác</option></select></div><div class="field"><label>Ghi chú</label><input id="ppeNote"></div><div class="field full"><div class="notice">Tồn âm không khóa thao tác; hệ thống lưu discrepancy + audit để đối chiếu.</div></div></div>`,async close=>{const lines=$$('.ppe-line').map(r=>({item_id:$('.liItem',r).value,quantity:Number($('.liQty',r).value)}));const out=await api('/api/ppe/issue',{method:'POST',body:JSON.stringify({employee_id:$('#ppeEmp').value,lines,reason:$('#ppeReason').value,note:$('#ppeNote').value})});close();toast(out.results.some(x=>x.negative_stock)?'Đã xuất · có mặt hàng âm kho':'Đã xuất PPE');ppe()});
  setTimeout(()=>{const renderInfo=()=>{const e=active.find(x=>x.id===$('#ppeEmp').value);$('#ppeEmpInfo').innerHTML=e?`<b>${esc(e.full_name)}</b><span>Mã NV: ${esc(e.employee_code||'—')}</span><span>Bộ phận: ${esc(e.department||'—')}</span><span>Vị trí: ${esc(e.job_title||'—')}</span><span>Site: ${esc(e.site_code||'—')}</span>`:''};$('#ppeEmp').onchange=renderInfo;renderInfo();$('#addLine').onclick=()=>{$('#ppeLines').insertAdjacentHTML('beforeend',ppeLineWith());wireRemove()};wireRemove()},0)
}
adjustPPE = function(preselectItemId=null){modal('Nhập / điều chỉnh PPE',`<div class="form-grid"><div class="field full"><label>PPE</label><select id="adjItem">${state.ppe.items.map(i=>`<option value="${i.id}" ${preselectItemId===i.id?'selected':''}>${esc(i.name)} · tồn ${i.current_stock}</option>`).join('')}</select></div><div class="field"><label>Số lượng (+ nhập, - điều chỉnh)</label><input id="adjQty" type="number" value="1"></div><div class="field"><label>Đơn giá nhập/tham chiếu (VND)</label><input id="adjPrice" type="number" min="0" step="100"></div><div class="field full"><label>Lý do</label><input id="adjReason" value="Kiểm kê/nhập kho"></div><div class="field full"><div class="notice">Khi nhập kho (+), nếu điền đơn giá thì hệ thống cập nhật đơn giá tham chiếu. Khi cấp phát, đơn giá được chốt vào giao dịch để phân bổ chi phí không thay đổi về sau.</div></div></div>`,async close=>{await api('/api/ppe/adjust',{method:'POST',body:JSON.stringify({item_id:$('#adjItem').value,quantity:Number($('#adjQty').value),unit_price:$('#adjPrice').value===''?null:Number($('#adjPrice').value),reason:$('#adjReason').value})});close();toast('Đã cập nhật tồn');ppe()});setTimeout(()=>{const fillPrice=()=>{const i=state.ppe.items.find(x=>x.id===$('#adjItem').value);$('#adjPrice').value=i?.unit_price??''};$('#adjItem').onchange=fillPrice;fillPrice()},0)}

compliance = async function(){
  const site=$('#cSite')?.value||'',cat=$('#cCat')?.value||'',review=$('#cReview')?.value||'',scope=$('#cScope')?.value||'',status=$('#cStatus')?.value||'';
  const [overview,obs,req,lr,lu,ls,lw,lwr,plans]=await Promise.all([api('/api/compliance/overview'),api(`/api/obligations?site=${encodeURIComponent(site)}&category=${encodeURIComponent(cat)}&review=${encodeURIComponent(review)}&scope=${encodeURIComponent(scope)}&status=${encodeURIComponent(status)}`),api('/api/deadline-requests'),api('/api/legal-reviews'),api('/api/legal-updates'),api('/api/legal-sources'),api('/api/legal-watch/status'),api('/api/legal-watch/runs'),api('/api/compliance/plan-imports')]);
  state.obligations=obs;state.legalReviews=lr;state.legalUpdates=lu;state.legalSources=ls;state.legalWatch={status:lw,runs:lwr};
  const activeLR=lr.filter(x=>x.status==='needs_review'),activeLU=lu.filter(x=>x.status==='needs_review');
  const rows=obs.map(o=>{const p=Number(o.progress||o.task_progress||0),source=o.source_scope==='legal_extra'?pill('Ngoài KH','violet'):pill('KH năm','teal');return `<tr><td class="sticky-col c-site">${esc(o.site_code||'—')}</td><td>${o.source_stt??'—'}</td><td class="sticky-col c-action"><button class="linklike obDetail" data-id="${o.id}">${esc(o.title)}</button><div class="sub">${esc(o.source_goal||o.notes||'')}</div></td><td>${monthName(o.schedule_month)}</td><td>${esc(o.owner||'—')}<div class="sub">${esc(o.coordinator||'')}</div></td><td>${source}</td><td>${statusPill(o.display_status||o.status)}</td><td><div class="mini-progress">${progressBar(p)}</div></td><td>${o.current_due_date?fmtDate(o.current_due_date):'<span class="muted">Theo tháng</span>'}</td><td>${o.task_done||0}/${o.task_count||0}</td><td>${o.evidence_count||0}</td><td>${o.legal_review_status==='needs_review'?pill('Review','amber'):o.legal_review_status==='reviewed'?pill('Reviewed','green'):pill('—','gray')}</td><td class="actions">${o.current_due_date?`<button class="ghost changeDue" data-id="${o.id}">Đổi hạn</button>`:''}<button class="soft quickEvidence" data-type="obligation" data-id="${o.id}" data-site="${o.site_id||''}">+ Bằng chứng</button><button class="ghost obEdit" data-id="${o.id}">Cập nhật</button></td></tr>`}).join('');
  $('#app').innerHTML=`<div class="grid compliance-kpis">${kpi('Tổng obligation',overview.total,'Toàn hệ thống','#edf2ff')}${kpi('Đang thực hiện',overview.in_progress,'Workflow hiện tại','#edf2ff')}${kpi('Quá hạn',overview.overdue,'Cần xử lý ngay','#fff0f1')}${kpi('30 ngày tới',overview.due_30,'Sắp đến hạn','#fff6e2')}${kpi('Ngoài kế hoạch',overview.legal_extra,'Luật yêu cầu bổ sung','#f1edff')}${kpi('Legal review',overview.needs_legal_review,'Cần xác nhận','#fff6e2')}</div>
  <div class="toolbar compliance-toolbar"><select id="cSite"><option value="">Tất cả site</option>${state.sites.map(s=>`<option value="${s.code}" ${site===s.code?'selected':''}>${s.code}</option>`).join('')}</select><select id="cCat"><option value="">Tất cả nhóm</option>${[['fire','PCCC'],['chemical','Hóa chất'],['environment','Môi trường'],['osh','ATVSLĐ'],['equipment','Kiểm định'],['food','Bếp/VSATTP'],['other','Khác']].map(x=>`<option value="${x[0]}" ${cat===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select id="cScope"><option value="">Mọi nguồn</option><option value="annual_plan" ${scope==='annual_plan'?'selected':''}>Kế hoạch năm</option><option value="legal_extra" ${scope==='legal_extra'?'selected':''}>Ngoài kế hoạch - Luật</option></select><select id="cStatus"><option value="">Mọi trạng thái</option>${[['not_started','Chưa bắt đầu'],['in_progress','Đang thực hiện'],['waiting','Đang chờ'],['blocked','Bị chặn'],['completed','Hoàn thành']].map(x=>`<option value="${x[0]}" ${status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select id="cReview"><option value="">Tất cả legal review</option><option value="needs_review" ${review==='needs_review'?'selected':''}>Needs review</option><option value="reviewed" ${review==='reviewed'?'selected':''}>Reviewed</option></select><button class="primary" id="addLegalExtra">+ Ngoài kế hoạch</button><button class="ghost" id="planUploadBtn">↑ KH năm mới</button><button class="ghost" id="fullCompliance">⛶ Toàn màn hình</button><span class="muted">${obs.length} mục</span></div>
  <div id="complianceFull"><button class="fullscreen-close" id="closeComplianceFull" type="button" title="Thoát toàn màn hình (Esc)">× Thoát toàn màn hình</button><div class="top-scroll" id="complianceTopScroll"><div></div></div><div class="table-wrap compliance-table-wrap" id="complianceTable"><table class="compliance-table"><thead><tr><th class="sticky-col c-site">Site</th><th>STT</th><th class="sticky-col c-action">Hành động</th><th>Tháng</th><th>Owner</th><th>Nguồn</th><th>Trạng thái</th><th>Tiến độ</th><th>Deadline</th><th>Task</th><th>File</th><th>Legal</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>
  <div class="section grid two"><div class="card panel"><div class="section-head"><div><h2>Kế hoạch năm</h2><p>Upload mới được staging trước, không ghi đè kế hoạch hiện hành âm thầm.</p></div>${pill(`${plans.filter(x=>x.status==='pending_review').length} chờ review`,plans.some(x=>x.status==='pending_review')?'amber':'green')}</div><div class="list">${plans.slice(0,6).map(x=>`<div class="list-row"><div><div class="titleline">${esc(x.original_name||x.version_label||'Kế hoạch')}</div><div class="sub">${x.plan_year||'—'} · ${new Date(x.imported_at).toLocaleString('vi-VN')} · ${esc(x.note||'')}</div></div>${pill(x.status,x.status==='applied'?'green':'amber')}</div>`).join('')||'<div class="empty">Chưa staging kế hoạch mới</div>'}</div></div><div class="card panel"><div class="section-head"><div><h2>Legal / deadline review</h2><p>Legal extra được tách riêng khỏi kế hoạch năm</p></div></div><div class="mini-stats"><div><b>${activeLU.length}</b><span>Legal update</span></div><div><b>${activeLR.length}</b><span>Obligation review</span></div><div><b>${req.filter(x=>x.status==='pending').length}</b><span>Deadline request</span></div></div></div></div>
  <div class="section card panel legal-intel-card"><div class="section-head"><div><h2>Tra cứu luật nội bộ</h2><p>Tìm theo số hiệu / tên văn bản / cơ quan ban hành trong Legal Register và các nghĩa vụ đang quản lý.</p></div><span class="pill gray">Human review required</span></div><div class="toolbar legal-search-toolbar"><input id="legalSearchQ" placeholder="VD: 105/2025/NĐ-CP, hóa chất, PCCC…"><select id="legalSearchCat"><option value="">Tất cả nhóm</option><option value="chemical">Hóa chất</option><option value="environment">Môi trường</option><option value="fire">PCCC</option><option value="osh">ATVSLĐ</option><option value="equipment">Kiểm định</option></select><button class="primary" id="legalSearchBtn">Tra cứu</button></div><div class="notice">Kết quả trong app chỉ phản ánh nguồn đã được đưa vào hệ thống. Khi cần tra cứu toàn bộ hệ thống pháp luật, mở cổng chính thức bên dưới và chỉ cập nhật Legal Register sau khi EHS review.</div><div id="legalSearchResults" class="legal-search-results"><div class="empty">Nhập từ khóa để bắt đầu.</div></div></div>`;
  $('#cSite').onchange=$('#cCat').onchange=$('#cScope').onchange=$('#cStatus').onchange=$('#cReview').onchange=()=>compliance();
  $$('.changeDue').forEach(b=>b.onclick=()=>changeDue(b.dataset.id));$$('.obEdit').forEach(b=>b.onclick=()=>editObligation(b.dataset.id));$$('.quickEvidence').forEach(b=>b.onclick=()=>quickEvidence(b.dataset.type,b.dataset.id,b.dataset.site||null));$$('.obDetail').forEach(b=>b.onclick=()=>obligationDetail(b.dataset.id));$('#addLegalExtra').onclick=addLegalExtra;$('#planUploadBtn').onclick=stagePlanFile;
  const doLegalSearch=async()=>{const q=$('#legalSearchQ').value.trim(),cat=$('#legalSearchCat').value,box=$('#legalSearchResults');if(q.length<2){box.innerHTML='<div class="empty">Nhập ít nhất 2 ký tự.</div>';return}box.innerHTML='<div class="empty">Đang tra cứu…</div>';try{const out=await api(`/api/legal-search?q=${encodeURIComponent(q)}&category=${encodeURIComponent(cat)}`),r=out.results||{},sources=r.sources||[],obls=r.obligations||[],updates=r.updates||[];box.innerHTML=`<div class="legal-search-portals">${(out.official_portals||[]).map(x=>`<a class="ghost button-link" href="${esc(x.url)}" target="_blank" rel="noopener">↗ ${esc(x.name)}</a>`).join('')}</div><div class="grid two"><div><h3>Văn bản đã quản lý (${sources.length})</h3><div class="list">${sources.map(x=>`<div class="list-row"><div><div class="titleline">${esc(x.code)} · ${esc(x.title)}</div><div class="sub">${esc(x.document_type||'')} · ${esc(x.issuer||'—')} · hiệu lực ${fmtDate(x.effective_date)} · ${esc(x.category||'')}</div></div><a class="ghost button-link" target="_blank" rel="noopener" href="${esc(x.official_url)}">Nguồn</a></div>`).join('')||'<div class="empty">Không có văn bản khớp trong Legal Register.</div>'}</div></div><div><h3>Nghĩa vụ liên quan (${obls.length})</h3><div class="list">${obls.map(x=>`<div class="list-row"><div><div class="titleline">${esc(x.title)}</div><div class="sub">${esc(x.legal_basis||'Chưa có căn cứ')} · ${fmtDate(x.current_due_date)} · ${esc(x.status||'')}</div></div></div>`).join('')||'<div class="empty">Chưa có obligation khớp.</div>'}</div></div></div>${updates.length?`<h3 style="margin-top:14px">Legal updates (${updates.length})</h3><div class="list">${updates.map(x=>`<div class="list-row"><div><div class="titleline">${esc(x.code)} · ${esc(x.summary)}</div><div class="sub">${esc(x.impact_level)} · ${esc(x.status)} · ${new Date(x.detected_at).toLocaleString('vi-VN')}</div></div></div>`).join('')}</div>`:''}<div class="sub" style="margin-top:10px">${esc(out.note||'')}</div>`}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}};$('#legalSearchBtn').onclick=doLegalSearch;$('#legalSearchQ').onkeydown=e=>{if(e.key==='Enter')doLegalSearch()};
  const top=$('#complianceTopScroll'),wrap=$('#complianceTable'),sync=()=>{top.firstElementChild.style.width=wrap.scrollWidth+'px'};sync();top.onscroll=()=>{wrap.scrollLeft=top.scrollLeft};wrap.onscroll=()=>{top.scrollLeft=wrap.scrollLeft};const fullBox=$('#complianceFull'),fullBtn=$('#fullCompliance'),closeFull=$('#closeComplianceFull');const setFull=on=>{fullBox.classList.toggle('fullscreen-table',!!on);document.body.classList.toggle('no-page-scroll',!!on);fullBtn.textContent=on?'↙ Thu nhỏ':'⛶ Toàn màn hình';requestAnimationFrame(sync)};fullBtn.onclick=()=>setFull(!fullBox.classList.contains('fullscreen-table'));closeFull.onclick=()=>setFull(false);if(window.__complianceEscHandler)document.removeEventListener('keydown',window.__complianceEscHandler);window.__complianceEscHandler=e=>{if(e.key==='Escape'&&fullBox.classList.contains('fullscreen-table'))setFull(false)};document.addEventListener('keydown',window.__complianceEscHandler);applyPermissionUI();
}
function editObligation(id){const o=state.obligations.find(x=>x.id===id);modal('Cập nhật Compliance',`<div class="form-grid"><div class="field full"><label>${esc(o.title)}</label><div class="sub">${o.source_scope==='legal_extra'?'Ngoài kế hoạch - yêu cầu pháp luật':'Kế hoạch năm'}</div></div><div class="field"><label>Trạng thái</label><select id="obStatus">${[['not_started','Chưa bắt đầu'],['in_progress','Đang thực hiện'],['waiting','Đang chờ'],['blocked','Bị chặn'],['completed','Hoàn thành']].map(x=>`<option value="${x[0]}" ${o.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label>Tiến độ %</label><input id="obProgress" type="number" min="0" max="100" value="${o.progress||0}"></div><div class="field"><label>Owner</label><input id="obOwner" value="${esc(o.owner||'')}"></div><div class="field"><label>Phối hợp</label><input id="obCoord" value="${esc(o.coordinator||'')}"></div><div class="field full"><label>Tình trạng / vướng mắc hiện tại</label><textarea id="obNote">${esc(o.status_note||'')}</textarea></div></div>`,async close=>{await api('/api/obligations',{method:'PATCH',body:JSON.stringify({id,status:$('#obStatus').value,progress:Number($('#obProgress').value||0),owner:$('#obOwner').value,coordinator:$('#obCoord').value,status_note:$('#obNote').value})});close();toast('Đã cập nhật compliance');compliance()})}
async function obligationDetail(id){const o=state.obligations.find(x=>x.id===id),tasks=await api('/api/tasks');const linked=tasks.filter(t=>t.linked_entity_type==='obligation'&&t.linked_entity_id===id);modal('Compliance detail',`<div class="ob-detail"><div class="detail-hero"><div><h3>${esc(o.title)}</h3><div class="sub">${esc(o.site_code||'—')} · ${esc(o.category)} · ${o.source_scope==='legal_extra'?'Ngoài kế hoạch':'Kế hoạch năm'}</div></div>${statusPill(o.display_status||o.status)}</div><div class="detail-grid"><div><span>Deadline</span><b>${fmtDate(o.current_due_date)}</b></div><div><span>Tiến độ</span><b>${o.progress||0}%</b></div><div><span>Owner</span><b>${esc(o.owner||'—')}</b></div><div><span>Legal</span><b>${esc(o.legal_basis||o.legal_review_status||'—')}</b></div></div><div class="notice">${esc(o.status_note||o.notes||'Chưa có ghi chú tình trạng.')}</div><h3>Task liên kết</h3><div class="list">${linked.map(t=>`<div class="list-row"><div><b>${esc(t.title)}</b><div class="sub">${fmtDate(t.due_date)} · ${t.progress||0}%</div></div>${statusPill(t.status)}</div>`).join('')||'<div class="empty">Chưa có task liên kết</div>'}</div></div>`,async close=>close(),'Đóng')}
function addLegalExtra(){modal('Thêm hồ sơ ngoài kế hoạch theo luật',`<div class="form-grid"><div class="field full"><label>Tên nghĩa vụ / hồ sơ *</label><input id="leTitle"></div><div class="field"><label>Nhóm *</label><select id="leCat"><option value="chemical">Hóa chất</option><option value="environment">Môi trường</option><option value="fire">PCCC</option><option value="osh">ATVSLĐ</option><option value="equipment">Kiểm định</option><option value="other">Khác</option></select></div><div class="field"><label>Site</label><select id="leSite"><option value="">Chung</option>${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`).join('')}</select></div><div class="field full"><label>Căn cứ pháp lý *</label><textarea id="leLegal"></textarea></div><div class="field"><label>Deadline</label><input id="leDue" type="date"></div><div class="field"><label>Owner</label><input id="leOwner" value="Phòng EHS"></div><div class="field full"><label>Ghi chú</label><textarea id="leNote"></textarea></div></div>`,async close=>{await api('/api/compliance/legal-extra',{method:'POST',body:JSON.stringify({title:$('#leTitle').value,category:$('#leCat').value,site_id:$('#leSite').value||null,legal_basis:$('#leLegal').value,due_date:$('#leDue').value||null,owner:$('#leOwner').value,notes:$('#leNote').value})});close();toast('Đã thêm nghĩa vụ ngoài kế hoạch');compliance()})}
function stagePlanFile(){modal('Tải kế hoạch EHS năm mới',`<div class="notice">CP5 lưu file như một plan version mới ở trạng thái chờ review. Kế hoạch hiện hành không bị overwrite trước khi mapping/xác nhận.</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>File kế hoạch *</label><input id="planFile" type="file" accept=".xlsx,.xls,.xlsm,.csv,.pdf"></div><div class="field"><label>Năm</label><input id="planYear" type="number" value="${new Date().getFullYear()+1}"></div><div class="field"><label>Version</label><input id="planVersion" placeholder="VD: Rev 01"></div><div class="field full"><label>Ghi chú</label><textarea id="planNote"></textarea></div></div>`,async close=>{const f=$('#planFile').files[0];if(!f)throw new Error('Chọn file kế hoạch');const doc=await uploadRawDocument(f,'annual_plan',state.sites[0]?.id||null);await api('/api/compliance/plan-import',{method:'POST',body:JSON.stringify({document_id:doc.id,plan_year:Number($('#planYear').value),version_label:$('#planVersion').value,note:$('#planNote').value})});close();toast('Đã staging kế hoạch mới · chờ review');compliance()},'Tải lên')}

async function uploadRawDocument(file,category='other',site_id=null,linked_entity_type=null,linked_entity_id=null){const base64=await new Promise((ok,err)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=err;r.readAsDataURL(file)});return api('/api/documents',{method:'POST',body:JSON.stringify({original_name:file.name,mime_type:file.type||'application/octet-stream',base64,category,site_id,linked_entity_type,linked_entity_id})})}

