  advance_other:{label:'Đề nghị tạm ứng khác',parent:'Đề nghị tạm ứng khác',description:'Phục vụ khóa huấn luyện hoặc tạm ứng phục vụ công việc ngoại giao',docs:[{name:'Đề nghị tạm ứng (SSE)'},{name:'Tờ trình (Photo và lưu bản sao)'}]},
