  settlement_vendor_advance:{label:'Quyết toán tạm ứng NCC',parent:'Quyết toán tạm ứng NCC',description:'Quyết toán cho đề nghị tạm ứng NCC',docs:[{name:'Đề nghị quyết toán tạm ứng (SSE)'},{name:'Tờ trình (bản sao đã lưu)'},{name:'Hóa đơn dịch vụ',optional:true},{name:'Biên bản nghiệm thu',optional:true},{name:'Bản sao kết quả (đối với khóa học)',optional:true}]},
  payment_external:{label:'Hạng mục 3 · đối ngoại',parent:'Đề nghị thanh toán khác',description:'Chi cho các khoản đối ngoại',docs:[{name:'Đề nghị thanh toán khác'},{name:'Tờ trình (ghi rõ “Chi hạng mục 3 - Không có hóa đơn”)'}]},
  waste:{label:'Rác thải / chất thải',parent:'Đề nghị thanh toán khác',description:'Thanh toán dịch vụ rác thải/chất thải',docs:[{name:'Đề nghị thanh toán khác'},{name:'Hóa đơn'},{name:'Biên bản nghiệm thu'},{name:'Hợp đồng (bản sao photo)'},{name:'Phiếu cân'}]},
