  standard:{label:'Hạng mục bình thường',parent:'Đề nghị thanh toán khác',description:'Thanh toán dịch vụ/hạng mục thông thường',docs:[{name:'Đề nghị thanh toán khác'},{name:'Tờ trình'},{name:'Hóa đơn'},{name:'Biên bản nghiệm thu'},{name:'Hợp đồng (>5 triệu)',conditional:true}]},
