const paymentFlowGroups={
  advance_other:{label:'Đề nghị tạm ứng khác',categories:['advance_other']},advance_vendor:{label:'Đề nghị tạm ứng NCC',categories:['advance_vendor']},settlement_advance:{label:'Quyết toán tạm ứng',categories:['settlement_advance']},settlement_vendor_advance:{label:'Quyết toán tạm ứng NCC',categories:['settlement_vendor_advance']},payment_other:{label:'Đề nghị thanh toán khác',categories:['payment_external','waste','environment_monitoring','standard','other']}
};
function paymentFlowForCategory(c){return Object.values(paymentFlowGroups).find(g=>g.categories.includes(c))?.label||paymentTypes[c]?.parent||'Khác'}
payments = async function(){
  [state.payments,state.vendors,state.contracts]=await Promise.all([api('/api/payments'),api('/api/vendors'),api('/api/contracts')]);
  $('#app').innerHTML=`<div class="toolbar"><button class="primary" id="addPayment">+ Hồ sơ thanh toán</button><span class="muted">${state.payments.length} hồ sơ · Tracking only, không phải kế toán</span></div><div class="grid payment-grid">${state.payments.map(p=>{const required=p.docs.filter(x=>x.required),linked=required.filter(x=>x.evidence_state==='linked').length,declared=required.filter(x=>x.evidence_state==='declared').length,tot=required.length,n=days(p.contractual_due_date),intel=p.intelligence||{};return `<div class="card payment"><div class="payment-top">${n<0&&p.status!=='paid'?pill(`Overdue ${-n}d`,'red'):statusPill(p.status)}<div class="actions"><button class="soft quickEvidence" data-type="payment" data-id="${p.id}" data-site="${p.site_id||''}">+ File</button><button class="ghost editPayment" data-id="${p.id}">Edit</button></div></div><h3>${esc(p.title)}</h3><div class="vendor">${esc(p.vendor_name)} · ${esc(p.site_code||'—')}</div><div class="payment-type-line">${pill(paymentFlowForCategory(p.category),'violet')} ${pill(paymentTypes[p.category]?.label||p.category,'gray')}</div><div class="money">${fmtMoney(p.amount)}</div><div class="sub">Invoice ${esc(p.invoice_no||'—')} · ${fmtDate(p.invoice_date)}</div><div class="sub">Contract due: <b>${fmtDate(p.contractual_due_date)}</b> · Planned: <b>${fmtDate(p.planned_payment_date)}</b></div>${p.explanation_if_late?`<div class="late-note">${esc(p.explanation_if_late)}</div>`:''}<div class="evidence-meter"><div><b>${linked}/${tot}</b><span>file đã link</span></div><div><b>${declared}</b><span>chỉ khai báo có</span></div><div><b>${intel.accepted_docs||0}</b><span>OCR duyệt</span></div></div><div class="progress"><i style="width:${tot?linked/tot*100:0}%"></i></div><div class="checklist">${p.docs.map(d=>`<div class="check payment-doc-row"><span class="evidence-dot ${d.evidence_state}"></span><span>${esc(d.doc_type)}${!d.required?' (không bắt buộc)':''}</span><span class="sub">${d.evidence_state==='linked'?'Đã có file':d.evidence_state==='declared'?'Đã khai báo · chưa file':'Thiếu'}</span><input class="docToggle" data-id="${d.id}" type="checkbox" ${d.received?'checked':''}></div>`).join('')}</div></div>`}).join('')||'<div class="card empty">Chưa có hồ sơ thanh toán</div>'}</div>`;
  $('#addPayment').onclick=createPayment;$$('.docToggle').forEach(c=>c.onchange=async()=>{await api('/api/payments/doc-toggle',{method:'POST',body:JSON.stringify({id:c.dataset.id,received:c.checked})});toast('Đã cập nhật khai báo checklist');payments()});$$('.editPayment').forEach(b=>b.onclick=()=>editPayment(b.dataset.id));$$('.quickEvidence').forEach(b=>b.onclick=()=>quickEvidence(b.dataset.type,b.dataset.id,b.dataset.site||null));applyPermissionUI();
}
function createPayment(){
  modal('Tạo hồ sơ thanh toán',`<div class="form-grid"><div class="field"><label>NCC *</label><select id="npVendor"><option value="">Chọn NCC</option>${state.vendors.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label>Loại thanh toán *</label><select id="npFlow">${Object.entries(paymentFlowGroups).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></div><div class="field full" id="npSubtypeWrap"><label>Hạng mục / loại chi tiết</label><select id="npType"></select><div id="npTypeDesc" class="sub"></div></div><div class="field full"><label>Hạng mục *</label><input id="npTitle" placeholder="VD: Thu gom rác tháng 10/2026"></div><div class="field"><label>Site</label><select id="npSite"><option value="">Chung</option>${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`).join('')}</select></div><div class="field"><label>Hợp đồng</label><select id="npContract"><option value="">Không/chưa chọn</option></select></div><div class="field"><label>Số hóa đơn</label><input id="npInvoice"></div><div class="field"><label>Ngày hóa đơn</label><input id="npInvoiceDate" type="date"></div><div class="field"><label>Số tiền</label><input id="npAmount" type="number" min="0"></div><div class="field"><label>Ngày dự kiến nội bộ</label><input id="npPlanned" type="date"></div><div class="field full"><label>Checklist tự sinh từ quy trình hiện tại</label><div id="npChecklist" class="checklist-preview"></div><div class="sub">Rule: hóa đơn &gt; 5 triệu cần hợp đồng; hợp đồng mới cần photo bản sao; đủ bộ thì scan lưu mềm.</div></div><div class="field full"><label>Giải trình nếu planned muộn hơn hạn HĐ</label><textarea id="npWhy"></textarea></div></div>`,async close=>{const out=await api('/api/payments',{method:'POST',body:JSON.stringify({vendor_id:$('#npVendor').value,title:$('#npTitle').value,category:$('#npType').value,site_id:$('#npSite').value||null,contract_id:$('#npContract').value||null,invoice_no:$('#npInvoice').value,invoice_date:$('#npInvoiceDate').value||null,amount:Number($('#npAmount').value||0),planned_payment_date:$('#npPlanned').value||null,explanation_if_late:$('#npWhy').value})});close();toast(`Đã tạo hồ sơ · due ${out.contractual_due_date?fmtDate(out.contractual_due_date):'chưa xác định'}`);payments()},'Tạo hồ sơ');
  setTimeout(()=>{const renderSubtype=()=>{const cats=paymentFlowGroups[$('#npFlow').value].categories;$('#npType').innerHTML=cats.map(k=>`<option value="${k}">${paymentTypes[k].label}</option>`).join('');$('#npSubtypeWrap').style.display=cats.length===1?'none':'flex';renderChecklist()};const renderChecklist=()=>{const t=paymentTypes[$('#npType').value];if(!t)return;$('#npTypeDesc').textContent=t.description||'';$('#npChecklist').innerHTML=t.docs.map(x=>`<span class="pill ${x.optional?'gray':x.conditional?'amber':'blue'}">${esc(x.name)}${x.optional?' · nếu có':x.conditional?' · theo điều kiện':''}</span>`).join(' ')};const renderContracts=()=>{const v=$('#npVendor').value;$('#npContract').innerHTML='<option value="">Không/chưa chọn</option>'+state.contracts.filter(c=>!v||c.vendor_id===v).map(c=>`<option value="${c.id}">${esc(c.contract_no||c.title)} · ${c.payment_term_days||'—'} ngày</option>`).join('')};$('#npFlow').onchange=renderSubtype;$('#npType').onchange=renderChecklist;$('#npVendor').onchange=renderContracts;renderSubtype();renderContracts()},0)
}

equipment = async function(){
  const reqs=[api('/api/equipment'),api('/api/employees?status=active')];if(can('documents.read'))reqs.push(api('/api/documents'));const out=await Promise.all(reqs);state.equipment=out[0];state.employees=out[1];if(out[2])state.documents=out[2];
  const needReview=state.equipment.filter(e=>e.review_status==='needs_review').length,expired=state.equipment.filter(e=>e.inspection_state==='expired').length;
  $('#app').innerHTML=`<div class="toolbar"><button class="primary" id="addEq">+ Thiết bị</button><span class="muted">${state.equipment.length} asset · ${needReview} cần rà nguồn · ${expired} hết hạn kiểm định</span></div><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Thiết bị</th><th>Nguồn/Review</th><th>Vị trí</th><th>Kiểm định gần nhất</th><th>Tiếp theo</th><th>Quản lý</th><th></th></tr></thead><tbody>${state.equipment.map(e=>{const due=e.inspection_state==='expired'?pill(fmtDate(e.next_inspection_date),'red'):e.inspection_state==='due_60'?pill(fmtDate(e.next_inspection_date),'amber'):fmtDate(e.next_inspection_date);return `<tr><td><b>${esc(e.asset_code)}</b><div class="sub">${esc(e.model||'')}</div></td><td><b>${esc(e.name)}</b><div class="sub">${esc(e.manufacturer||'—')} · ${esc(e.serial_no||'—')}</div>${e.strict_control?pill('Nghiêm ngặt','violet'):pill('Chưa xác định','gray')}</td><td>${e.review_status==='needs_review'?pill('Needs review','amber'):pill('Reviewed','green')}<div class="sub">${esc(e.source_ref||'manual')}</div></td><td>${esc(e.site_code||'—')} · ${esc(e.location||'—')}</td><td>${fmtDate(e.last_inspection_date)}<div class="sub">${e.inspection_count||0} lịch sử</div></td><td>${due}</td><td>${esc(e.manager||'—')}<div class="sub">${esc(e.department||'')} ${e.operator?'· vận hành '+esc(e.operator):''}</div></td><td class="actions"><button class="ghost eqHistory" data-id="${e.id}">Lịch sử</button><button class="ghost eqEdit" data-id="${e.id}">Sửa</button>${e.review_status==='needs_review'?`<button class="ghost eqReconcile" data-id="${e.id}">Đối chiếu</button>`:''}<button class="soft quickEvidence" data-type="equipment" data-id="${e.id}" data-site="${e.site_id||''}">+ File</button><button class="soft eqInspect" data-id="${e.id}">+ Kiểm định</button></td></tr>`}).join('')}</tbody></table></div>`;
  $('#addEq').onclick=addEq;$$('.eqInspect').forEach(b=>b.onclick=()=>recordInspection(b.dataset.id));$$('.eqHistory').forEach(b=>b.onclick=()=>equipmentHistory(b.dataset.id));$$('.eqEdit').forEach(b=>b.onclick=()=>editEquipment(b.dataset.id));$$('.eqReconcile').forEach(b=>b.onclick=()=>reconcileEquipment(b.dataset.id));$$('.quickEvidence').forEach(b=>b.onclick=()=>quickEvidence(b.dataset.type,b.dataset.id,b.dataset.site||null));applyPermissionUI();
}
editEquipment = function(id){const e=state.equipment.find(x=>x.id===id),labels=uniqueEmployeeLabels(state.employees||[]);const employeeOpts=(selected)=>`<option value="">Không gắn Employee Master</option>${state.employees.map(x=>`<option value="${x.id}" ${selected===x.id?'selected':''}>${esc(labels.get(x.id))}</option>`).join('')}`;modal('Sửa toàn bộ thông tin thiết bị',`<div class="form-grid"><div class="field"><label>Asset code</label><input id="eeCode" value="${esc(e.asset_code||'')}"></div><div class="field"><label>Tên thiết bị</label><input id="eeName" value="${esc(e.name||'')}"></div><div class="field"><label>Category</label><input id="eeCat" value="${esc(e.category||'')}"></div><div class="field"><label>Hãng</label><input id="eeMaker" value="${esc(e.manufacturer||'')}"></div><div class="field"><label>Model</label><input id="eeModel" value="${esc(e.model||'')}"></div><div class="field"><label>Serial</label><input id="eeSerial" value="${esc(e.serial_no||'')}"></div><div class="field"><label>Năm SX</label><input id="eeYear" value="${esc(e.manufacture_year||'')}"></div><div class="field"><label>Xuất xứ</label><input id="eeCountry" value="${esc(e.source_country||'')}"></div><div class="field"><label>Site</label><select id="eeSite"><option value="">Chưa xác định</option>${state.sites.map(s=>`<option value="${s.id}" ${e.site_id===s.id?'selected':''}>${s.code}</option>`).join('')}</select></div><div class="field"><label>Vị trí</label><input id="eeLoc" value="${esc(e.location||'')}"></div><div class="field"><label>Bộ phận quản lý</label><input id="eeDept" value="${esc(e.department||'')}"></div><div class="field"><label>Người quản lý</label><input id="eeManager" value="${esc(e.manager||'')}"></div><div class="field"><label>Gắn NV quản lý</label><select id="eeManagerEmp">${employeeOpts(e.manager_employee_id)}</select></div><div class="field"><label>Người vận hành</label><input id="eeOperator" value="${esc(e.operator||'')}"></div><div class="field"><label>Gắn NV vận hành</label><select id="eeOperatorEmp">${employeeOpts(e.operator_employee_id)}</select></div><div class="field"><label>Ngày kiểm định gần nhất</label><input id="eeLast" type="date" value="${esc(e.last_inspection_date||'')}"></div><div class="field"><label>Hạn/kiểm định tiếp theo</label><input id="eeNext" type="date" value="${esc(e.next_inspection_date||'')}"></div><div class="field"><label>Đơn vị kiểm định</label><input id="eeOrg" value="${esc(e.inspector_org||'')}"></div><div class="field"><label>Trạng thái</label><select id="eeStatus"><option value="active" ${e.status==='active'?'selected':''}>Active</option><option value="repair_hold" ${e.status==='repair_hold'?'selected':''}>Hỏng / hold</option><option value="retired" ${e.status==='retired'?'selected':''}>Retired</option></select></div><div class="field"><label>Nhắc trước (ngày)</label><input id="eeRemind" type="number" min="0" value="${e.inspection_reminder_days??30}"></div><div class="field full"><label>Căn cứ pháp lý</label><textarea id="eeLegal">${esc(e.legal_basis||'')}</textarea></div><div class="field full"><label>Điều kiện/ngưỡng áp dụng</label><textarea id="eeApply">${esc(e.applicability_condition||'')}</textarea></div><div class="field full"><label>Ghi chú</label><textarea id="eeRemarks">${esc(e.remarks||'')}</textarea></div><div class="field"><label><input id="eeStrict" type="checkbox" ${e.strict_control?'checked':''}> Thiết bị nghiêm ngặt</label></div><div class="field"><label><input id="eeReviewed" type="checkbox" ${e.review_status==='reviewed'?'checked':''}> Đã đối chiếu nguồn</label></div></div>`,async close=>{const me=state.employees.find(x=>x.id===$('#eeManagerEmp').value),op=state.employees.find(x=>x.id===$('#eeOperatorEmp').value);await api('/api/equipment',{method:'PATCH',body:JSON.stringify({id,asset_code:$('#eeCode').value,name:$('#eeName').value,category:$('#eeCat').value,manufacturer:$('#eeMaker').value,model:$('#eeModel').value,serial_no:$('#eeSerial').value,manufacture_year:$('#eeYear').value,source_country:$('#eeCountry').value,site_id:$('#eeSite').value||null,location:$('#eeLoc').value,department:$('#eeDept').value,manager_employee_id:$('#eeManagerEmp').value||null,manager:me?.full_name||$('#eeManager').value,operator_employee_id:$('#eeOperatorEmp').value||null,operator:op?.full_name||$('#eeOperator').value,last_inspection_date:$('#eeLast').value||null,next_inspection_date:$('#eeNext').value||null,inspector_org:$('#eeOrg').value,status:$('#eeStatus').value,inspection_reminder_days:Number($('#eeRemind').value||0),legal_basis:$('#eeLegal').value,applicability_condition:$('#eeApply').value,remarks:$('#eeRemarks').value,strict_control:$('#eeStrict').checked,review_status:$('#eeReviewed').checked?'reviewed':'needs_review'})});close();toast('Đã cập nhật toàn bộ asset');equipment()})}
recordInspection = function(id){const e=state.equipment.find(x=>x.id===id);modal('Ghi nhận kiểm định',`<div class="form-grid"><div class="field full"><label>${esc(e.asset_code)} · ${esc(e.name)}</label></div><div class="field"><label>Ngày kiểm định *</label><input id="iDate" type="date"></div><div class="field"><label>Hạn/kiểm định tiếp theo</label><input id="iNext" type="date"></div><div class="field"><label>Kết quả *</label><select id="iResult"><option value="pass">Đạt</option><option value="conditional">Có điều kiện</option><option value="fail">Không đạt</option></select></div><div class="field"><label>Đơn vị kiểm định</label><input id="iOrg"></div><div class="field"><label>Số tem/chứng thư</label><input id="iCert"></div><div class="field"><label>Chứng thư (upload mới)</label><input id="iCertFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp"></div><div class="field full"><label>Ảnh thiết bị / tem kiểm định</label><input id="iPhotos" type="file" accept="image/*" multiple><div class="sub">Có thể chọn nhiều ảnh.</div></div><div class="field full"><label>Ghi chú</label><textarea id="iNote"></textarea></div></div>`,async close=>{let cert=null;const cf=$('#iCertFile').files[0];if(cf)cert=(await uploadRawDocument(cf,'equipment',e.site_id)).id;const photoIds=[];for(const f of [...$('#iPhotos').files])photoIds.push((await uploadRawDocument(f,'equipment',e.site_id)).id);await api('/api/equipment/inspection',{method:'POST',body:JSON.stringify({equipment_id:id,inspection_date:$('#iDate').value,next_due_date:$('#iNext').value,result:$('#iResult').value,inspector_org:$('#iOrg').value,certificate_no:$('#iCert').value,document_id:cert,photo_document_ids:photoIds,notes:$('#iNote').value})});close();toast(`Đã ghi kiểm định · ${photoIds.length} ảnh`);equipment()})}
equipmentHistory = async function(id){const rows=await api(`/api/equipment/inspections?equipment_id=${encodeURIComponent(id)}`);modal('Lịch sử kiểm định',`<div class="inspection-timeline">${rows.map(i=>`<div class="inspection-event"><div class="timeline-dot"></div><div class="card panel"><div class="section-head"><div><b>${fmtDate(i.inspection_date)} · ${esc(i.inspection_type||'periodic')}</b><div class="sub">${esc(i.inspector_org||'—')} · tem/chứng thư ${esc(i.certificate_no||'—')} · next ${fmtDate(i.next_due_date)}</div></div>${pill(i.result,i.result==='pass'?'green':i.result==='fail'?'red':'amber')}</div><div class="attachment-grid">${(i.attachments||[]).map(a=>a.mime_type?.startsWith('image/')?`<a href="/api/documents/file?id=${encodeURIComponent(a.document_id)}" target="_blank" class="photo-thumb"><img src="/api/documents/file?id=${encodeURIComponent(a.document_id)}" alt="${esc(a.original_name)}"><span>${esc(a.original_name)}</span></a>`:`<a href="/api/documents/file?id=${encodeURIComponent(a.document_id)}" class="file-chip">📄 ${esc(a.original_name)}</a>`).join('')}</div>${i.notes?`<div class="sub">${esc(i.notes)}</div>`:''}</div></div>`).join('')||'<div class="empty">Chưa có lịch sử kiểm định</div>'}</div>`,async close=>close(),'Đóng')}

tasks = async function(){const status=$('#taskStatus')?.value||'',rows=await api(`/api/tasks?status=${encodeURIComponent(status)}`);state.tasks=rows;const open=rows.filter(t=>!['completed','cancelled'].includes(t.status));$('#app').innerHTML=`<div class="toolbar"><button class="primary" id="addTask">+ Task</button><select id="taskStatus"><option value="">Mọi trạng thái</option>${[['not_started','Chưa bắt đầu'],['in_progress','Đang thực hiện'],['waiting','Đang chờ'],['blocked','Bị chặn'],['completed','Hoàn thành']].map(x=>`<option value="${x[0]}" ${status===x[0]?'selected':''}>${x[1]}</option>`)}</select><span class="muted">${open.length} việc chưa đóng</span></div><div class="task-board">${rows.map(t=>`<div class="card task-card ${t.status}"><div class="task-top"><div>${statusPill(t.status)} ${pill(t.priority||'medium',t.priority==='high'?'red':t.priority==='medium'?'amber':'gray')}</div><div class="actions"><button class="soft quickEvidence" data-type="task" data-id="${t.id}" data-site="${t.site_id||''}">+ File</button><button class="ghost taskEdit" data-id="${t.id}">Sửa</button>${t.status!=='completed'?`<button class="soft taskDone" data-id="${t.id}">✓ Hoàn thành</button>`:''}</div></div><h3>${esc(t.title)}</h3><div class="sub">${esc(t.category||'—')} · ${esc(t.owner||'—')} · ${esc(t.site_code||'—')}</div><div class="task-due ${days(t.due_date)<0&&t.status!=='completed'?'late':''}">Deadline: <b>${fmtDate(t.due_date)}</b>${t.source_due_date?` · nguồn ${fmtDate(t.source_due_date)}`:''} ${t.deadline_sync_state==='changed'?pill('Deadline nguồn đã đổi','amber'):''}</div>${progressBar(t.progress)}${t.linked_title?`<div class="linked-chip">↳ ${esc(t.linked_entity_type)}: ${esc(t.linked_title)}</div>`:''}${t.blocked_reason?`<div class="late-note">Blocked: ${esc(t.blocked_reason)}</div>`:''}${t.notes?`<div class="sub task-note">${esc(t.notes)}</div>`:''}</div>`).join('')||'<div class="card empty">Không có task</div>'}</div>`;$('#addTask').onclick=quickTask;$('#taskStatus').onchange=()=>tasks();$$('.taskEdit').forEach(b=>b.onclick=()=>editTask(b.dataset.id));$$('.quickEvidence').forEach(b=>b.onclick=()=>quickEvidence(b.dataset.type,b.dataset.id,b.dataset.site||null));$$('.taskDone').forEach(b=>b.onclick=async()=>{await api('/api/tasks',{method:'PATCH',body:JSON.stringify({id:b.dataset.id,status:'completed',progress:100})});toast('Đã hoàn thành task');tasks()});applyPermissionUI()}
quickTask = function(){const obs=state.obligations||[];modal('Tạo task',`<div class="form-grid"><div class="field full"><label>Nội dung *</label><input id="tTitle"></div><div class="field"><label>Deadline</label><input id="tDue" type="date"></div><div class="field"><label>Owner</label><input id="tOwner" value="EHS"></div><div class="field"><label>Status</label><select id="tStatus"><option value="not_started">Chưa bắt đầu</option><option value="in_progress">Đang thực hiện</option><option value="waiting">Đang chờ</option><option value="blocked">Bị chặn</option></select></div><div class="field"><label>Tiến độ %</label><input id="tProgress" type="number" min="0" max="100" value="0"></div><div class="field"><label>Priority</label><select id="tPriority"><option>medium</option><option>high</option><option>low</option></select></div><div class="field"><label>Category</label><select id="tCat"><option>Compliance</option><option>PCCC</option><option>Chemical</option><option>Environment</option><option>PPE</option><option>Payment</option><option>Equipment</option></select></div><div class="field"><label>Site</label><select id="tSite">${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`).join('')}</select></div><div class="field full"><label>Liên kết Compliance (tuỳ chọn)</label><select id="tOb"><option value="">Không link</option>${obs.slice(0,400).map(o=>`<option value="${o.id}">${esc(o.site_code||'—')} · ${esc(o.title)}</option>`).join('')}</select></div><div class="field full"><label>Ghi chú</label><textarea id="tNotes"></textarea></div></div>`,async close=>{const oid=$('#tOb').value;await api('/api/tasks',{method:'POST',body:JSON.stringify({title:$('#tTitle').value,due_date:$('#tDue').value||null,owner:$('#tOwner').value,category:$('#tCat').value,site_id:$('#tSite').value,status:$('#tStatus').value,progress:Number($('#tProgress').value||0),priority:$('#tPriority').value,notes:$('#tNotes').value,linked_entity_type:oid?'obligation':null,linked_entity_id:oid||null})});close();toast('Đã tạo task');if(state.view==='tasks')tasks()})}
function editTask(id){const t=state.tasks.find(x=>x.id===id);modal('Cập nhật task',`<div class="form-grid"><div class="field full"><label>${esc(t.title)}</label></div><div class="field"><label>Status</label><select id="teStatus">${[['not_started','Chưa bắt đầu'],['in_progress','Đang thực hiện'],['waiting','Đang chờ'],['blocked','Bị chặn'],['completed','Hoàn thành'],['cancelled','Hủy']].map(x=>`<option value="${x[0]}" ${t.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label>Tiến độ %</label><input id="teProgress" type="number" min="0" max="100" value="${t.progress||0}"></div><div class="field"><label>Deadline</label><input id="teDue" type="date" value="${t.due_date||''}"></div><div class="field"><label>Owner</label><input id="teOwner" value="${esc(t.owner||'')}"></div><div class="field"><label>Priority</label><select id="tePriority"><option ${t.priority==='low'?'selected':''}>low</option><option ${t.priority==='medium'?'selected':''}>medium</option><option ${t.priority==='high'?'selected':''}>high</option></select></div><div class="field full"><label>Blocked reason</label><input id="teBlocked" value="${esc(t.blocked_reason||'')}"></div><div class="field full"><label>Ghi chú tiến độ</label><textarea id="teNotes">${esc(t.notes||'')}</textarea></div>${t.source_due_date?`<div class="field full"><div class="notice">Deadline nguồn: ${fmtDate(t.source_due_date)} · ${esc(t.deadline_sync_state)}. Đổi deadline task sẽ được ghi audit.</div></div>`:''}</div>`,async close=>{await api('/api/tasks',{method:'PATCH',body:JSON.stringify({id,status:$('#teStatus').value,progress:Number($('#teProgress').value||0),due_date:$('#teDue').value||null,owner:$('#teOwner').value,priority:$('#tePriority').value,blocked_reason:$('#teBlocked').value,notes:$('#teNotes').value})});close();toast('Đã cập nhật task');tasks()})}


// ===== Checkpoint 5.3: EHS Officer Daily Workflow =====
function dueBadge(d){const n=days(d);if(n==null)return pill('Không deadline','gray');if(n<0)return pill(`Quá ${-n}d`,'red');if(n===0)return pill('Hôm nay','red');if(n<=7)return pill(`${n}d`,'amber');return pill(fmtDate(d),'blue')}
async function quickEvidence(entityType,entityId,siteId=null){if(!can('documents.write'))return toast('Tài khoản không có quyền upload evidence',true);let payment=null,opts='';if(entityType==='payment'){const ps=state.payments?.length?state.payments:await api('/api/payments');payment=ps.find(x=>x.id===entityId);if(payment)opts=payment.docs.map(d=>`<option value="${esc(d.doc_type)}">${esc(d.doc_type)}${d.document_id?' · đã có file':''}</option>`).join('')}modal('Thêm bằng chứng',`<div class="form-grid"><div class="field full"><div class="notice">File được link trực tiếp vào ${esc(entityType)} và lưu Audit Trail. File gốc không bị overwrite.</div></div>${entityType==='payment'?`<div class="field full"><label>Loại chứng từ *</label><select id="evType">${opts||'<option>Hồ sơ khác</option>'}</select></div>`:''}<div class="field full"><label>File *</label><input id="evFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.xlsm,.jpg,.jpeg,.png,.webp"></div><div class="field full"><label>Ghi chú</label><input id="evNote" placeholder="VD: bằng chứng hoàn thành / chứng từ bổ sung"></div></div>`,async close=>{const f=$('#evFile').files[0];if(!f)throw new Error('Chọn file evidence');const cat=entityType==='payment'?'payment':entityType==='obligation'?'compliance':entityType;const doc=await uploadRawDocument(f,cat,siteId,entityType,entityId);await api('/api/evidence/link',{method:'POST',body:JSON.stringify({document_id:doc.id,entity_type:entityType,entity_id:entityId,evidence_type:entityType==='payment'?$('#evType').value:'evidence',note:$('#evNote').value})});close();toast('Đã link bằng chứng');render()},'Upload & link')}

async function myDay(){const [d,q]=await Promise.all([api('/api/my-day'),api('/api/data-quality')]);state.payments=d.payments||[];const urgent=(d.tasks||[]).filter(x=>(x.due_date&&days(x.due_date)<=0)||x.status==='blocked').length+(d.obligations||[]).filter(x=>x.current_due_date&&days(x.current_due_date)<=0).length;$('#app').innerHTML=`<div class="grid myday-kpis">${kpi('Ưu tiên ngay',urgent,'overdue / blocked','#fff0f1')}${kpi('Task 7 ngày',d.tasks.length,'đang mở','#edf2ff')}${kpi('Compliance cần nhìn',d.obligations.length,'tháng này / 30 ngày','#fff6e2')}${kpi('Inbox',d.inbox_count,'cần review/approval','#f1edff')}${kpi('Data quality',q.score+'/100','độ sạch dữ liệu','#eaf8f2')}</div><div class="myday-grid"><div class="stack"><div class="card panel"><div class="section-head"><div><h2>Việc của tôi</h2><p>Đang làm · blocked · đến hạn trong 7 ngày</p></div><button class="ghost goView" data-view="tasks">Tất cả Task</button></div><div class="list">${d.tasks.map(t=>`<div class="daily-row"><div><div class="titleline">${esc(t.title)}</div><div class="sub">${esc(t.site_code||'—')} · ${esc(t.owner||'—')} · ${t.progress||0}% · ${t.evidence_count||0} file</div></div><div class="actions">${statusPill(t.status)} ${dueBadge(t.due_date)}<button class="soft quickEvidence" data-type="task" data-id="${t.id}" data-site="${t.site_id||''}">+ evidence</button>${t.status!=='completed'?`<button class="primary dailyDone" data-id="${t.id}">✓</button>`:''}</div></div>`).join('')||'<div class="empty">Không có task cần xử lý gần</div>'}</div></div><div class="card panel"><div class="section-head"><div><h2>Compliance attention</h2><p>Đến hạn / kế hoạch tháng hiện tại</p></div><button class="ghost goView" data-view="compliance">Mở Compliance</button></div><div class="list">${d.obligations.map(o=>`<div class="daily-row"><div><div class="titleline">${esc(o.title)}</div><div class="sub">${esc(o.site_code||'—')} · ${esc(o.owner||'—')} · ${o.progress||0}% · ${o.evidence_count||0} evidence</div></div><div class="actions">${statusPill(o.status)} ${o.current_due_date?dueBadge(o.current_due_date):pill('Theo tháng','gray')}<button class="soft quickEvidence" data-type="obligation" data-id="${o.id}" data-site="${o.site_id||''}">+ evidence</button></div></div>`).join('')||'<div class="empty">Không có compliance attention</div>'}</div></div></div><div class="stack"><div class="card panel"><div class="section-head"><div><h2>Operations</h2><p>Payment & kiểm định</p></div></div>${d.payments.map(p=>`<div class="ops-card"><b>${esc(p.title)}</b><span>${esc(p.vendor_name)} · thiếu ${p.missing_docs||0} hồ sơ</span><div>${dueBadge(p.contractual_due_date)} <button class="soft quickEvidence" data-type="payment" data-id="${p.id}" data-site="${p.site_id||''}">+ file</button></div></div>`).join('')}${d.equipment.map(e=>`<div class="ops-card"><b>${esc(e.asset_code)} · ${esc(e.name)}</b><span>${esc(e.site_code||'—')} · ${esc(e.location||'—')}</span><div>${dueBadge(e.next_inspection_date)} <button class="soft quickEvidence" data-type="equipment" data-id="${e.id}" data-site="${e.site_id||''}">+ ảnh/file</button></div></div>`).join('')||'<div class="empty">Không có item sắp hạn</div>'}</div><div class="card panel"><div class="section-head"><div><h2>Inbox & Data Quality</h2><p>Xử lý trước audit</p></div><button class="primary goView" data-view="inbox">Mở Inbox (${d.inbox_count})</button></div><div class="quality-score"><strong>${q.score}</strong><span>/100</span></div><div class="list">${q.issues.slice(0,7).map(x=>`<button class="quality-item goView" data-view="${x.view}"><span>${esc(x.title)}</span>${pill(String(x.count),x.level==='critical'?'red':x.level==='warning'?'amber':'blue')}</button>`).join('')||'<div class="empty">Data quality ổn</div>'}</div></div></div></div>`;$$('.goView').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('.quickEvidence').forEach(b=>b.onclick=()=>quickEvidence(b.dataset.type,b.dataset.id,b.dataset.site||null));$$('.dailyDone').forEach(b=>b.onclick=()=>completeTaskWithRecurrence(b.dataset.id,myDay));applyPermissionUI()}

async function inboxView(){const type=$('#inboxType')?.value||'',rows=await api('/api/inbox');const filtered=type?rows.filter(x=>x.kind===type):rows;const kinds=[...new Set(rows.map(x=>x.kind))];$('#app').innerHTML=`<div class="toolbar"><select id="inboxType"><option value="">Tất cả (${rows.length})</option>${kinds.map(k=>`<option ${k===type?'selected':''}>${esc(k)}</option>`).join('')}</select><span class="muted">Inbox được tổng hợp động · xử lý ở module nguồn</span></div><div class="inbox-list">${filtered.map(x=>`<div class="card inbox-card ${x.priority}"><div class="inbox-kind">${pill(x.kind,x.priority==='critical'?'red':x.priority==='high'?'amber':'blue')} ${x.due_date?dueBadge(x.due_date):''}</div><div><b>${esc(x.title)}</b><div class="sub">${esc(x.subtitle||'')} · ${esc(x.status||'')}</div></div><button class="ghost inboxOpen" data-view="${x.view}">Mở</button></div>`).join('')||'<div class="card empty">Inbox trống</div>'}</div>`;$('#inboxType').onchange=()=>inboxView();$$('.inboxOpen').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}

let calendarCursor=new Date();
async function calendarView(){const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),start=new Date(y,m,1),end=new Date(y,m+1,0),iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,out=await api(`/api/calendar?start=${iso(start)}&end=${iso(end)}`),by={};for(const e of out.events)(by[e.date]??=[]).push(e);const first=(start.getDay()+6)%7,daysIn=end.getDate(),cells=[];for(let i=0;i<first;i++)cells.push('<div class="cal-cell outside"></div>');for(let d=1;d<=daysIn;d++){const date=iso(new Date(y,m,d)),ev=by[date]||[];cells.push(`<div class="cal-cell ${date===new Date().toISOString().slice(0,10)?'today':''}"><div class="cal-date">${d}</div>${ev.slice(0,5).map(e=>`<button class="cal-event ${e.type} calOpen" data-view="${e.view}" title="${esc(e.title)}"><span>${esc(e.site||'')}</span>${esc(e.title)}</button>`).join('')}${ev.length>5?`<div class="sub">+${ev.length-5} mục</div>`:''}</div>`)}$('#app').innerHTML=`<div class="calendar-toolbar"><button class="ghost" id="calPrev">←</button><h2>Tháng ${m+1}/${y}</h2><button class="ghost" id="calNext">→</button><button class="soft" id="calToday">Hôm nay</button></div><div class="cal-week"><b>T2</b><b>T3</b><b>T4</b><b>T5</b><b>T6</b><b>T7</b><b>CN</b></div><div class="calendar-grid">${cells.join('')}</div><div class="calendar-legend"><span class="task">Task</span><span class="compliance">Compliance</span><span class="payment">Payment</span><span class="equipment">Kiểm định</span></div>`;$('#calPrev').onclick=()=>{calendarCursor=new Date(y,m-1,1);calendarView()};$('#calNext').onclick=()=>{calendarCursor=new Date(y,m+1,1);calendarView()};$('#calToday').onclick=()=>{calendarCursor=new Date();calendarView()};$$('.calOpen').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}


// ===== Checkpoint 5.9: recurring reminders synced to Tasks + Calendar =====
function recurrenceLabel(t){if(!t?.recurrence)return '';const names={daily:'Hàng ngày',weekly:'Hàng tuần',monthly:'Hàng tháng'},n=Math.max(1,Number(t.recurrence_interval||1));let text=names[t.recurrence]||t.recurrence;if(n>1)text=`Mỗi ${n} ${t.recurrence==='daily'?'ngày':t.recurrence==='weekly'?'tuần':'tháng'}`;if(t.recurrence_end_date)text+=` · đến ${fmtDate(t.recurrence_end_date)}`;return text}
function recurrenceFields(prefix,task={}){const r=task.recurrence||'',interval=task.recurrence_interval||1,end=task.recurrence_end_date||'';return `<div class="field"><label>Lặp lại</label><select id="${prefix}Repeat"><option value="" ${!r?'selected':''}>Không lặp</option><option value="daily" ${r==='daily'?'selected':''}>Hàng ngày</option><option value="weekly" ${r==='weekly'?'selected':''}>Hàng tuần</option><option value="monthly" ${r==='monthly'?'selected':''}>Hàng tháng</option></select></div><div class="field repeatDetail"><label>Mỗi</label><div class="repeat-inline"><input id="${prefix}RepeatEvery" type="number" min="1" max="365" value="${interval}"><span id="${prefix}RepeatUnit">kỳ</span></div></div><div class="field repeatDetail"><label>Kết thúc chu kỳ</label><input id="${prefix}RepeatEnd" type="date" value="${end}"></div>`}
function bindRecurrence(prefix){const sel=$(`#${prefix}Repeat`),details=$$('.repeatDetail'),unit=$(`#${prefix}RepeatUnit`);const paint=()=>{const r=sel.value;details.forEach(x=>x.style.display=r?'flex':'none');if(unit)unit.textContent=r==='daily'?'ngày':r==='weekly'?'tuần':r==='monthly'?'tháng':'kỳ'};sel.onchange=paint;paint()}
function recurrencePayload(prefix){const recurrence=$(`#${prefix}Repeat`).value||null;return {recurrence,recurrence_interval:recurrence?Number($(`#${prefix}RepeatEvery`).value||1):1,recurrence_end_date:recurrence?($(`#${prefix}RepeatEnd`).value||null):null}}

async function completeTaskWithRecurrence(id,after){const out=await api('/api/tasks',{method:'PATCH',body:JSON.stringify({id,status:'completed',progress:100})});if(out.recurring&&out.next_due_date)toast(`Đã hoàn thành kỳ này · kỳ tiếp theo ${fmtDate(out.next_due_date)}`);else if(out.recurring&&out.series_finished)toast('Đã hoàn thành kỳ cuối của chu kỳ');else toast('Đã hoàn thành task');if(after)after()}

tasks = async function(){const status=$('#taskStatus')?.value||'',rows=await api(`/api/tasks?status=${encodeURIComponent(status)}`);state.tasks=rows;const open=rows.filter(t=>!['completed','cancelled'].includes(t.status)),recurring=rows.filter(t=>t.recurrence&&!['cancelled','completed'].includes(t.status)).length;$('#app').innerHTML=`<div class="toolbar"><button class="primary" id="addTask">+ Task</button><select id="taskStatus"><option value="">Mọi trạng thái</option>${[['not_started','Chưa bắt đầu'],['in_progress','Đang thực hiện'],['waiting','Đang chờ'],['blocked','Bị chặn'],['completed','Hoàn thành']].map(x=>`<option value="${x[0]}" ${status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><span class="muted">${open.length} việc chưa đóng · ${recurring} việc theo chu kỳ</span></div><div class="task-board">${rows.map(t=>`<div class="card task-card ${t.status}"><div class="task-top"><div>${statusPill(t.status)} ${pill(t.priority||'medium',t.priority==='high'?'red':t.priority==='medium'?'amber':'gray')} ${t.recurrence?pill('↻ '+recurrenceLabel(t),'violet'):''}</div><div class="actions"><button class="soft quickEvidence" data-type="task" data-id="${t.id}" data-site="${t.site_id||''}">+ File</button><button class="ghost taskEdit" data-id="${t.id}">Sửa</button>${t.status!=='completed'?`<button class="soft taskDone" data-id="${t.id}">✓ Hoàn thành kỳ này</button>`:''}</div></div><h3>${esc(t.title)}</h3><div class="sub">${esc(t.category||'—')} · ${esc(t.owner||'—')} · ${esc(t.site_code||'—')}</div><div class="task-due ${days(t.due_date)<0&&t.status!=='completed'?'late':''}">${t.recurrence?'Kỳ tiếp theo':'Deadline'}: <b>${fmtDate(t.due_date)}</b>${t.source_due_date?` · nguồn ${fmtDate(t.source_due_date)}`:''} ${t.deadline_sync_state==='changed'?pill('Deadline nguồn đã đổi','amber'):''}</div>${progressBar(t.progress)}${t.recurrence?`<div class="recurrence-note">↻ ${esc(recurrenceLabel(t))} · đã hoàn thành ${t.recurrence_completed_count||0} kỳ</div>`:''}${t.linked_title?`<div class="linked-chip">↳ ${esc(t.linked_entity_type)}: ${esc(t.linked_title)}</div>`:''}${t.blocked_reason?`<div class="late-note">Blocked: ${esc(t.blocked_reason)}</div>`:''}${t.notes?`<div class="sub task-note">${esc(t.notes)}</div>`:''}</div>`).join('')||'<div class="card empty">Không có task</div>'}</div>`;$('#addTask').onclick=quickTask;$('#taskStatus').onchange=()=>tasks();$$('.taskEdit').forEach(b=>b.onclick=()=>editTask(b.dataset.id));$$('.quickEvidence').forEach(b=>b.onclick=()=>quickEvidence(b.dataset.type,b.dataset.id,b.dataset.site||null));$$('.taskDone').forEach(b=>b.onclick=()=>completeTaskWithRecurrence(b.dataset.id,tasks));applyPermissionUI()}

quickTask = function(){const obs=state.obligations||[];modal('Tạo task / nhắc việc',`<div class="form-grid"><div class="field full"><label>Nội dung *</label><input id="tTitle"></div><div class="field"><label>Deadline / kỳ đầu tiên</label><input id="tDue" type="date"></div><div class="field"><label>Owner</label><input id="tOwner" value="EHS"></div>${recurrenceFields('t')}<div class="field"><label>Status</label><select id="tStatus"><option value="not_started">Chưa bắt đầu</option><option value="in_progress">Đang thực hiện</option><option value="waiting">Đang chờ</option><option value="blocked">Bị chặn</option></select></div><div class="field"><label>Tiến độ %</label><input id="tProgress" type="number" min="0" max="100" value="0"></div><div class="field"><label>Priority</label><select id="tPriority"><option>medium</option><option>high</option><option>low</option></select></div><div class="field"><label>Category</label><select id="tCat"><option>Compliance</option><option>PCCC</option><option>Chemical</option><option>Environment</option><option>PPE</option><option>Payment</option><option>Equipment</option></select></div><div class="field"><label>Site</label><select id="tSite">${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`).join('')}</select></div><div class="field full"><label>Liên kết Compliance (tuỳ chọn)</label><select id="tOb"><option value="">Không link</option>${obs.slice(0,400).map(o=>`<option value="${o.id}">${esc(o.site_code||'—')} · ${esc(o.title)}</option>`).join('')}</select></div><div class="field full"><div class="notice">Công việc lặp cần một deadline/kỳ đầu tiên. Khi bấm hoàn thành, hệ thống tự chuyển sang kỳ tiếp theo và giữ lịch sử kỳ đã hoàn thành.</div></div><div class="field full"><label>Ghi chú</label><textarea id="tNotes"></textarea></div></div>`,async close=>{const oid=$('#tOb').value,payload=recurrencePayload('t');const out=await api('/api/tasks',{method:'POST',body:JSON.stringify({title:$('#tTitle').value,due_date:$('#tDue').value||null,owner:$('#tOwner').value,category:$('#tCat').value,site_id:$('#tSite').value,status:$('#tStatus').value,progress:Number($('#tProgress').value||0),priority:$('#tPriority').value,notes:$('#tNotes').value,linked_entity_type:oid?'obligation':null,linked_entity_id:oid||null,...payload})});close();toast(out.recurrence?'Đã tạo nhắc việc theo chu kỳ':'Đã tạo task');if(state.view==='tasks')tasks();if(state.view==='calendar')calendarView()},'Tạo task');setTimeout(()=>bindRecurrence('t'),0)}

editTask = function(id){const t=state.tasks.find(x=>x.id===id);modal('Cập nhật task / chu kỳ',`<div class="form-grid"><div class="field full"><label>${esc(t.title)}</label></div><div class="field"><label>Status</label><select id="teStatus">${[['not_started','Chưa bắt đầu'],['in_progress','Đang thực hiện'],['waiting','Đang chờ'],['blocked','Bị chặn'],['completed','Hoàn thành kỳ này'],['cancelled','Hủy']].map(x=>`<option value="${x[0]}" ${t.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label>Tiến độ %</label><input id="teProgress" type="number" min="0" max="100" value="${t.progress||0}"></div><div class="field"><label>Deadline / kỳ tiếp theo</label><input id="teDue" type="date" value="${t.due_date||''}"></div><div class="field"><label>Owner</label><input id="teOwner" value="${esc(t.owner||'')}"></div>${recurrenceFields('te',t)}<div class="field"><label>Priority</label><select id="tePriority"><option ${t.priority==='low'?'selected':''}>low</option><option ${t.priority==='medium'?'selected':''}>medium</option><option ${t.priority==='high'?'selected':''}>high</option></select></div><div class="field full"><label>Blocked reason</label><input id="teBlocked" value="${esc(t.blocked_reason||'')}"></div><div class="field full"><label>Ghi chú tiến độ</label><textarea id="teNotes">${esc(t.notes||'')}</textarea></div>${t.recurrence?`<div class="field full"><div class="notice">Đã hoàn thành ${t.recurrence_completed_count||0} kỳ. Có thể đổi chu kỳ hoặc chọn “Không lặp” để dừng sau kỳ hiện tại.</div></div>`:''}${t.source_due_date?`<div class="field full"><div class="notice">Deadline nguồn: ${fmtDate(t.source_due_date)} · ${esc(t.deadline_sync_state)}. Đổi deadline task sẽ được ghi audit.</div></div>`:''}</div>`,async close=>{const payload=recurrencePayload('te'),out=await api('/api/tasks',{method:'PATCH',body:JSON.stringify({id,status:$('#teStatus').value,progress:Number($('#teProgress').value||0),due_date:$('#teDue').value||null,owner:$('#teOwner').value,priority:$('#tePriority').value,blocked_reason:$('#teBlocked').value,notes:$('#teNotes').value,...payload})});close();if(out.recurring&&out.next_due_date)toast(`Đã hoàn thành kỳ này · kỳ tiếp theo ${fmtDate(out.next_due_date)}`);else toast('Đã cập nhật task');tasks()},'Lưu thay đổi');setTimeout(()=>bindRecurrence('te'),0)}

calendarView = async function(){const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),start=new Date(y,m,1),end=new Date(y,m+1,0),iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,out=await api(`/api/calendar?start=${iso(start)}&end=${iso(end)}`),by={};for(const e of out.events)(by[e.date]??=[]).push(e);const first=(start.getDay()+6)%7,daysIn=end.getDate(),cells=[];for(let i=0;i<first;i++)cells.push('<div class="cal-cell outside"></div>');for(let d=1;d<=daysIn;d++){const date=iso(new Date(y,m,d)),ev=by[date]||[];cells.push(`<div class="cal-cell ${date===new Date().toISOString().slice(0,10)?'today':''}"><div class="cal-date">${d}</div>${ev.slice(0,5).map(e=>`<button class="cal-event ${e.type} ${e.recurring?'recurring':''} calOpen" data-view="${e.view}" title="${esc(e.title)}${e.recurring?' · Lặp lại':''}"><span>${e.recurring?'↻ ':''}${esc(e.site||'')}</span>${esc(e.title)}${e.completed_occurrence?' ✓':''}</button>`).join('')}${ev.length>5?`<div class="sub">+${ev.length-5} mục</div>`:''}</div>`)}$('#app').innerHTML=`<div class="calendar-toolbar"><button class="ghost" id="calPrev">←</button><h2>Tháng ${m+1}/${y}</h2><button class="ghost" id="calNext">→</button><button class="soft" id="calToday">Hôm nay</button></div><div class="cal-week"><b>T2</b><b>T3</b><b>T4</b><b>T5</b><b>T6</b><b>T7</b><b>CN</b></div><div class="calendar-grid">${cells.join('')}</div><div class="calendar-legend"><span class="task">Task</span><span class="task recurring">↻ Task lặp</span><span class="compliance">Compliance</span><span class="payment">Payment</span><span class="equipment">Kiểm định</span></div>`;$('#calPrev').onclick=()=>{calendarCursor=new Date(y,m-1,1);calendarView()};$('#calNext').onclick=()=>{calendarCursor=new Date(y,m+1,1);calendarView()};$('#calToday').onclick=()=>{calendarCursor=new Date();calendarView()};$$('.calOpen').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}

applyPermissionUI = function(){const hide=(sel,p)=>{$$(sel).forEach(x=>x.hidden=!can(p))};hide('#addEmployee,.toggleEmp','employees.write');hide('#issuePPE','ppe.issue');hide('#adjustPPE,#managePpeTypes,.ppeHistEdit','ppe.adjust');hide('.changeDeadline,.changeDue','compliance.request_deadline');hide('#addLegalExtra,#planUploadBtn,.obEdit','compliance.write');hide('.legalResolve,.resolveLegalUpdate','legal.review');hide('#drop,#docImportTools','documents.write');hide('.docProcess','documents.process');hide('.docReview,.docMeta','documents.review');hide('.editPayment,.docToggle,#addPayment','payments.write');hide('#addEq,.eqInspect,.eqEdit,.eqReconcile','equipment.write');hide('#addTask,.taskEdit,.taskDone,.notifRefresh','tasks.write');hide('.legalWatchRun','legal.review')}


// ===== Checkpoint 6.1: PPE size management =====
const PPE_UNALLOCATED_UI='__UNALLOCATED__';
function cp61SizeOptions(item){
  if(Array.isArray(item?.size_options))return item.size_options;
  try{const x=JSON.parse(item?.size_options_json||'[]');return Array.isArray(x)?x:[]}catch{return []}
}
function cp61OneSize(item){return Number(item?.one_size??1)===1}
function cp61SizeStock(item,label){return (item?.size_stocks||[]).find(x=>x.size_label===label)}
function cp61SizeSummary(item){
  if(cp61OneSize(item))return '<span class="pill gray">One size</span>';
  const opts=cp61SizeOptions(item),parts=opts.map(x=>{const st=cp61SizeStock(item,x),n=Number(st?.current_stock||0);return `<span class="size-chip ${n<0?'neg':''}">${esc(x)}: <b>${new Intl.NumberFormat('vi-VN').format(n)}</b></span>`});
  const u=cp61SizeStock(item,PPE_UNALLOCATED_UI),uv=Number(u?.current_stock||0);if(uv!==0)parts.push(`<span class="size-chip unallocated">Chưa phân: <b>${new Intl.NumberFormat('vi-VN').format(uv)}</b></span>`);
  return `<div class="size-chip-list">${parts.join('')||'<span class="muted">Chưa khai báo size</span>'}</div>`;
}
function cp61SuggestedSize(item,emp){
  const opts=cp61SizeOptions(item);if(!opts.length)return '';
  const name=String(item?.name||'').toLowerCase();let wanted='';
  if(/giày|ủng|dép|shoe/.test(name))wanted=String(emp?.shoe_size||'').trim();
  else if(/áo|quần|đồng phục|clothing/.test(name))wanted=String(emp?.clothing_size||'').trim();
  if(wanted){const hit=opts.find(x=>String(x).trim().toLowerCase()===wanted.toLowerCase());if(hit)return hit}
  return opts[0];
}
function cp61SizeSelectHtml(item,emp,current=''){
  if(cp61OneSize(item))return `<input class="liSize" type="hidden" value=""><span class="one-size-label">One size</span>`;
  const opts=cp61SizeOptions(item),pick=current&&opts.includes(current)?current:cp61SuggestedSize(item,emp);
  return `<select class="liSize">${opts.map(x=>{const st=cp61SizeStock(item,x),stock=Number(st?.current_stock||0);return `<option value="${esc(x)}" ${x===pick?'selected':''}>${esc(x)} · tồn ${new Intl.NumberFormat('vi-VN').format(stock)}</option>`}).join('')}</select>`;
}
function cp61PpeRows(items){return items.map(i=>`<tr><td>${esc(i.sku)}</td><td><b>${esc(i.name)}</b></td><td class="ppe-size-cell">${cp61SizeSummary(i)}</td><td>${Number(i.current_stock)<0?pill(i.current_stock,'red'):Number(i.current_stock)<=Number(i.min_stock)?pill(i.current_stock,'amber'):pill(i.current_stock,'green')}</td><td>${esc(i.unit||'—')}</td><td>${i.min_stock??'—'}</td><td>${i.unit_price?fmtMoney(i.unit_price):'—'}</td><td class="ppe-action-cell"><div class="ppe-row-actions"><button class="soft ppeIssueOne" data-id="${i.id}">Xuất</button><button class="ghost ppeAdjustOne" data-id="${i.id}">Điều chỉnh</button></div></td></tr>`).join('')}

managePpeTypes = async function(){
  const catalog=await api('/api/ppe/catalog');
  const active=catalog.filter(x=>Number(x.active)===1).length,inactive=catalog.length-active;
  modal('Quản lý loại PPE',`<div class="ppe-catalog-manager"><div class="toolbar"><button class="primary" id="ppeTypeAdd">+ Thêm loại PPE</button><input id="ppeTypeQ" placeholder="Tìm tên / SKU / size"><select id="ppeTypeStatus"><option value="">Tất cả</option><option value="active">Đang dùng</option><option value="inactive">Đã ngừng</option></select><span class="muted">${active} đang dùng · ${inactive} đã ngừng</span></div><div class="notice">Với quần áo/giày dép: tick <b>Một size</b> nếu loại đó không phân size. Nếu có nhiều size, bỏ tick và khai báo danh sách như S, M, L, XL hoặc 38, 39, 40...</div><div class="table-wrap ppe-catalog-table"><table><thead><tr><th>SKU</th><th>Loại PPE</th><th>Size</th><th>ĐVT</th><th>Tồn</th><th>Min</th><th>Đơn giá</th><th>Trạng thái</th><th></th></tr></thead><tbody id="ppeTypeRows"></tbody></table></div></div>`,async close=>close(),'Đóng');
  const render=()=>{const q=String($('#ppeTypeQ')?.value||'').toLowerCase(),st=$('#ppeTypeStatus')?.value||'';const rows=catalog.filter(i=>{const sizes=cp61SizeOptions(i).join(' ').toLowerCase();return(!q||String(i.name).toLowerCase().includes(q)||String(i.sku).toLowerCase().includes(q)||sizes.includes(q))&&(!st||(st==='active'?Number(i.active)===1:Number(i.active)===0))});$('#ppeTypeRows').innerHTML=rows.map(i=>`<tr><td>${esc(i.sku)}</td><td><b>${esc(i.name)}</b>${i.size_variant?`<div class="sub">${esc(i.size_variant)}</div>`:''}</td><td>${cp61SizeSummary(i)}</td><td>${esc(i.unit||'—')}</td><td>${Number(i.current_stock)<0?pill(i.current_stock,'red'):esc(i.current_stock)}</td><td>${esc(i.min_stock??'0')}</td><td>${i.unit_price!=null?fmtMoney(i.unit_price):'—'}</td><td>${Number(i.active)===1?pill('Đang dùng','green'):pill('Đã ngừng','gray')}</td><td class="actions"><button class="ghost ppeTypeEdit" data-id="${i.id}">Sửa</button>${Number(i.active)===1?`<button class="danger ppeTypeStop" data-id="${i.id}">Bỏ</button>`:`<button class="soft ppeTypeRestore" data-id="${i.id}">Khôi phục</button>`}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Không có loại PPE phù hợp</td></tr>';$$('.ppeTypeEdit').forEach(b=>b.onclick=()=>ppeTypeForm(catalog.find(x=>x.id===b.dataset.id)));$$('.ppeTypeStop').forEach(b=>b.onclick=()=>deactivatePpeType(catalog.find(x=>x.id===b.dataset.id)));$$('.ppeTypeRestore').forEach(b=>b.onclick=async()=>{await api('/api/ppe/catalog',{method:'PATCH',body:JSON.stringify({id:b.dataset.id,active:true})});toast('Đã khôi phục loại PPE');managePpeTypes()})};
  $('#ppeTypeAdd').onclick=()=>ppeTypeForm(null);$('#ppeTypeQ').oninput=render;$('#ppeTypeStatus').onchange=render;render();
}
ppeTypeForm = function(item=null){
  const isEdit=!!item,oneSize=item?cp61OneSize(item):true,sizeText=cp61SizeOptions(item).join(', ');
  modal(isEdit?'Sửa loại PPE':'Thêm loại PPE',`<div class="form-grid"><div class="field"><label>SKU *</label><input id="ptSku" value="${esc(item?.sku||'')}"></div><div class="field"><label>Tên PPE *</label><input id="ptName" value="${esc(item?.name||'')}"></div><div class="field"><label>ĐVT *</label><input id="ptUnit" value="${esc(item?.unit||'cái')}"></div><div class="field"><label>Quy cách / mô tả</label><input id="ptSize" value="${esc(item?.size_variant||'')}"></div><div class="field full checkbox-field"><label class="check-label"><input id="ptOneSize" type="checkbox" ${oneSize?'checked':''}> <span><b>Một size</b><small>Dùng cho PPE không cần quản lý theo size số.</small></span></label></div><div class="field full" id="ptSizeOptionsField" ${oneSize?'hidden':''}><label>Danh sách size *</label><input id="ptSizeOptions" value="${esc(sizeText)}" placeholder="VD quần áo: S, M, L, XL, XXL · giày: 38, 39, 40, 41, 42"><div class="sub">Ngăn cách bằng dấu phẩy. Tồn kho sẽ được theo dõi riêng từng size.</div></div><div class="field"><label>Min stock tổng</label><input id="ptMin" type="number" min="0" value="${item?.min_stock??0}"></div><div class="field"><label>Lifecycle (ngày)</label><input id="ptLife" type="number" min="0" value="${item?.lifecycle_days??''}"></div><div class="field"><label>Đơn giá tham chiếu (VND)</label><input id="ptPrice" type="number" min="0" step="100" value="${item?.unit_price??''}"></div>${!isEdit?'<div class="field"><label>Tồn đầu kỳ tổng</label><input id="ptOpening" type="number" value="0"></div>':''}<div class="field full"><div class="notice">${isEdit?'Nếu chuyển từ “Một size” sang nhiều size, tồn hiện tại được giữ an toàn ở nhóm <b>Chưa phân size</b>. Các lần nhập/xuất tiếp theo sẽ chọn size cụ thể.':'Nếu là nhiều size và có tồn đầu kỳ, số tồn cũ được đưa vào “Chưa phân size” cho tới khi cậu phân bổ/kiểm kê theo size.'}</div></div></div>`,async close=>{const one=$('#ptOneSize').checked,sizes=$('#ptSizeOptions').value.split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean);const body={sku:$('#ptSku').value,name:$('#ptName').value,unit:$('#ptUnit').value,size_variant:$('#ptSize').value,one_size:one,size_options:sizes,min_stock:Number($('#ptMin').value||0),lifecycle_days:$('#ptLife').value===''?null:Number($('#ptLife').value),unit_price:$('#ptPrice').value===''?null:Number($('#ptPrice').value)};if(!one&&!sizes.length)throw new Error('Khai báo ít nhất 1 size');if(isEdit){body.id=item.id;await api('/api/ppe/catalog',{method:'PATCH',body:JSON.stringify(body)})}else{body.opening_stock=Number($('#ptOpening').value||0);await api('/api/ppe/catalog',{method:'POST',body:JSON.stringify(body)})}close();toast(isEdit?'Đã cập nhật loại PPE':'Đã thêm loại PPE');ppe()},isEdit?'Lưu':'Thêm');
  setTimeout(()=>{const toggle=()=>{$('#ptSizeOptionsField').hidden=$('#ptOneSize').checked};$('#ptOneSize').onchange=toggle;toggle()},0)
}

ppe = async function(){
  state.employees=await api('/api/employees?status=active');state.ppe=await api('/api/ppe');
  const neg=state.ppe.items.filter(i=>Number(i.current_stock)<0).length,zero=state.ppe.items.filter(i=>Number(i.current_stock)===0).length,low=state.ppe.items.filter(i=>Number(i.current_stock)<=Number(i.min_stock)).length,totalStock=state.ppe.items.reduce((a,i)=>a+Number(i.current_stock||0),0),multi=state.ppe.items.filter(i=>!cp61OneSize(i)).length;
  $('#app').innerHTML=`<div class="grid ppe-kpis">${kpi('Tổng mặt hàng',state.ppe.items.length,'PPE master','#edf2ff')}${kpi('Tổng tồn',new Intl.NumberFormat('vi-VN').format(totalStock),'Theo tồn hệ thống','#eaf8f2')}${kpi('Quản lý size',multi,'Loại PPE nhiều size','#edf2ff')}${kpi('Âm kho',neg,'Cần reconciliation','#fff0f1')}${kpi('Hết hàng',zero,'Vẫn cho xuất','#f1edff')}</div>
  <div class="toolbar ppe-toolbar"><button class="primary" id="issuePPE">+ Xuất PPE</button><button class="ghost" id="adjustPPE">Nhập / điều chỉnh</button><button class="ghost" id="managePpeTypes">⚙ Loại PPE</button><input id="ppeQ" placeholder="Tìm PPE / SKU / size"><span class="muted">${state.ppe.items.length} mặt hàng · ${multi} loại nhiều size · ${neg} âm kho</span><div class="toolbar-spacer"></div><div class="ppe-history-menu-wrap"><button class="ghost" id="ppeHistoryToggle">Lịch sử nhập/xuất ▾</button><div class="card ppe-history-dropdown" id="ppeHistoryDropdown" hidden><div class="ppe-history-head"><div><b>Lịch sử nhập/xuất PPE</b><span>Stock ledger đầy đủ, gồm size</span></div><button class="x" id="ppeHistoryClose">×</button></div><div class="toolbar"><input id="ppeHistQ" placeholder="Tìm PPE / size / người nhận / bộ phận / lý do"><select id="ppeHistType"><option value="">Tất cả giao dịch</option><option value="IN">Nhập kho</option><option value="OUT">Xuất PPE</option><option value="REVERSAL">Hoàn kho sửa sai</option><option value="ADJUSTMENT">Điều chỉnh</option><option value="OPENING_IMPORT">Tồn đầu kỳ</option></select><button class="ghost" id="exportPpeHistory">⇩ Xuất Excel lịch sử</button><span class="muted" id="ppeHistCount">Chưa tải</span></div><div class="table-wrap ppe-history-table-wrap"><table class="ppe-history-table"><thead><tr><th>Ngày nghiệp vụ</th><th>Loại</th><th>Trạng thái</th><th>SKU</th><th>PPE</th><th>Size</th><th>SL</th><th>Tồn tổng trước</th><th>Tồn tổng sau</th><th>Người nhận</th><th>Bộ phận</th><th>Lý do</th><th>Lý do sửa</th><th>Người thao tác</th><th>Thao tác</th></tr></thead><tbody id="ppeHistoryRows"><tr><td colspan="15" class="empty">Mở lịch sử để tải dữ liệu</td></tr></tbody></table></div></div></div></div>
  <div class="ppe-inventory-full"><div class="top-scroll" id="ppeTopScroll"><div></div></div><div class="table-wrap ppe-table-wrap" id="ppeTableWrap"><table class="ppe-table"><thead><tr><th>SKU</th><th>PPE</th><th>Size / tồn theo size</th><th>Tồn tổng</th><th>ĐVT</th><th>Min stock</th><th>Đơn giá tham chiếu</th><th class="ppe-action-head">Thao tác</th></tr></thead><tbody id="ppeRows">${cp61PpeRows(state.ppe.items)}</tbody></table></div><div class="ppe-table-foot"><span>Loại nhiều size hiển thị tồn riêng từng size; tổng tồn vẫn dùng để kiểm soát kho chung.</span><span>${state.ppe.items.length} mặt hàng</span></div></div>`;
  const renderRows=()=>{const q=String($('#ppeQ').value||'').toLowerCase();const rows=state.ppe.items.filter(x=>x.name.toLowerCase().includes(q)||x.sku.toLowerCase().includes(q)||cp61SizeOptions(x).join(' ').toLowerCase().includes(q));$('#ppeRows').innerHTML=cp61PpeRows(rows);$$('.ppeIssueOne').forEach(b=>b.onclick=()=>issuePPE(b.dataset.id));$$('.ppeAdjustOne').forEach(b=>b.onclick=()=>adjustPPE(b.dataset.id));applyPermissionUI()};
  $('#issuePPE').onclick=()=>issuePPE();$('#adjustPPE').onclick=()=>adjustPPE();$('#managePpeTypes').onclick=()=>managePpeTypes();$('#ppeQ').oninput=renderRows;renderRows();
  const top=$('#ppeTopScroll'),wrap=$('#ppeTableWrap'),sync=()=>{top.firstElementChild.style.width=wrap.scrollWidth+'px'};sync();top.onscroll=()=>{wrap.scrollLeft=top.scrollLeft};wrap.onscroll=()=>{top.scrollLeft=wrap.scrollLeft};
  const menu=$('#ppeHistoryDropdown'),toggle=$('#ppeHistoryToggle'),close=$('#ppeHistoryClose');let loaded=false;const open=async()=>{menu.hidden=false;toggle.textContent='Lịch sử nhập/xuất ▴';if(!loaded){loaded=true;await loadPpeHistory()}};const hide=()=>{menu.hidden=true;toggle.textContent='Lịch sử nhập/xuất ▾'};toggle.onclick=()=>menu.hidden?open():hide();close.onclick=hide;$('#ppeHistType').onchange=()=>loadPpeHistory();let histTimer;$('#ppeHistQ').oninput=()=>{clearTimeout(histTimer);histTimer=setTimeout(loadPpeHistory,220)};$('#exportPpeHistory').onclick=e=>{e.preventDefault();downloadExcel('ppe-ledger',$('#exportPpeHistory'))};
  applyPermissionUI();
}

ppeHistoryRows = function(rows){return rows.map(t=>{const st=String(t.tx_status||'active'),status=st==='active'?pill('Hiệu lực','green'):st==='superseded'?pill('Đã thay thế','amber'):st==='voided'?pill('Đã hủy','red'):pill(st,'gray');const action=t.type==='OUT'&&st==='active'?`<button class="ghost ppeHistEdit" data-id="${t.id}">Sửa</button>`:'—';return `<tr class="${st==='active'?'':'ledger-muted'}"><td>${new Date(t.effective_at||t.created_at).toLocaleString('vi-VN')}</td><td>${pill(ppeTxLabel(t.type),t.type==='OUT'?'blue':t.type==='IN'?'green':t.type==='REVERSAL'?'violet':t.type==='ADJUSTMENT'?'amber':'gray')}</td><td>${status}</td><td>${esc(t.sku||'—')}</td><td><b>${esc(t.item_name||'—')}</b></td><td>${t.size_label===PPE_UNALLOCATED_UI?pill('Chưa phân','amber'):esc(t.size_label||'One size')}</td><td>${new Intl.NumberFormat('vi-VN').format(Number(t.quantity||0))}</td><td>${new Intl.NumberFormat('vi-VN').format(Number(t.stock_before||0))}</td><td>${Number(t.stock_after)<0?pill(t.stock_after,'red'):esc(new Intl.NumberFormat('vi-VN').format(Number(t.stock_after||0)))}</td><td>${esc(t.employee_name||'—')}</td><td>${esc(t.department||'—')}</td><td>${esc(t.reason||'—')}</td><td>${esc(t.correction_reason||'—')}</td><td>${esc(t.actor||'—')}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="15" class="empty">Không có giao dịch phù hợp</td></tr>'}

function cp61PpeLine(preselectId=null,employeeId=null){
  const emp=state.employees.find(x=>x.id===employeeId)||state.employees[0],item=state.ppe.items.find(x=>x.id===(preselectId||state.ppe.items[0]?.id))||state.ppe.items[0];
  return `<div class="ppe-line ppe-line-size"><select class="liItem">${state.ppe.items.map(i=>`<option value="${i.id}" ${item?.id===i.id?'selected':''}>${esc(i.name)} · tổng ${i.current_stock}</option>`).join('')}</select><div class="liSizeWrap">${item?cp61SizeSelectHtml(item,emp):''}</div><input class="liQty" type="number" min="1" value="1"><button class="x rm" type="button">×</button></div>`
}
function cp61WirePpeLine(row,employeeId){
  const renderSize=()=>{const item=state.ppe.items.find(x=>x.id===$('.liItem',row).value),emp=state.employees.find(x=>x.id===employeeId);$('.liSizeWrap',row).innerHTML=item?cp61SizeSelectHtml(item,emp):''};$('.liItem',row).onchange=renderSize;renderSize();
}
issuePPE = function(preselectItemId=null){
  const active=state.employees,labels=uniqueEmployeeLabels(active);
  modal('Xuất PPE',`<div class="form-grid"><div class="field full"><label>Người nhận *</label><select id="ppeEmp">${active.map(e=>`<option value="${e.id}">${esc(labels.get(e.id))}</option>`).join('')}</select><div id="ppeEmpInfo" class="selected-person"></div></div><div class="field full"><label>Hàng cần xuất</label><div class="ppe-lines" id="ppeLines">${cp61PpeLine(preselectItemId,active[0]?.id)}</div><button class="soft" type="button" id="addLine">+ Thêm mặt hàng</button></div><div class="field"><label>Lý do</label><select id="ppeReason"><option>Cấp mới</option><option>Cấp định kỳ</option><option>Hỏng</option><option>Mất</option><option>Thay thế</option><option>Khác</option></select></div><div class="field"><label>Ghi chú</label><input id="ppeNote"></div><div class="field full"><div class="notice">PPE nhiều size bắt buộc chọn size. Tồn âm theo size vẫn không khóa thao tác nhưng sẽ được lưu vào audit để đối chiếu.</div></div></div>`,async close=>{const lines=$$('.ppe-line').map(r=>({item_id:$('.liItem',r).value,size_label:$('.liSize',r)?.value||null,quantity:Number($('.liQty',r).value)}));const out=await api('/api/ppe/issue',{method:'POST',body:JSON.stringify({employee_id:$('#ppeEmp').value,lines,reason:$('#ppeReason').value,note:$('#ppeNote').value})});close();toast(out.results.some(x=>x.negative_stock)?'Đã xuất · có tồn âm cần đối chiếu':'Đã xuất PPE');ppe()});
  setTimeout(()=>{const renderInfo=()=>{const e=active.find(x=>x.id===$('#ppeEmp').value);$('#ppeEmpInfo').innerHTML=e?`<b>${esc(e.full_name)}</b><span>Mã NV: ${esc(e.employee_code||'—')}</span><span>Bộ phận: ${esc(e.department||'—')}</span><span>Vị trí: ${esc(e.job_title||'—')}</span><span>Site: ${esc(e.site_code||'—')}</span><span>Size giày: ${esc(e.shoe_size||'—')}</span><span>Size quần áo: ${esc(e.clothing_size||'—')}</span>`:'';$$('.ppe-line').forEach(r=>cp61WirePpeLine(r,e?.id))};$('#ppeEmp').onchange=renderInfo;renderInfo();$('#addLine').onclick=()=>{const e=active.find(x=>x.id===$('#ppeEmp').value);$('#ppeLines').insertAdjacentHTML('beforeend',cp61PpeLine(null,e?.id));const row=$$('.ppe-line').at(-1);cp61WirePpeLine(row,e?.id);wireRemove()};wireRemove()},0)
}

function editPpeIssueHistory(txId){
  const tx=(state.ppeHistory||[]).find(x=>x.id===txId);if(!tx)return toast('Không tìm thấy giao dịch',true);
  const active=state.employees||[],labels=uniqueEmployeeLabels(active),selectedEmp=active.find(e=>e.id===tx.employee_id)||active[0],selectedItem=state.ppe.items.find(i=>i.id===tx.item_id)||state.ppe.items[0];
  modal('Sửa lịch sử xuất PPE',`<div class="notice"><b>Nguyên tắc audit:</b> hệ thống không sửa/xóa dòng xuất cũ. Khi lưu, số lượng cũ được <b>tự hoàn về kho</b>, dòng cũ chuyển “Đã thay thế”, sau đó hệ thống ghi một dòng xuất mới đã chỉnh. Nếu chọn “Chỉ hoàn kho”, lần xuất cũ sẽ được hủy.</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Giao dịch gốc</label><input value="${esc(tx.sku||'')} · ${esc(tx.item_name||'')} · ${esc(tx.size_label||'One size')} · SL ${Number(tx.quantity||0)} · ${esc(tx.employee_name||'—')}" disabled></div><div class="field full checkbox-field"><label class="check-label"><input id="histCancelOnly" type="checkbox"> <span><b>Chỉ hoàn kho / hủy lần xuất</b><small>Không tạo giao dịch xuất thay thế.</small></span></label></div><div class="field full"><label>Người nhận *</label><select id="histEmp">${active.map(e=>`<option value="${e.id}" ${e.id===selectedEmp?.id?'selected':''}>${esc(labels.get(e.id))}</option>`).join('')}</select></div><div class="field full"><label>PPE *</label><select id="histItem">${state.ppe.items.map(i=>`<option value="${i.id}" ${i.id===selectedItem?.id?'selected':''}>${esc(i.name)} · tồn ${i.current_stock}</option>`).join('')}</select></div><div class="field" id="histSizeField"><label>Size</label><div id="histSizeWrap"></div></div><div class="field"><label>Số lượng *</label><input id="histQty" type="number" min="1" value="${Number(tx.quantity||1)}"></div><div class="field"><label>Lý do cấp</label><select id="histReason">${['Cấp mới','Cấp định kỳ','Hỏng','Mất','Thay thế','Khác'].map(x=>`<option ${String(tx.reason||'')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Ghi chú</label><input id="histNote" value="${esc(tx.note||'')}"></div><div class="field full"><label>Lý do chỉnh sửa *</label><textarea id="histCorrectionReason" placeholder="VD: Xuất nhầm size 42 thay vì 41 / nhầm người nhận / nhầm số lượng"></textarea></div></div>`,async close=>{const cancel=$('#histCancelOnly').checked,body={transaction_id:tx.id,mode:cancel?'cancel':'correct',correction_reason:$('#histCorrectionReason').value};if(!cancel)Object.assign(body,{employee_id:$('#histEmp').value,item_id:$('#histItem').value,size_label:$('#histSize')?.value||null,quantity:Number($('#histQty').value),reason:$('#histReason').value,note:$('#histNote').value});const out=await api('/api/ppe/history/correct',{method:'POST',body:JSON.stringify(body)});close();toast(cancel?'Đã hủy lần xuất và hoàn hàng về kho':out.replacement?.negative_stock?'Đã sửa · giao dịch mới làm tồn âm cần đối chiếu':'Đã sửa lịch sử và tự hoàn/ghi lại tồn kho');await ppe();setTimeout(async()=>{const btn=$('#ppeHistoryToggle');if(btn){btn.click();await loadPpeHistory()}},80)},'Lưu chỉnh sửa');
  setTimeout(()=>{const renderSize=()=>{const item=state.ppe.items.find(i=>i.id===$('#histItem').value);if(!item||cp61OneSize(item)){$('#histSizeField').hidden=true;$('#histSizeWrap').innerHTML='';return}$('#histSizeField').hidden=false;const opts=cp61SizeOptions(item),want=item.id===tx.item_id?tx.size_label:null;$('#histSizeWrap').innerHTML=`<select id="histSize">${opts.map(x=>`<option value="${esc(x)}" ${x===want?'selected':''}>${esc(x)} · tồn ${Number(cp61SizeStock(item,x)?.current_stock||0)}</option>`).join('')}</select>`};const toggle=()=>{const off=$('#histCancelOnly').checked;['#histEmp','#histItem','#histQty','#histReason','#histNote'].forEach(sel=>{if($(sel))$(sel).disabled=off});$('#histSizeField').style.opacity=off?'.45':'1';};$('#histItem').onchange=renderSize;$('#histCancelOnly').onchange=toggle;renderSize();toggle()},0)
}

adjustPPE = function(preselectItemId=null){
  const first=state.ppe.items.find(i=>i.id===preselectItemId)||state.ppe.items[0];
  modal('Nhập / điều chỉnh PPE',`<div class="form-grid"><div class="field full"><label>PPE</label><select id="adjItem">${state.ppe.items.map(i=>`<option value="${i.id}" ${first?.id===i.id?'selected':''}>${esc(i.name)} · tổng ${i.current_stock}</option>`).join('')}</select></div><div class="field" id="adjSizeField"><label>Size</label><div id="adjSizeWrap"></div></div><div class="field"><label>Số lượng (+ nhập, - điều chỉnh)</label><input id="adjQty" type="number" value="1"></div><div class="field"><label>Đơn giá nhập/tham chiếu (VND)</label><input id="adjPrice" type="number" min="0" step="100"></div><div class="field full"><label>Lý do</label><input id="adjReason" value="Kiểm kê/nhập kho"></div><div class="field full"><div class="notice">Loại nhiều size: chọn đúng size khi nhập/điều chỉnh. “Chưa phân size” dùng cho tồn cũ chưa kiểm kê theo size.</div></div></div>`,async close=>{await api('/api/ppe/adjust',{method:'POST',body:JSON.stringify({item_id:$('#adjItem').value,size_label:$('#adjSize')?.value||null,quantity:Number($('#adjQty').value),unit_price:$('#adjPrice').value===''?null:Number($('#adjPrice').value),reason:$('#adjReason').value})});close();toast('Đã cập nhật tồn');ppe()});
  setTimeout(()=>{const render=()=>{const i=state.ppe.items.find(x=>x.id===$('#adjItem').value);$('#adjPrice').value=i?.unit_price??'';if(cp61OneSize(i)){$('#adjSizeField').hidden=true;$('#adjSizeWrap').innerHTML=''}else{$('#adjSizeField').hidden=false;const opts=cp61SizeOptions(i),u=cp61SizeStock(i,PPE_UNALLOCATED_UI);$('#adjSizeWrap').innerHTML=`<select id="adjSize">${opts.map(x=>{const st=cp61SizeStock(i,x);return `<option value="${esc(x)}">${esc(x)} · tồn ${Number(st?.current_stock||0)}</option>`}).join('')}<option value="${PPE_UNALLOCATED_UI}">Chưa phân size · ${Number(u?.current_stock||0)}</option></select>`}};$('#adjItem').onchange=render;render()},0)
}


