function startSideClock(){const el=$('#sideClock');if(!el)return;const tick=()=>{const d=new Date(),time=new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(d),date=new Intl.DateTimeFormat('vi-VN',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'}).format(d);el.innerHTML=`<b>${esc(time)}</b><small>${esc(date)}</small>`};tick();const timer=setInterval(tick,1000);window.addEventListener('beforeunload',()=>clearInterval(timer),{once:true})}
function globalSearchModal(){
  $('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal search-modal"><div class="modal-head"><strong>Global Search</strong><button class="x">×</button></div><div class="modal-body"><input id="globalSearchInput" class="search-box" placeholder="Tìm hồ sơ, nhân viên, PPE, thiết bị, task, invoice..." autocomplete="off"><div class="sub" style="margin-top:7px">Gõ ít nhất 2 ký tự · Esc để đóng · Ctrl+K để mở</div><div id="globalSearchResults" class="search-results"><div class="empty">Nhập từ khóa để tìm xuyên toàn hệ thống</div></div></div></div></div>`;
  const close=()=>$('#modalRoot').innerHTML='';$('.x').onclick=close;const input=$('#globalSearchInput'),box=$('#globalSearchResults');input.focus();let timer;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=input.value.trim();if(q.length<2){box.innerHTML='<div class="empty">Nhập ít nhất 2 ký tự</div>';return}box.innerHTML='<div class="empty">Đang tìm…</div>';try{const out=await api(`/api/search?q=${encodeURIComponent(q)}`);box.innerHTML=out.results.map(r=>`<button class="search-result" data-view="${esc(r.view)}" data-id="${esc(r.id)}" data-type="${esc(r.type)}"><span class="search-type">${esc(r.type)}</span><span><b>${esc(r.title)}</b><small class="sub">${esc(r.subtitle||'')}</small></span></button>`).join('')||'<div class="empty">Không tìm thấy kết quả</div>';$$('.search-result',box).forEach(b=>b.onclick=async()=>{const view=b.dataset.view,id=b.dataset.id,type=b.dataset.type;close();if(type==='equipment')history.replaceState(null,'',`?asset=${encodeURIComponent(id)}`);else if(location.search)history.replaceState(null,'',location.pathname);await navigate(view)})}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}},220)};document.addEventListener('keydown',function escSearch(e){if(e.key==='Escape'&&$('#modalRoot .search-modal')){close();document.removeEventListener('keydown',escSearch)}})
}
function wireGlobalSearch(){if($('#globalSearchBtn'))$('#globalSearchBtn').onclick=globalSearchModal;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();globalSearchModal()}})}
async function auditPrepView(){const domain=$('#auditDomain')?.value||'all',site=$('#auditSite')?.value||'',a=await api(`/api/audit-prep?domain=${encodeURIComponent(domain)}&site=${encodeURIComponent(site)}`),s=a.summary;const gapRows=[];for(const o of a.obligations){if(Number(o.evidence_count)===0||o.status!=='completed'||(o.current_due_date&&days(o.current_due_date)<0))gapRows.push({title:o.title,sub:`${o.site_code||'—'} · ${o.owner||'—'} · ${o.current_due_date?fmtDate(o.current_due_date):'không deadline'}`,why:Number(o.evidence_count)===0?'Thiếu evidence':o.status!=='completed'?'Chưa hoàn thành':'Quá hạn',view:'compliance'})}for(const e of a.equipment){if(e.review_status==='needs_review'||(e.next_inspection_date&&days(e.next_inspection_date)<0))gapRows.push({title:`${e.asset_code} · ${e.name}`,sub:`${e.site_code||'—'} · ${e.location||'—'}`,why:e.review_status==='needs_review'?'Chưa đối chiếu nguồn':'Hết hạn kiểm định',view:'equipment'})}
  $('#app').innerHTML=`<div class="audit-controls no-print"><select id="auditDomain"><option value="all" ${domain==='all'?'selected':''}>Tất cả EHS</option><option value="pccc" ${domain==='pccc'?'selected':''}>PCCC & CNCH</option><option value="chemical" ${domain==='chemical'?'selected':''}>Hóa chất</option><option value="environment" ${domain==='environment'?'selected':''}>Môi trường</option><option value="osh" ${domain==='osh'?'selected':''}>ATVSLĐ / PPE / Kiểm định</option></select><select id="auditSite"><option value="">Tất cả site</option>${state.sites.map(x=>`<option value="${x.code}" ${site===x.code?'selected':''}>${x.code}</option>`).join('')}</select><button class="primary" id="auditExport">⇩ Audit Pack Excel</button><button class="ghost" id="auditPrint">In / PDF</button></div><div class="grid kpis section">${kpi('Evidence coverage',s.evidence_coverage_percent+'%','Tỷ lệ obligation có evidence','#eaf8f2')}${kpi('Obligations',s.obligations,'Trong phạm vi','#edf2ff')}${kpi('Quá hạn',s.overdue,'Cần xử lý','#fff0f1')}${kpi('Thiếu evidence',s.no_evidence,'Gap hồ sơ','#fff6e2')}${kpi('Thiết bị hết hạn',s.equipment_expired,'Inspection','#fff0f1')}${kpi('Open tasks',s.open_tasks,'Task liên quan','#edf2ff')}</div><div class="grid two section"><div class="card panel"><div class="section-head"><div><h2>Gap cần xử lý</h2><p>${esc(a.domain_label)} · ${esc(a.site)}</p></div>${pill(String(gapRows.length),gapRows.length?'amber':'green')}</div><div class="list">${gapRows.slice(0,40).map(g=>`<button class="quality-item auditGo" data-view="${g.view}"><span><b>${esc(g.title)}</b><small class="sub">${esc(g.sub)}</small></span>${pill(g.why,g.why.includes('hạn')?'red':'amber')}</button>`).join('')||'<div class="empty">Không thấy gap nổi bật theo dữ liệu hiện có</div>'}</div></div><div class="card panel"><div class="section-head"><div><h2>Audit inventory</h2><p>Ảnh chụp tình trạng hiện tại</p></div></div><div class="mini-stats"><div><b>${s.documents}</b><span>Documents</span></div><div><b>${s.equipment}</b><span>Equipment</span></div><div><b>${s.equipment_needs_review}</b><span>Need review</span></div><div><b>${s.completed}</b><span>Completed obligations</span></div></div><div class="notice" style="margin-top:12px">Evidence coverage là chỉ số kiểm soát dữ liệu nội bộ, <b>không phải kết luận tuân thủ pháp luật</b>. Audit Pack chỉ tổng hợp các record hiện có trong app.</div></div></div><div class="section card panel audit-table"><div class="section-head"><div><h2>Requirements</h2><p>Evidence / task / deadline theo obligation</p></div></div><div class="table-wrap"><table><thead><tr><th>Site</th><th>Nghĩa vụ</th><th>Owner</th><th>Deadline</th><th>Status</th><th>Progress</th><th>Evidence</th><th>Task mở</th></tr></thead><tbody>${a.obligations.map(o=>`<tr><td>${esc(o.site_code||'—')}</td><td><b>${esc(o.title)}</b><div class="sub">${esc(o.legal_basis||'')}</div></td><td>${esc(o.owner||'—')}</td><td>${fmtDate(o.current_due_date)}</td><td>${statusPill(o.status)}</td><td>${o.progress||0}%</td><td>${o.evidence_count||0}</td><td>${o.open_task_count||0}</td></tr>`).join('')}</tbody></table></div></div>`;
  $('#auditDomain').onchange=$('#auditSite').onchange=()=>auditPrepView();$('#auditExport').onclick=()=>downloadExcelWithParams('audit-pack',{domain,site},$('#auditExport'));$('#auditPrint').onclick=()=>window.print();$$('.auditGo').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
}
async function downloadExcelWithParams(scope,params,btn){const original=btn?.textContent||'Xuất Excel';if(btn){btn.disabled=true;btn.textContent='Đang xuất…'}try{const q=new URLSearchParams({scope,...Object.fromEntries(Object.entries(params).filter(([,v])=>v!=null&&v!==''))}),r=await fetch(`/api/export/excel?${q}`);if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||`HTTP ${r.status}`)}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(r.headers.get('content-disposition')||'').match(/filename="?([^";]+)"?/)?.[1]||`VIETCHEM_EHS_${scope}.xlsx`;a.click();URL.revokeObjectURL(url);toast('Đã xuất Excel')}catch(e){toast(e.message,true)}finally{if(btn){btn.disabled=false;btn.textContent=original}}}
