function reportCenterView(){const y=reportCursor.getFullYear(),m=reportCursor.getMonth()+1;$('#app').innerHTML=`<div class="report-mode-tabs"><button class="${reportMode==='weekly'?'active':''}" data-mode="weekly">Báo cáo tuần</button><button class="${reportMode==='monthly'?'active':''}" data-mode="monthly">Báo cáo tháng</button><button class="${reportMode==='kpi'?'active':''}" data-mode="kpi">KPI tháng</button></div><div class="notice report-manual-note">Nhập trực tiếp theo đúng đầu mục. Khi xuất, hệ thống <b>điền dữ liệu vào chính file mẫu gốc cậu đã gửi</b>, giữ nguyên layout/merge/border/print setup; không dựng lại form mới.</div><div id="reportModeBody"></div>`;$$('.report-mode-tabs button').forEach(b=>b.onclick=()=>{reportMode=b.dataset.mode;reportCenterView()});if(reportMode==='weekly')weeklyReportPane();else if(reportMode==='kpi')kpiReportPane();else monthlyReportPane()}
