function weeklyItemCard(title,kind,i){const plan=kind==='plan';return `<div class="report-entry" data-kind="${kind}" data-index="${i}"><div class="report-entry-title">${esc(title)}</div><div class="report-entry-grid"><div class="field full"><label>${plan?'Hành động/Kế hoạch tuần tới':'Đã thực hiện / Kết quả tuần'}</label><textarea class="r-action" placeholder="VD: ${i===0?'Đã kiểm tra xe 89H-...; thiếu ...; đã cấp bổ sung.':i===3?'Đã làm MSDS cho Ms... SL: ...; rà soát ... MSDS.':'Nhập nội dung thực hiện cụ thể...'}"></textarea></div><div class="field"><label>Người thực hiện</label><input class="r-owner" value="${esc((state.user?.display_name||'').split(' ').slice(-1)[0]||'Thắng')}"></div><div class="field"><label>Nhân sự phối hợp</label><input class="r-collab" placeholder="VD: Hoàng, Đạt"></div>${plan?'':`<div class="field"><label>Tình trạng</label><select class="r-status"><option value="Đạt">Đạt</option><option value="Không đạt">Không đạt</option><option value="Đang thực hiện">Đang thực hiện</option><option value="Không phát sinh">Không phát sinh</option></select></div>`}<div class="field ${plan?'full':''}"><label>Giải trình / Đề xuất / Ghi chú</label><textarea class="r-note"></textarea></div></div></div>`}
function collectWeekly(kind){return $$(`.report-entry[data-kind="${kind}"]`).map((el,i)=>({title:(kind==='plan'?WEEKLY_FORM_ITEMS:WEEKLY_FORM_ITEMS)[i].replace(/^\d+\.\s*/,''),action:$('.r-action',el).value.trim(),owner:$('.r-owner',el).value.trim(),collaborator:$('.r-collab',el).value.trim(),status:$('.r-status',el)?.value||'',note:$('.r-note',el).value.trim()}))}
function weeklyReportPane(){const body=$('#reportModeBody'),d=new Date(),iso=d.toISOString().slice(0,10);body.innerHTML=`<div class="report-controls">${reportPersonFields()}<button class="primary" id="weeklyExport">⇩ Xuất báo cáo tuần</button><button class="ghost" id="weeklyTemplate">Mẫu gốc</button></div><div class="grid two report-range-grid"><div class="card panel"><h3>I. Kết quả thực hiện tuần</h3><div class="form-grid"><div class="field"><label>Từ ngày</label><input id="weekResultStart" type="date" value="${iso}"></div><div class="field"><label>Đến ngày</label><input id="weekResultEnd" type="date" value="${iso}"></div></div></div><div class="card panel"><h3>II. Kế hoạch tuần tiếp theo</h3><div class="form-grid"><div class="field"><label>Từ ngày</label><input id="weekPlanStart" type="date" value="${iso}"></div><div class="field"><label>Đến ngày</label><input id="weekPlanEnd" type="date" value="${iso}"></div></div></div></div><details class="report-form-section" open><summary>I. Kết quả thực hiện công việc tuần</summary><div class="report-entry-list">${WEEKLY_FORM_ITEMS.map((x,i)=>weeklyItemCard(x,'result',i)).join('')}</div></details><details class="report-form-section"><summary>II. Kế hoạch công việc tuần tiếp theo</summary><div class="report-entry-list">${WEEKLY_FORM_ITEMS.map((x,i)=>weeklyItemCard(x,'plan',i)).join('')}</div></details>`;$('#weeklyTemplate').onclick=()=>downloadTemplate('weekly',$('#weeklyTemplate'));$('#weeklyExport').onclick=()=>postManualReport({type:'weekly',...reportIdentity(),resultStart:reportDate($('#weekResultStart').value),resultEnd:reportDate($('#weekResultEnd').value),planStart:reportDate($('#weekPlanStart').value),planEnd:reportDate($('#weekPlanEnd').value),resultItems:collectWeekly('result'),planItems:collectWeekly('plan')},$('#weeklyExport'))}
function monthWeekLabels(year,month){const last=new Date(year,month,0).getDate(),out=[];let start=1,n=1;while(start<=last&&n<=5){const end=Math.min(start+6,last);out.push(`Tuần ${n} (${String(start).padStart(2,'0')}/${String(month).padStart(2,'0')} - ${String(end).padStart(2,'0')}/${String(month).padStart(2,'0')}/${year})`);start=end+1;n++}return out}
function monthlyItemCard(title,w,i){return `<div class="report-entry monthly-entry" data-week="${w}" data-index="${i}"><div class="report-entry-title">${esc(title)}</div><div class="report-entry-grid"><div class="field full"><label>Nội dung/Kết quả công việc</label><textarea class="m-work" placeholder="Nhập nội dung đã thực hiện, tiến độ, khối lượng, chất lượng..."></textarea></div><div class="field"><label>Kết quả công việc (KQ)</label><select class="m-result"><option>Đã hoàn thành</option><option>Còn lại phải HT</option><option>Cần TH trong tháng kế tiếp</option><option>Không phát sinh</option></select></div><div class="field"><label>Đánh giá KQ</label><select class="m-eval"><option>Đã TH</option><option>Được duyệt</option><option>Còn phải TH</option><option>Chưa đánh giá</option></select></div><div class="field full"><label>Đánh giá / Diễn giải chi tiết</label><textarea class="m-detail"></textarea></div><div class="field full"><label>Đề xuất giải pháp hoàn thành công việc</label><textarea class="m-solution"></textarea></div></div></div>`}
function collectMonthly(){return $$('.monthly-week').map((week,w)=>({label:$('.month-week-label',week).value.trim(),items:$$('.monthly-entry',week).map((el,i)=>({title:MONTHLY_FORM_ITEMS[i].replace(/^\d+\.\s*/,''),work:$('.m-work',el).value.trim(),result:$('.m-result',el).value,evaluation:$('.m-eval',el).value,detail:$('.m-detail',el).value.trim(),solution:$('.m-solution',el).value.trim()}))}))}
function monthlyReportPane(){const y=reportCursor.getFullYear(),m=reportCursor.getMonth()+1,body=$('#reportModeBody'),labels=monthWeekLabels(y,m).slice(0,4);while(labels.length<4)labels.push(`Tuần ${labels.length+1}`);body.innerHTML=`<div class="report-controls"><select id="reportMonth">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${m===i+1?'selected':''}>Tháng ${i+1}</option>`).join('')}</select><input id="reportYear" type="number" min="2020" max="2100" value="${y}">${reportPersonFields()}<button class="primary" id="reportExport">⇩ Xuất báo cáo tháng</button><button class="ghost" id="reportTemplate">Mẫu gốc</button></div><div id="monthWeeks">${labels.map((label,w)=>`<details class="report-form-section monthly-week" ${w===0?'open':''}><summary><input class="month-week-label" value="${esc(label)}" aria-label="Tên tuần"></summary><div class="report-entry-list">${MONTHLY_FORM_ITEMS.map((x,i)=>monthlyItemCard(x,w,i)).join('')}</div></details>`).join('')}</div>`;const redraw=()=>{const yy=Number($('#reportYear').value),mm=Number($('#reportMonth').value);reportCursor=new Date(yy,mm-1,1);const labels=monthWeekLabels(yy,mm).slice(0,4);while(labels.length<4)labels.push(`Tuần ${labels.length+1}`);$('#monthWeeks').innerHTML=labels.map((label,w)=>`<details class="report-form-section monthly-week" ${w===0?'open':''}><summary><input class="month-week-label" value="${esc(label)}" aria-label="Tên tuần"></summary><div class="report-entry-list">${MONTHLY_FORM_ITEMS.map((x,i)=>monthlyItemCard(x,w,i)).join('')}</div></details>`).join('')};$('#reportMonth').onchange=$('#reportYear').onchange=redraw;$('#reportTemplate').onclick=()=>downloadTemplate('monthly',$('#reportTemplate'));$('#reportExport').onclick=()=>postManualReport({type:'monthly',year:Number($('#reportYear').value),month:Number($('#reportMonth').value),...reportIdentity(),weeks:collectMonthly()},$('#reportExport'))}
function kpiScoreOptions(){return ['','0','0.5','1','1.5','2','2.5','3','3.5','4'].map(x=>`<option value="${x}">${x===''?'Chọn điểm':x}</option>`).join('')}
function updateKpiManualSummary(){const scores=$$('.kpi-score').map(x=>x.value===''?null:Number(x.value)),weights=KPI_FORM_ITEMS.map(x=>x.weight),ready=scores.every(x=>x!==null),ded1=Math.max(0,Number($('#kpiDiscipline')?.value||0)),ded2=Math.max(0,Number($('#kpiProfessional')?.value||0));if(!ready){$('#kpiManualSummary').innerHTML='<span class="muted">Chọn đủ điểm 9 chỉ tiêu để xem tổng KPI.</span>';return}const weighted=scores.reduce((a,v,i)=>a+v*weights[i],0),avg=weighted/weights.reduce((a,b)=>a+b,0),objective=avg/3*100,action=Math.max(0,100-ded1-ded2),final=objective*.7+action*.3,rating=final>=90?'A':final>=80?'B':final>=70?'C':'D';$('#kpiManualSummary').innerHTML=`<b>Điểm mục tiêu quy đổi:</b> ${objective.toFixed(2)}% · <b>Điểm hành động:</b> ${action.toFixed(2)} · <b>KPI:</b> ${final.toFixed(2)} · <b>Xếp loại:</b> ${rating}`}
function collectKpi(){return $$('.kpi-manual-row').map((el,i)=>({note:$('.kpi-note',el).value.trim(),result:$('.kpi-result',el).value.trim(),score:$('.kpi-score',el).value===''?null:Number($('.kpi-score',el).value)}))}
function kpiReportPane(){const y=reportCursor.getFullYear(),m=reportCursor.getMonth()+1,body=$('#reportModeBody');body.innerHTML=`<div class="report-controls"><select id="kpiMonth">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${m===i+1?'selected':''}>Tháng ${i+1}</option>`).join('')}</select><input id="kpiYear" type="number" min="2020" max="2100" value="${y}">${reportPersonFields()}<button class="primary" id="kpiExport">⇩ Xuất KPI</button><button class="ghost" id="kpiTemplate">Mẫu gốc</button></div><div class="table-wrap kpi-manual-table"><table><thead><tr><th>TT</th><th>Nội dung công việc</th><th>Mục tiêu</th><th>ĐVT</th><th>Trọng số</th><th>Ghi chú</th><th>Kết quả thực hiện</th><th>Điểm</th></tr></thead><tbody>${KPI_FORM_ITEMS.map((x,i)=>`<tr class="kpi-manual-row"><td>${i+1}</td><td><b>${esc(x.work)}</b></td><td>${esc(x.target)}</td><td>${esc(x.unit)}</td><td>${x.weight}</td><td><textarea class="kpi-note"></textarea></td><td><textarea class="kpi-result" placeholder="VD: 12 lượt/11 xe; 3 lần theo xe..."></textarea></td><td><select class="kpi-score">${kpiScoreOptions()}</select></td></tr>`).join('')}</tbody></table></div><div class="card panel section"><div class="form-grid"><div class="field"><label>Điểm trừ tuân thủ kỷ luật</label><input id="kpiDiscipline" type="number" min="0" max="100" step="0.5" value="0"></div><div class="field"><label>Điểm trừ chuyên môn nghiệp vụ</label><input id="kpiProfessional" type="number" min="0" max="100" step="0.5" value="0"></div></div><div id="kpiManualSummary" class="notice" style="margin-top:12px">Chọn đủ điểm 9 chỉ tiêu để xem tổng KPI.</div></div>`;$$('.kpi-score').forEach(x=>x.onchange=updateKpiManualSummary);$('#kpiDiscipline').oninput=$('#kpiProfessional').oninput=updateKpiManualSummary;$('#kpiMonth').onchange=$('#kpiYear').onchange=()=>{reportCursor=new Date(Number($('#kpiYear').value),Number($('#kpiMonth').value)-1,1)};$('#kpiTemplate').onclick=()=>downloadTemplate('kpi',$('#kpiTemplate'));$('#kpiExport').onclick=()=>postManualReport({type:'kpi',year:Number($('#kpiYear').value),month:Number($('#kpiMonth').value),...reportIdentity(),items:collectKpi(),disciplineDeduction:Number($('#kpiDiscipline').value||0),professionalDeduction:Number($('#kpiProfessional').value||0)},$('#kpiExport'))}
function captureTargetOptions(type,rows){if(type==='equipment')return rows.map(x=>`<option value="${x.id}" data-site="${x.site_id||''}">${esc(x.asset_code)} · ${esc(x.name)}</option>`).join('');if(type==='obligation')return rows.map(x=>`<option value="${x.id}" data-site="${x.site_id||''}">${esc(x.site_code||'—')} · ${esc(x.title)}</option>`).join('');return ''}
async function quickCapture(){if(!can('tasks.write')&&!can('documents.write'))return toast('Tài khoản không có quyền Quick Capture',true);const [eq,obs]=await Promise.all([can('equipment.read')?api('/api/equipment'):Promise.resolve([]),can('compliance.read')?api('/api/obligations'):Promise.resolve([])]);modal('Quick Capture',`<div class="form-grid"><div class="field full"><label>Loại ghi nhận</label><select id="capMode"><option value="finding">Finding / việc hiện trường</option><option value="task">Task nhanh</option>${eq.length?'<option value="equipment">Ảnh / evidence thiết bị</option>':''}${obs.length?'<option value="obligation">Evidence Compliance</option>':''}</select></div><div class="field full" id="capTargetWrap" hidden><label>Đối tượng</label><select id="capTarget"></select></div><div class="field full" id="capTitleWrap"><label>Nội dung *</label><input id="capTitle" placeholder="VD: Pallet hóa chất thiếu nhãn cảnh báo"></div><div class="field"><label>Site</label><select id="capSite"><option value="">Chung</option>${state.sites.map(s=>`<option value="${s.id}">${s.code}</option>`).join('')}</select></div><div class="field"><label>Deadline</label><input id="capDue" type="date"></div><div class="field"><label>Priority</label><select id="capPriority"><option value="medium">Medium</option><option value="high">High</option><option value="low">Low</option></select></div><div class="field"><label>Trạng thái</label><select id="capStatus"><option value="in_progress">Đang thực hiện</option><option value="not_started">Chưa bắt đầu</option><option value="blocked">Bị chặn</option></select></div><div class="field full"><label>Ảnh / file</label><input id="capFile" type="file" accept="image/*,.pdf,.doc,.docx,.xls,.xlsx" capture="environment"><div class="sub">Trên điện thoại có thể chụp ảnh trực tiếp.</div></div><div class="field full"><label>Ghi chú</label><textarea id="capNote"></textarea></div></div>`,async close=>{const mode=$('#capMode').value,file=$('#capFile').files[0],note=$('#capNote').value;if(mode==='finding'||mode==='task'){if(!$('#capTitle').value.trim())throw new Error('Nhập nội dung');const out=await api('/api/tasks',{method:'POST',body:JSON.stringify({title:$('#capTitle').value,category:mode==='finding'?'Finding':'Quick Capture',site_id:$('#capSite').value||null,owner:state.user?.display_name||'EHS',due_date:$('#capDue').value||null,priority:$('#capPriority').value,status:$('#capStatus').value,notes:note})});if(file&&can('documents.write')){const doc=await uploadRawDocument(file,mode==='finding'?'osh':'other',$('#capSite').value||null,'task',out.id);await api('/api/evidence/link',{method:'POST',body:JSON.stringify({document_id:doc.id,entity_type:'task',entity_id:out.id,evidence_type:'quick_capture',note})})}}else{if(!file)throw new Error('Chọn ảnh/file');const id=$('#capTarget').value,target=mode==='equipment'?eq.find(x=>x.id===id):obs.find(x=>x.id===id),siteId=target?.site_id||$('#capSite').value||null,cat=mode==='equipment'?'equipment':'compliance';const doc=await uploadRawDocument(file,cat,siteId,mode,id);await api('/api/evidence/link',{method:'POST',body:JSON.stringify({document_id:doc.id,entity_type:mode,entity_id:id,evidence_type:'quick_capture',note})})}close();toast('Quick Capture đã lưu');if(state.view==='myday')myDay()},'Lưu ghi nhận');setTimeout(()=>{const mode=$('#capMode'),targetWrap=$('#capTargetWrap'),target=$('#capTarget'),titleWrap=$('#capTitleWrap');const redraw=()=>{const m=mode.value,isTarget=['equipment','obligation'].includes(m);targetWrap.hidden=!isTarget;titleWrap.hidden=isTarget;if(m==='equipment')target.innerHTML=captureTargetOptions('equipment',eq);if(m==='obligation')target.innerHTML=captureTargetOptions('obligation',obs)};mode.onchange=redraw;redraw()},0)}
function showEquipmentQr(id){const e=state.equipment.find(x=>x.id===id);if(!e)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><strong>QR thiết bị · ${esc(e.asset_code)}</strong><button class="x">×</button></div><div class="modal-body"><div class="qr-card"><img src="/api/equipment/qr?id=${encodeURIComponent(id)}" alt="QR ${esc(e.asset_code)}"><div><h3>${esc(e.name)}</h3><div class="sub">${esc(e.asset_code)} · ${esc(e.serial_no||'—')} · ${esc(e.site_code||'—')} · ${esc(e.location||'—')}</div><div class="notice" style="margin-top:12px">QR mở trực tiếp asset trong VIETCHEM EHS. Nếu quét bằng điện thoại, hãy mở app bằng địa chỉ IP/LAN của máy chủ (hoặc cấu hình <code>EHS_PUBLIC_BASE_URL</code>) trước khi tạo QR.</div><div class="actions" style="margin-top:12px"><a class="primary button-link" href="/api/equipment/qr?id=${encodeURIComponent(id)}" download="${esc(e.asset_code)}_QR.svg">Tải QR SVG</a></div></div></div></div></div></div>`;$('.x').onclick=()=>$('#modalRoot').innerHTML=''}
